#!/usr/bin/env python3
"""3단계 성능 — 선형·어텐션 커널들의 글 소스(커널.gl)를 만든다. 누적 변수가 수십 개라 손으로 쓰면 틀리기 쉬워서 만든다.

  python research/gpu/3단계/커널생성.py            (커널.gl · 커널반.gl · 커널반F16.gl · 커널반Q8.gl · 커널반Q4.gl · 커널프롬.gl)
  python research/gpu/3단계/커널생성.py -o 파일.gl   (짧은실수 KV 판 하나만 — 대조용)

7단계: 모형의 크기(너비 · 머리 수 · 층 수 · 확장 폭 · 낱말 수)가 매개변수다 — source(…, 크기="XL") 가 커널XL.gl · 커널XL반F16.gl ·
커널XL반Q8정수.gl · 커널XL반Q4정수.gl 을, gpt2_source("XL") 이 gpt2XL.gl 을 만든다. 기본(small)의 출력은 바꾸기 전과 바이트까지 같다.

커널반F16.gl · 커널반Q8.gl · 커널반Q4.gl (5단계 — 양자화: 밝힌 손실만): 가중치를 GGUF 의 형식(F16 · Q8_0 · Q4_0)으로 GPU 에 두고 커널
안에서 정확히 풀어 같은 순서로 곱해더하는 판(반실수 KV). 배치와 푸는 식은 아래 "가중치의 형식" 의 설명. 선형 판 다섯 · 로짓 판 넷 ·
임베딩 · 생성메가가 형식에 따라 다르고, 어텐션은 커널반.gl 과 같다.

커널반.gl (4단계 2 — 밝힌 정밀도): KV 캐시를 반실수로 둔 판. c_attn 의 끝손질이 키·값을 `으로 반실수` 로 좁혀 쓰고(반올림 한 번 —
소스가 밝힌 것), 어텐션은 읽어서 넓혀(정확) 짧은실수로 계산한다. 키의 배치는 [머리][조각][d][위치 64] — 조각 하나(8 KB)가 붙어 있어
생성의 어텐션이 띄엄띄엄 읽지 않는다(값과는 상관없다). 그 밖의 커널과 순서 약속은 커널.gl 과 같다.

순서의 약속 (모든 판이 지킨다 — 그래서 어느 판으로, 몇 행을 함께 계산해도 칸마다 비트가 같다):
  p_g      = Σ 입력[r, k] · 가중치[k, n]   (k ≡ g mod 4, k 오름차순, 곱해더하기로 차례로 — 반올림 한 번씩)   g = 0 … 3
  출력[r, n] = 끝손질( ((p₀ + p₂) + (p₁ + p₃)) + 치우침[n] )
가닥 넷은 cuBLAS 와 같은 큰 타일(스레드 하나가 8 × 8 칸)을 허락하면서, 토큰 하나를 계산할 때(행 하나)도 열마다 사슬이 넷이라 메모리를
충분히 동시에 읽을 수 있게 고른 수다. 판:
  타일선형·타일선형넷 — 블록 하나(256 스레드 = 가닥 4 × 64)가 64 × 64 칸. k 를 32 줄씩 공유 메모리 세 판에 앞서 올린다
                     (넷 = 가중치를 16 바이트 비동기복사로 — 열수가 64 의 배수일 때 — 그리고 입력은 16 바이트 읽기로 레지스터를 거쳐 한
                     조각 앞서 판에 뒤집어 둔다(레지): 4 바이트 비동기복사 2048 번으로 옮기던 판은 옮기기만으로 cuBLAS 전체 시간이 들었다).
  작은타일선형         — 32 × 32 칸(블록이 적게 나오는 모양). 입력은 같은 레지스터 길로.
  줄선형R             — 행 R 개(1 또는 4)를 블록 하나(128 스레드 = 가닥 4 × 열 32)가 열 32 개씩. 깊은줄선형1 은 가중치를 48 개씩 먼저 읽는다.
  생성메가             — 토큰 생성(배치 1) 전체를 커널 하나로(아래).
끝손질: 그대로 / _잔차(잔차 + 값) / _겔루(tanh 근사 GELU) / _KV(열 0..767 은 q 로 출력에, 768.. 은 키칸, 1536.. 은 값칸의 캐시 자리에).
KV 캐시(층마다): 키는 [문장][머리][d][위치](전치 — 생성의 점수가 위치 순으로 붙여 읽는다), 값은 [문장][머리][위치][d].

어텐션의 순서 약속 (질의 하나 — 위치 p, 머리 h). 키를 위치 64 개씩의 조각 σ = 0 … ⌊p/64⌋ 로 나눈다(조각 σ 의 키
t = 64σ … min(64σ + 63, p)):
  s_t  = (Σ_d q_d · k_td, d 오름차순 곱해더하기) × 0.125
  m_σ  = max_{t∈σ} s_t (어느 순서로 구해도 같다),   e_t = 근사지수(s_t − m_σ)
  l_σ  = Σ_{t∈σ} e_t (t 오름차순, 0 에서부터 더하기),   o_σd = Σ_{t∈σ} e_t · v_td (t 오름차순 곱해더하기)
  접기 — (M, L, O) = (m₀, l₀, o₀), 그다음 σ = 1, 2, … 차례로: M' = max(M, m_σ), 가 = 근사지수(M − M'), 나 = 근사지수(m_σ − M'),
         L = 곱해더하기(l_σ, 나, L·가), O_d = 곱해더하기(o_σd, 나, O_d·가), M = M'
  출력_d = O_d / L
조각 안은 짧은 사슬이고 조각들은 위치 순서대로 접히므로, 프롬프트 처리는 점수를 한 번만 계산하고(점수 표를 두지 않는다) 생성은 조각을
여러 블록이 나눠 맡을 수 있다. 판: 흐름어텐션(프롬프트 — 블록 하나가 질의 64 개, 조각마다 한 번에), 조각어텐션 + 조각접기(생성 —
조각을 블록들이 나눠 맡고 차례로 접는다), 메가커널 안의 어텐션(같은 계산 — 머리마다 마지막에 도착한 블록이 접는다).
"""
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
끝손질들 = ("", "_잔차", "_겔루", "_KV")
# KV 캐시의 원소 타입: "짧은실수"(커널.gl) 또는 "반실수"(커널반.gl). source(KV) 가 정한다.
KV = "짧은실수"
# 가중치의 형식 (5단계 — 양자화: 밝힌 손실만): 층의 선형 가중치(층형식)와 낱말표(낱말형식) — "짧은실수"(그대로) · "F16" · "Q8_0" ·
# "Q4_0". source(…) 가 정한다. 양자 형식은 GGUF 의 블록(열 하나의 k 32 줄 — 값 32 개)을 블록 평면 배치로 다시 깔아 둔 것이다(값은
# 그대로 — 호스트가 깐다, 5단계/gguf읽기.py):
#   칸 (kb, g, n) = 열 n 의 k = 32·kb + g + 4i (i < 8) 여덟 값 — 가닥 g 의 스레드가 맡는 값들. 칸 번호 e = (kb·4 + g)·N + n
#   (열이 붙어 있어 워프가 한 번에 읽는다).
#   Q4_0 — 칸마다 중간정수 하나(자리 e): 바이트 i' (< 4) 가 GGUF 블록의 qs[g + 4i'], 값 i < 4 는 ((w >> 8i) & 15) − 8,
#          i ≥ 4 는 ((w >> (8(i − 4) + 4)) & 15) − 8.
#   Q8_0 — 칸마다 중간정수 둘(평면 h 의 자리 (kb·8 + g·2 + h)·N + n): 바이트 i' 가 qs[g + 4(4h + i')] + 128, 값 4h + i' 는
#          ((w_h >> 8i') & 255) − 128.
#   F16  — 칸마다 반실수 여덟(자리 e·8 + i).
#   척도(Q4_0 · Q8_0) — 반실수, 자리 kb·N + n.   값 = (정수 으로 짧은실수) × 척도 — 정확하다.
# 그래서 같은 가중치를 미리 풀어 짧은실수로 둔 판과 곱해더하는 값·순서가 같고, 로짓이 비트까지 같다(5a).
층형식 = "짧은실수"
낱말형식 = "짧은실수"
# 양자 형식의 순서 약속: "가닥"(5단계 — 블록 평면 배치, 가닥 넷의 곱해더하기) 또는 "정수"(6단계 — 정수 블록 계약, 아래 설명).
계약 = "가닥"
# 정수 블록 계약의 활성값 자리 수(8단계): 4 (30 비트 — 6단계) 또는 2 (14 비트 — 자리 둘). source(…, 자리수=…) 가 정한다.
자리수 = 4
# 자리 둘 타일의 끝 계산 길(값은 셋 다 같다 — 번갈아 재서 고름, XL c_fc 행 1024): "cvt"(정수 → 실수 변환 — 47%), "마법둘"(마법수 덧셈 둘 —
# 42%), "누적"(마법수를 mma 의 누적 입력으로 — 39%, 레지스터 넘침). 명령 수가 적은 길이 느렸다 — 발행이 아니라 다른 것이 묶는다.
둘자리길 = "cvt"
# 모형의 크기(7단계 — GPT-2 XL): 너비(D) · 머리 수(머리 하나 64 칸) · 층 수 · 확장 폭(FFN) · 낱말 수. source(…, 크기=…) 가 바꾸고
# 되돌린다 — 기본은 GPT-2 small 이라 그 소스는 바꾸기 전과 같다(크기가 다를 때만 다른 줄이 나온다).
너비, 머리수, 층수, 확장폭, 낱말수 = 768, 12, 12, 3072, 50257
크기들 = {"small": (768, 12, 12, 3072, 50257), "XL": (1600, 25, 48, 6400, 50257)}


def 작은가():
    """GPT-2 small 의 크기인가 — 그때는 이전 단계의 소스를 바이트까지 그대로 낸다."""
    return (너비, 머리수, 층수, 확장폭, 낱말수) == 크기들["small"]


def 좁힘(v):
    """KV 캐시에 쓰는 값 — 반실수 판이면 밝혀서 좁힌다(가까운 쪽 반올림, 넘치면 오류 칸에 4)."""
    return v if KV == "짧은실수" else f"({v}) 으로 반실수"


def 키자리(바탕, 열d, 위치):
    """키 칸의 자리 — 열d = 머리·64 + d (식), 위치 = 그 행의 위치(식). 짧은실수 판: [머리][d][위치](전치),
    반실수 판: [머리][조각][d][위치 64] (조각 = 위치 / 64)."""
    if KV == "짧은실수":
        return f"{바탕} + ({열d}) * 최대길이 + {위치}"
    # 열d · 위치는 음이 아니다 — / 64 · % 64 를 >> 6 · & 63 으로(같은 값; 나눗셈은 64 비트 정수면 GPU 에서 비싸다)
    return f"{바탕} + (({열d}) >> 6) * 64 * 최대길이 + ({위치} >> 6) * 4096 + (({열d}) & 63) * 64 + ({위치} & 63)"


def 와과(말):
    """말 뒤의 동반 조사 — 받침이 있으면 '과', 없으면 '와'."""
    c = ord(말[-1]) - 0xAC00
    return "과" if 0 <= c < 11172 and c % 28 else "와"


def 가중선언(값, 척, 형식):
    """가중치 매개변수의 선언(뒤 조사까지). 짧은실수 · F16 은 하나, Q8_0 · Q4_0 은 값(중간정수)과 척도(반실수) 둘."""
    if 형식 == "짧은실수":
        return f"짧은실수 참조 {값}{와과(값)} "
    if 형식 == "F16":
        return f"반실수 참조 {값}{와과(값)} "
    return f"중간정수 참조 {값}{와과(값)} 반실수 참조 {척}{와과(척)} "


def 층크기(형식, K, N):
    """양자 가중치 한 층의 (값 바이트, 척도 바이트) — 호스트가 층마다 [값][척도] 를 이어 둔다."""
    return {"Q4_0": K * N // 2, "Q8_0": K * N, "F16": 2 * K * N}[형식], (0 if 형식 == "F16" else K * N // 16)


def 층크기정수(형식, K, N):
    """6단계 정수 배치의 한 층 (값 바이트, 척도 바이트) — 척도는 [블록][척도폭] (척도폭 = N 을 64 로 올림)."""
    Np = (N + 63) // 64 * 64
    return (K * N if 형식 == "Q8_0" else K * N // 2), (K // 32) * Np * 2


def 칸자리(형식, g, n, N):
    """블록 평면 배치에서 칸 (kb = 0, g, n) 의 값 자리(식)와 kb 가 하나 늘 때의 걸음 — 값 배열의 원소 단위. N 은 식이거나 수."""
    곱 = (lambda a: str(a * N)) if isinstance(N, int) else (lambda a: f"{a} * {N}")
    if 형식 == "Q4_0":
        return f"{g} * {N} + {n}", 곱(4)
    if 형식 == "Q8_0":
        return f"{g} * {곱(2)} + {n}", 곱(8)
    return f"({g} * {N} + {n}) * 8", 곱(32)


def 칸선언(형식, q, ind):
    """칸 하나를 받을 레지스터 — Q4_0: 중간정수 q, Q8_0: q_0 · q_1 (평면 둘), F16: 반실수 q_0 … q_7 (쓸 때 정확히 넓힌다).
    Q 형식의 척도는 짧은실수 qd (반실수를 정확히 넓혀)."""
    if 형식 == "Q4_0":
        return [f"{ind}중간정수 {q} = 0.", f"{ind}짧은실수 {q}d = 0 으로 짧은실수."]
    if 형식 == "Q8_0":
        return [f"{ind}중간정수 {q}_0 = 0.", f"{ind}중간정수 {q}_1 = 0.", f"{ind}짧은실수 {q}d = 0 으로 짧은실수."]
    return [f"{ind}반실수 {q}_{i} = (0 으로 짧은실수) 으로 반실수." for i in range(8)]


def 칸읽기(형식, 값, 척, 자리, 척자리, q, ind, N):
    """칸 하나(값 자리 자리, 척도 자리 척자리 — 식)를 칸선언 의 레지스터로. Q8_0 의 둘째 평면은 자리 + N."""
    if 형식 == "Q4_0":
        return [f"{ind}{q} = {값}[{자리}].", f"{ind}{q}d = {척}[{척자리}]."]
    if 형식 == "Q8_0":
        return [f"{ind}{q}_0 = {값}[{자리}].", f"{ind}{q}_1 = {값}[{자리} + {N}].", f"{ind}{q}d = {척}[{척자리}]."]
    return [f"{ind}{q}_{i} = {값}[{자리} + {i}]." for i in range(8)]


def 칸값식(형식, q, i):
    """칸의 여덟 값 중 i 번째(k = 32·kb + g + 4i) — 짧은실수 식. 정수의 범위([−8, 7] · [−128, 127])는 백엔드가 증명하고(그래서 빠른
    변환), 정수 → 짧은실수 와 척도를 곱한 값은 정확하다(가수 15 · 19 비트 이하) — 미리 풀어 둔 짧은실수 가중치와 같은 값."""
    if 형식 == "F16":
        return f"{q}_{i}"
    if 형식 == "Q4_0":
        s = 8 * i if i < 4 else 8 * (i - 4) + 4
        w = f"({q} >> {s})" if s else q
        return f"((({w} & 15) - 8) 으로 짧은실수) * {q}d"
    s = 8 * (i % 4)
    w = f"({q}_{i // 4} >> {s})" if s else f"{q}_{i // 4}"
    return f"((({w} & 255) - 128) 으로 짧은실수) * {q}d"


def 머리(epi, 미리=False, 형식=None):
    p = "짧은실수 참조 입력에서 " + 가중선언("가중치", "척도", 형식 or 층형식) + "짧은실수 참조 치우침과 "
    if epi == "_잔차":
        p += "짧은실수 참조 잔차와 "
    if epi == "_KV":
        p += f"{KV} 참조 키칸과 {KV} 참조 값칸과 "
    p += "짧은실수 참조 출력에 정수 행수로 정수 깊이로 정수 열수로"
    if epi == "_KV":
        p += " 정수 묶음안행수로 정수 위치시작으로 정수 최대길이로"
    if 미리:
        p += " 짧은실수 참조 다음을 정수 다음수로"
    return p


def 끝(epi, v, 행, 열, 자리, ind, 칸=None):
    """값 v(치우침까지 더한 것)를 행·열에 쓰는 끝손질. 자리 = KV 캐시의 행 바탕(행마다 한 번 구해 둔 것). 칸 = 출력 · 잔차의
    자리를 미리 구해 둔 식(없으면 행 * 열수 + 열 — _KV 밖에서만)."""
    칸 = 칸 or f"{행} * 열수 + {열}"
    if epi == "":
        return [f"{ind}출력[{칸}] = {v}."]
    if epi == "_잔차":
        return [f"{ind}출력[{칸}] = 잔차[{칸}] + {v}."]
    if epi == "_겔루":
        return [f"{ind}u = 0.7978845608 * ({v} + 0.044715 * {v} * {v} * {v}).",
                f"{ind}th = 1.0 - 2.0 / (근사지수(2.0 * u) + 1.0).",
                f"{ind}출력[{칸}] = 0.5 * {v} * (1.0 + th)."]
    return [f"{ind}{열} < {너비}이면 {{ 출력[{행} * {너비} + {열}] = {v}. }}",
            f"{ind}아니면 {열} < {2 * 너비}이면 {{ 키칸[{키자리(자리, f'{열} - {너비}', '자리위')}] = {좁힘(v)}. }}",
            f"{ind}아니면 {{ 값칸[{자리} + (({열} - {2 * 너비}) / 64) * 최대길이 * 64 + 자리위 * 64 + ({열} - {2 * 너비}) % 64] = {좁힘(v)}. }}"]


def 자리두기(행, ind):
    """행의 KV 캐시 자리: 자리 = 문장 · 768 · 최대길이, 자리위 = 위치시작 + 행 % 묶음안행수. 문장이 하나면 나눗셈을 건너뛴다(값은 같다)."""
    return [f"{ind}묶음안행수 >= 행수이면 {{ 자리 = 0. 자리위 = 위치시작 + {행}. }}",
            f"{ind}아니면 {{ 자리 = ({행} / 묶음안행수) * {너비} * 최대길이. 자리위 = 위치시작 + {행} % 묶음안행수. }}"]


def 타일선형(epi, 넷=False, 이름=None, 레지=False):
    """64 × 64 칸을 블록 하나(256 스레드 = 가닥 4 × 64)가. k 를 32 줄씩, 공유 메모리 세 판에 비동기복사로 두 조각 앞서 올린다.
    스레드 하나가 8 × 8 칸 — 행 {ty·4 + r, 32 + ty·4 + r}, 열 {tx·4 + c, 32 + tx·4 + c} (r, c < 4). 이렇게 두면 스레드가 읽는
    입력·가중치 조각이 네 칸씩 붙어 있어서 컴파일러가 네 칸 묶어 읽기(ld.shared.v4)로 낸다.
    판: 입력 [판 3][k 32][행 64] — 자리 (k, m) 는 m ^ s(k), s(k) = 8·((k/8) % 4) (옮겨 쓸 때 뱅크가 겹치지 않게 비튼다),
        가중치 [판 3][k 32][열 64].
    넷 = 참: 가중치를 16 바이트씩 옮긴다 — 열수가 64 의 배수이고 가중치의 시작이 16 바이트 정렬일 때만(호스트가 확인한다).
    레지 = 참: 입력 조각을 스레드마다 16 바이트 읽기 둘로 레지스터에 받아 다음 조각을 계산하는 동안 들고 있다가 판에 뒤집어 쓴다
    (깊이가 4 의 배수라는 약속 — 깊이4 = 깊이 / 4 · 4 로 컴파일러에 알린다)."""
    I8, J8 = range(8), range(8)
    BK, AB, BB = 32, 32 * 64, 32 * 64
    B0 = 3 * AB
    판 = "공유판48"
    이름 = 이름 or f"타일선형{'넷' if 넷 else ''}{epi}"

    def 올리기(판번호, ind):
        """a원·b원 이 가리키는 조각을 판 번호(식)에 비동기로 올린다."""
        out = [f"{ind}올판 = {판번호}."]
        if not 레지:
            out += [f"{ind}비동기복사(판 에, 올판 * {AB} + a저장 + {64 * e} 를, 입력 에서, a원 + {e} 로)." for e in range(8)]
        if 넷:
            out += [f"{ind}비동기복사16(판 에, {B0} + 올판 * {BB} + b저장 를, 가중치 에서, b원 로).",
                    f"{ind}비동기복사16(판 에, {B0} + 올판 * {BB} + b저장 + 1024 를, 가중치 에서, b원 + 열16 로)."]
        else:
            out += [f"{ind}비동기복사(판 에, {B0} + 올판 * {BB} + b저장 + {(e // 2) * 64 + 32 * (e % 2)} 를, 가중치 에서, "
                    f"b원{e % 2} + 열줄{e // 2} 로)." for e in range(8)]
        return out

    def 다음(ind):
        out = [] if 레지 else [f"{ind}a원 = a원 + {BK}."]
        out += [f"{ind}b원 = b원 + 열32."] if 넷 else [f"{ind}b원0 = b원0 + 열32.", f"{ind}b원1 = b원1 + 열32."]
        return out

    def 읽기A(ind):
        """입력 조각(행 64 × k 32)을 레지스터로 — 스레드마다 두 행(ar0, ar0 + 32)의 네 칸씩, 16 바이트 읽기 둘."""
        return [f"{ind}ra{h}_{u} = 입력[ra원{h} + {u}]." for h in range(2) for u in range(4)]

    def 쓰기A(판식, ind):
        """레지스터의 입력 조각을 판의 [k][행 ^ s(k)] 자리에 (가닥마다 네 행씩 붙여 읽을 수 있게 뒤집어 둔다)."""
        return [f"{ind}판[{판식} + 저a + {u * 64 + 32 * h}] = ra{h}_{u}." for h in range(2) for u in range(4)]

    L = [f"(* 64 × 64 칸을 블록 하나가 — 가닥 g 의 스레드 64 개가 k ≡ g (mod 4) 를 맡고, 스레드 하나가 8 × 8 칸. 커널생성.py 의 설명 *)",
         f"(* 실행한도 {이름} 256 2 *)",
         f"[{머리(epi)} {이름}]는 {{",
         "    정수 tid = 블록안가로().",
         "    정수 가닥 = tid / 64.",
         "    정수 t64 = tid % 64.",
         "    정수 ty = t64 / 8.",
         "    정수 tx = t64 % 8.",
         "    정수 행0 = 블록가로() * 64.",
         "    정수 열0 = 블록세로() * 64.",
         f"    짧은실수 참조 판 = {판}().",
         "    정수 a행 = 행0 + tid / 4.",
         "    a행 >= 행수이면 { a행 = 행수 - 1. }",
         "    정수 ak = (tid % 4) * 8.",
         "    정수 a저장 = ak * 64 + ((tid / 4) ^ ((tid % 4) * 8)).",
         "    정수 a원 = a행 * 깊이 + ak.",
         "    정수 열32 = 열수 * 32."]
    if 넷:
        L += ["    정수 열16 = 열수 * 16.",
              "    정수 b저장 = (tid / 16) * 64 + (tid % 16) * 4.",
              "    정수 b원 = (tid / 16) * 열수 + 열0 + (tid % 16) * 4."]
    else:
        L += ["    정수 wp = tid / 32.", "    정수 ln = tid % 32.", "    정수 b저장 = 4 * wp * 64 + ln."]
        for e in range(2):
            L += [f"    정수 c{e} = 열0 + ln + {32 * e}.", f"    c{e} >= 열수이면 {{ c{e} = 열수 - 1. }}",
                  f"    정수 b원{e} = 4 * wp * 열수 + c{e}."]
        L += [f"    정수 열줄{r} = {r} * 열수." for r in range(4)]
    L.append(f"    정수 타일수 = 깊이 / {BK}.")
    L.append("    정수 올판 = 0.")
    if 레지:
        L += ["    정수 ar0 = tid / 8.",
              "    정수 ac = (tid % 8) * 4.",
              "    정수 sa = 8 * ((tid % 8) / 2).",
              "    정수 깊이4 = 깊이 / 4 * 4.",
              "    정수 행a0 = 행0 + ar0.", "    행a0 >= 행수이면 { 행a0 = 행수 - 1. }",
              "    정수 행a1 = 행0 + ar0 + 32.", "    행a1 >= 행수이면 { 행a1 = 행수 - 1. }",
              "    정수 ra원0 = 행a0 * 깊이4 + ac.",
              "    정수 ra원1 = 행a1 * 깊이4 + ac.",
              "    정수 저a = ac * 64 + (ar0 ^ sa)."]
        L += [f"    짧은실수 ra{h}_{u} = 입력[ra원{h} + {u}]." for h in range(2) for u in range(4)]
        L += 쓰기A("0", "    ")
    L += 올리기("0", "    ")
    L.append("    비동기묶기().")
    L.append("    타일수 > 1이면 {")
    L += 다음("        ")
    L += 올리기("1", "        ")
    if 레지:
        L += [f"        ra원{h} = ra원{h} + {BK}." for h in range(2)]
        L += 읽기A("        ")
    L.append("    }")
    L.append("    비동기묶기().")
    L.append("    짧은실수 영 = 0 으로 짧은실수.")
    L += [f"    짧은실수 a{i}_{j} = 영." for i in I8 for j in J8]
    L += [f"    짧은실수 x{i} = 영." for i in I8]
    L += [f"    짧은실수 w{j} = 영." for j in J8]
    L.append("    정수 aq = 0.")
    L.append("    정수 버퍼 = 0.")
    L.append("    정수 앞판 = 2.")
    L.append("    반복 (정수 t는 0부터 타일수 전까지) {")
    L.append("        비동기기다리기(1).")
    L.append("        동기화().")
    L.append("        t + 2 < 타일수이면 {")
    L += 다음("            ")
    L += 올리기("앞판", "            ")
    L.append("        }")
    L.append("        비동기묶기().")
    L.append(f"        정수 B바탕 = {B0} + 버퍼 * {BB} + 가닥 * 64 + tx * 4.")
    for q in range(BK // 4):
        if q % 2 == 0:
            L.append(f"        aq = 버퍼 * {AB} + 가닥 * 64 + ((ty * 4) ^ {8 * (q // 2)}).")
        L += [f"        x{r} = 판[aq + {q * 256 + r}]." for r in range(4)]
        L += [f"        x{4 + r} = 판[aq + {q * 256 + 32 + r}]." for r in range(4)]
        L += [f"        w{c} = 판[B바탕 + {q * 256 + c}]." for c in range(4)]
        L += [f"        w{4 + c} = 판[B바탕 + {q * 256 + 32 + c}]." for c in range(4)]
        L += [f"        a{i}_{j} = 곱해더하기(x{i}, w{j}, a{i}_{j})." for i in I8 for j in J8]
    if 레지:
        L.append("        t + 1 < 타일수이면 {")
        L.append("            정수 다음버퍼 = 버퍼 + 1.")
        L.append("            다음버퍼 == 3이면 { 다음버퍼 = 0. }")
        L += 쓰기A(f"다음버퍼 * {AB}", "            ")
        L.append("            t + 2 < 타일수이면 {")
        L += [f"                ra원{h} = ra원{h} + {BK}." for h in range(2)]
        L += 읽기A("                ")
        L.append("            }")
        L.append("        }")
    L.append("        버퍼 = 버퍼 + 1.")
    L.append("        버퍼 == 3이면 { 버퍼 = 0. }")
    L.append("        앞판 = 앞판 + 1.")
    L.append("        앞판 == 3이면 { 앞판 = 0. }")
    L.append("    }")
    return L + 타일끝(epi)


def 타일끝(epi):
    """64 × 64 타일 판의 뒤(모든 판이 같다): 가닥 합치기 ((p₀ + p₂) + (p₁ + p₃)), 치우침, 끝손질."""
    I8, J8 = range(8), range(8)
    행식 = lambda i: f"ty * 4 + {i}" if i < 4 else f"32 + ty * 4 + {i - 4}"
    열식 = lambda j: f"tx * 4 + {j}" if j < 4 else f"32 + tx * 4 + {j - 4}"
    L = []
    L.append("    동기화().")
    L.append("    (* 가닥 합치기: 가닥 2·3 이 자기 64 칸을 붙여 내놓고(스레드마다 68 간격 — 네 칸씩), 0·1 이 더한다(q₀ = p₀ + p₂,")
    L.append("       q₁ = p₁ + p₃). 그다음 0·1 이 q 를 판에 두고, 네 가닥이 칸을 나눠 (q₀ + q₁) + 치우침 과 끝손질을 한다 *)")
    L.append("    가닥 >= 2이면 {")
    L.append("        정수 r바탕 = ((가닥 - 2) * 64 + t64) * 68.")
    L += [f"        판[r바탕 + {i * 8 + j}] = a{i}_{j}." for i in I8 for j in J8]
    L.append("    }")
    L.append("    동기화().")
    L.append("    가닥 < 2이면 {")
    L.append("        정수 r바탕2 = (가닥 * 64 + t64) * 68.")
    L += [f"        a{i}_{j} = a{i}_{j} + 판[r바탕2 + {i * 8 + j}]." for i in I8 for j in J8]
    L.append("    }")
    L.append("    동기화().")
    # q₀(가닥 0)과 q₁(가닥 1)을 [가닥][행 64][열 64 + 4] 에 둔다
    L.append("    가닥 < 2이면 {")
    for i in I8:
        for j in J8:
            L.append(f"        판[가닥 * 4352 + ({행식(i)}) * 68 + {열식(j)}] = a{i}_{j}.")
    L.append("    }")
    L.append("    동기화().")
    L += ["    정수 행 = 0.", "    정수 열 = 0.", "    정수 자리 = 0.", "    정수 자리위 = 0.", "    정수 칸 = 0.", "    짧은실수 v = 영.",
          "    짧은실수 u = 영.", "    짧은실수 th = 영.", "    정수 rr = 0.", "    정수 cc = 0."]
    if epi == "_KV":
        L.append("    정수 키타일 = 0.")
        L.append(f"    (열0 >= {너비} 그리고 열0 < {2 * 너비})이면 {{ 키타일 = 1. }}")
    L.append("    반복 (정수 m는 0부터 16 전까지) {")
    L.append("        칸 = m * 256 + tid.")
    if epi == "_KV":
        L.append("        키타일 == 1이면 { rr = 칸 % 64. cc = 칸 / 64. }")
        L.append("        아니면 { rr = 칸 / 64. cc = 칸 % 64. }")
    else:
        L += ["        rr = 칸 / 64.", "        cc = 칸 % 64."]
    L.append("        행 = 행0 + rr.")
    L.append("        열 = 열0 + cc.")
    L.append("        (행 < 행수 그리고 열 < 열수)이면 {")
    L.append("            v = (판[rr * 68 + cc] + 판[4352 + rr * 68 + cc]) + 치우침[열].")
    if epi == "_KV":
        L += 자리두기("행", "            ")
    L += 끝(epi, "v", "행", "열", "자리", "            ")
    L.append("        }")
    L.append("    }")
    L.append("}")
    return L


def 작은타일선형(epi, 이름=None, 레지=True):
    """32 × 32 칸을 블록 하나(256 스레드 = 가닥 4 × 64)가 — 행이 적어 64 × 64 블록이 GPU 를 다 채우지 못할 때. 스레드 하나가
    4 × 4 칸(행 ty·4 + r, 열 tx·4 + c). k 를 32 줄씩 세 판에 비동기복사로. 입력 판은 [k 32][행 32] 에 자리 m ^ s(k),
    s(k) = 4·((k/4) % 8). 가중치는 16 바이트씩 — 열수가 32 의 배수이고 시작이 16 바이트 정렬일 때만(호스트가 확인한다)."""
    I4, J4 = range(4), range(4)
    BK, AB, BB = 32, 32 * 32, 32 * 32
    B0 = 3 * AB
    이름 = 이름 or f"작은타일선형{epi}"
    L = [f"(* 32 × 32 칸을 블록 하나가 — 가닥 g 의 스레드 64 개가 k ≡ g (mod 4) 를 맡고, 스레드 하나가 4 × 4 칸 *)",
         f"(* 실행한도 {이름} 256 4 *)",
         f"[{머리(epi)} {이름}]는 {{",
         "    정수 tid = 블록안가로().",
         "    정수 가닥 = tid / 64.",
         "    정수 t64 = tid % 64.",
         "    정수 ty = t64 / 8.",
         "    정수 tx = t64 % 8.",
         "    정수 행0 = 블록가로() * 32.",
         "    정수 열0 = 블록세로() * 32.",
         "    짧은실수 참조 판 = 공유판24().",
         "    정수 a행 = 행0 + tid / 8.",
         "    a행 >= 행수이면 { a행 = 행수 - 1. }",
         "    정수 ak = (tid % 8) * 4.",
         "    정수 a저장 = ak * 32 + ((tid / 8) ^ ((tid % 8) * 4)).",
         "    정수 a원 = a행 * 깊이 + ak.",
         "    정수 열32 = 열수 * 32.",
         "    정수 b저장 = (tid / 8) * 32 + (tid % 8) * 4.",
         "    정수 b원 = (tid / 8) * 열수 + 열0 + (tid % 8) * 4.",
         f"    정수 타일수 = 깊이 / {BK}.",
         "    정수 올판 = 0."]

    def 올리기(판번호, ind):
        out = [f"{ind}올판 = {판번호}."]
        if not 레지:
            out += [f"{ind}비동기복사(판 에, 올판 * {AB} + a저장 + {32 * e} 를, 입력 에서, a원 + {e} 로)." for e in range(4)]
        out += [f"{ind}비동기복사16(판 에, {B0} + 올판 * {BB} + b저장 를, 가중치 에서, b원 로)."]
        return out

    def 다음(ind):
        return ([] if 레지 else [f"{ind}a원 = a원 + {BK}."]) + [f"{ind}b원 = b원 + 열32."]

    def 읽기A(ind):
        return [f"{ind}ra{u} = 입력[ra원 + {u}]." for u in range(4)]

    def 쓰기A(판식, ind):
        return [f"{ind}판[{판식} + a저장 + {32 * u}] = ra{u}." for u in range(4)]

    if 레지:
        L += ["    정수 깊이4 = 깊이 / 4 * 4.",
              "    정수 ra원 = a행 * 깊이4 + ak."]
        L += [f"    짧은실수 ra{u} = 입력[ra원 + {u}]." for u in range(4)]
        L += 쓰기A("0", "    ")
    L += 올리기("0", "    ")
    L.append("    비동기묶기().")
    L.append("    타일수 > 1이면 {")
    L += 다음("        ")
    L += 올리기("1", "        ")
    if 레지:
        L.append(f"        ra원 = ra원 + {BK}.")
        L += 읽기A("        ")
    L.append("    }")
    L.append("    비동기묶기().")
    L.append("    짧은실수 영 = 0 으로 짧은실수.")
    L += [f"    짧은실수 a{i}_{j} = 영." for i in I4 for j in J4]
    L += [f"    짧은실수 x{i} = 영." for i in I4]
    L += [f"    짧은실수 w{j} = 영." for j in J4]
    L += [f"    정수 ty4x{q} = (ty * 4) ^ {4 * q}." for q in range(8)]
    L += ["    정수 버퍼 = 0.", "    정수 앞판 = 2."]
    L.append("    반복 (정수 t는 0부터 타일수 전까지) {")
    L.append("        비동기기다리기(1).")
    L.append("        동기화().")
    L.append("        t + 2 < 타일수이면 {")
    L += 다음("            ")
    L += 올리기("앞판", "            ")
    L.append("        }")
    L.append("        비동기묶기().")
    L.append(f"        정수 A바탕 = 버퍼 * {AB} + 가닥 * 32.")
    L.append(f"        정수 B바탕 = {B0} + 버퍼 * {BB} + 가닥 * 32 + tx * 4.")
    for q in range(BK // 4):
        L.append(f"        정수 aq{q} = A바탕 + ty4x{q}.")
        L += [f"        x{r} = 판[aq{q} + {q * 128 + r}]." for r in I4]
        L += [f"        w{c} = 판[B바탕 + {q * 128 + c}]." for c in J4]
        L += [f"        a{i}_{j} = 곱해더하기(x{i}, w{j}, a{i}_{j})." for i in I4 for j in J4]
    if 레지:
        L.append("        t + 1 < 타일수이면 {")
        L.append("            정수 다음버퍼 = 버퍼 + 1.")
        L.append("            다음버퍼 == 3이면 { 다음버퍼 = 0. }")
        L += 쓰기A(f"다음버퍼 * {AB}", "            ")
        L.append("            t + 2 < 타일수이면 {")
        L.append(f"                ra원 = ra원 + {BK}.")
        L += 읽기A("                ")
        L.append("            }")
        L.append("        }")
    L.append("        버퍼 = 버퍼 + 1.")
    L.append("        버퍼 == 3이면 { 버퍼 = 0. }")
    L.append("        앞판 = 앞판 + 1.")
    L.append("        앞판 == 3이면 { 앞판 = 0. }")
    L.append("    }")
    return L + 작은타일끝(epi)


def 작은타일끝(epi):
    """32 × 32 타일 판의 뒤: 가닥 합치기, 치우침, 끝손질. q₀ · q₁ 의 자리 [가닥][행 32][열 32 + 1] 은 판의 2048 부터 —
    (5단계에서 고침: 4096 부터 두면 끝이 6208 이라 공유판24(6144 칸) 밖 64 칸까지 썼다. 값은 같다 — 자리만 옮긴다.)"""
    I4, J4 = range(4), range(4)
    L = []
    L.append("    동기화().")
    L.append("    가닥 >= 2이면 {")
    L += [f"        판[{(i * 4 + j) * 128} + (가닥 - 2) * 64 + t64] = a{i}_{j}." for i in I4 for j in J4]
    L.append("    }")
    L.append("    동기화().")
    L.append("    가닥 < 2이면 {")
    L += [f"        a{i}_{j} = a{i}_{j} + 판[{(i * 4 + j) * 128} + 가닥 * 64 + t64]." for i in I4 for j in J4]
    L.append("    }")
    L.append("    동기화().")
    L.append("    가닥 < 2이면 {")
    L += [f"        판[{2048} + 가닥 * 1056 + (ty * 4 + {i}) * 33 + tx * 4 + {j}] = a{i}_{j}." for i in I4 for j in J4]
    L.append("    }")
    L.append("    동기화().")
    L += ["    정수 행 = 0.", "    정수 열 = 0.", "    정수 자리 = 0.", "    정수 자리위 = 0.", "    정수 칸 = 0.", "    짧은실수 v = 영.",
          "    짧은실수 u = 영.", "    짧은실수 th = 영."]
    L.append("    반복 (정수 m는 0부터 4 전까지) {")
    L.append("        칸 = m * 256 + tid.")
    L.append("        행 = 행0 + 칸 / 32.")
    L.append("        열 = 열0 + 칸 % 32.")
    L.append("        (행 < 행수 그리고 열 < 열수)이면 {")
    L.append("            v = (판[2048 + (칸 / 32) * 33 + 칸 % 32] + 판[3104 + (칸 / 32) * 33 + 칸 % 32]) + 치우침[열].")
    if epi == "_KV":
        L += 자리두기("행", "            ")
    L += 끝(epi, "v", "행", "열", "자리", "            ")
    L.append("        }")
    L.append("    }")
    L.append("}")
    return L


def 줄끝(R, epi, TX):
    """줄 판의 뒤(줄선형 · 양자줄선형이 같다): 가닥 합치기 ((p₀ + p₂) + (p₁ + p₃)), 치우침, 끝손질, 다음 커널의 가중치 미리읽기."""
    rr = range(R)
    L = []
    L.append("    짧은실수 참조 판 = 공유판4().")
    L.append("    가닥 >= 2이면 {")
    L += [f"        판[((가닥 - 2) * {R} + {r}) * {TX} + tx] = a{r}." for r in rr]
    L.append("    }")
    L.append("    동기화().")
    L.append("    가닥 < 2이면 {")
    L += [f"        a{r} = a{r} + 판[(가닥 * {R} + {r}) * {TX} + tx]." for r in rr]
    L.append("    }")
    L.append("    동기화().")
    L.append("    가닥 == 1이면 {")
    L += [f"        판[{r * TX} + tx] = a{r}." for r in rr]
    L.append("    }")
    L.append("    동기화().")
    L.append("    (가닥 == 0 그리고 열 < 열수)이면 {")
    L += ["        짧은실수 v = 영.", "        짧은실수 u = 영.", "        짧은실수 th = 영.", "        정수 자리 = 0.", "        정수 자리위 = 0."]
    for r in rr:
        L.append(f"        {r} < 행수이면 {{")
        L.append(f"            v = (a{r} + 판[{r * TX} + tx]) + 치우침[열].")
        if epi == "_KV":
            L += 자리두기(str(r), "            ")
        L += 끝(epi, "v", str(r), "열", "자리", "            ")
        L.append("        }")
    L.append("    }")
    L.append("    (* 다음 커널의 가중치를 L2 로 미리 — 128 바이트 줄마다 한 번, 모든 스레드가 나눠서 *)")
    L.append("    반복 (정수 미 = 실행번호() * 32: 미 < 다음수: 미 += 실행개수() * 32) { 미리읽기(다음, 미). }")
    L.append("}")
    return L


def 줄선형(R, epi, U=16, TX=32, 이름=None):
    rr = range(R)
    이름 = 이름 or f"줄선형{R}{epi}"
    L = [f"(* 행 {R} 개 × 열 {TX} 개를 블록 하나(가닥 4 × 열 {TX})가 — 가중치를 {U} 개씩 먼저 읽고 차례로 곱해더한다 *)",
         f"[{머리(epi, True)} {이름}]는 {{",
         "    정수 tid = 블록안가로().",
         f"    정수 가닥 = tid / {TX}.",
         f"    정수 tx = tid % {TX}.",
         f"    정수 열 = 블록가로() * {TX} + tx.",
         "    정수 c = 열.",
         "    c >= 열수이면 { c = 열수 - 1. }"]
    for r in rr:
        L += [f"    정수 i{r} = {r}.", f"    i{r} >= 행수이면 {{ i{r} = 행수 - 1. }}", f"    정수 x바탕{r} = i{r} * 깊이."]
    L.append("    짧은실수 영 = 0 으로 짧은실수.")
    L += [f"    짧은실수 a{r} = 영." for r in rr]
    L += [f"    짧은실수 w{u} = 영." for u in range(U)]
    L.append("    정수 k = 가닥.")
    L.append(f"    반복 (: k + {4 * (U - 1)} < 깊이: k += {4 * U}) {{")
    L += [f"        w{u} = 가중치[(k + {4 * u}) * 열수 + c]." for u in range(U)]
    for u in range(U):
        L += [f"        a{r} = 곱해더하기(입력[x바탕{r} + k + {4 * u}], w{u}, a{r})." for r in rr]
    L.append("    }")
    L.append("    반복 (: k < 깊이: k += 4) {")
    L.append("        w0 = 가중치[k * 열수 + c].")
    L += [f"        a{r} = 곱해더하기(입력[x바탕{r} + k], w0, a{r})." for r in rr]
    L.append("    }")
    return L + 줄끝(R, epi, TX)


# ── 5단계: 양자 가중치 판 ── 배치·순서·끝손질은 위의 짧은실수 판과 같고, 가중치만 블록 평면 배치의 칸을 읽어 정확히 푼다 ─────────

def 양자줄선형(R, epi, UB, 이름, 형식=None):
    """줄선형의 양자 판 — 스레드 배치(가닥 4 × 열 32)·순서(가닥 g 가 k ≡ g (mod 4) 를 오름차순 곱해더하기)·끝손질이 같다. 가닥 g 의
    스레드는 칸 (kb, g, 열) 을 UB 개씩 먼저 읽고, kb 오름차순 · 칸 안 i 오름차순(k = 32·kb + g + 4i — 곧 k 오름차순)으로 풀어
    곱해더한다."""
    형식 = 형식 or 층형식
    rr = range(R)
    e0, 걸음 = 칸자리(형식, "가닥", "c", "열수")
    L = [f"(* 행 {R} 개 × 열 32 개를 블록 하나(가닥 4 × 열 32)가 — 가중치({형식})의 칸을 {UB} 개씩 먼저 읽어 풀고 차례로 곱해더한다 *)",
         f"[{머리(epi, True, 형식)} {이름}]는 {{",
         "    정수 tid = 블록안가로().",
         "    정수 가닥 = tid / 32.",
         "    정수 tx = tid % 32.",
         "    정수 열 = 블록가로() * 32 + tx.",
         "    정수 c = 열.",
         "    c >= 열수이면 { c = 열수 - 1. }"]
    for r in rr:
        L += [f"    정수 i{r} = {r}.", f"    i{r} >= 행수이면 {{ i{r} = 행수 - 1. }}", f"    정수 x바탕{r} = i{r} * 깊이 + 가닥."]
    L.append("    짧은실수 영 = 0 으로 짧은실수.")
    L += [f"    짧은실수 a{r} = 영." for r in rr]
    L += ["    짧은실수 wv = 영.", f"    정수 qe = {e0}.", "    정수 qs = c.", f"    정수 걸음 = {걸음}.", "    정수 블록수 = 깊이 / 32.",
          "    정수 kb = 0."]
    for b in range(UB):
        L += 칸선언(형식, f"q{b}", "    ")

    def 몸(nb, ind):
        out = []
        for b in range(nb):
            if 형식 == "F16":                               # 칸마다 바탕을 따로 — 여덟 반실수를 묶어 읽게(자리 차이가 작게)
                out.append(f"{ind}정수 qe{b} = qe + {b} * 걸음." if b else f"{ind}정수 qe{b} = qe.")
            자리 = f"qe{b}" if 형식 == "F16" else (f"qe + {b} * 걸음" if b else "qe")
            out += 칸읽기(형식, "가중치", "척도", 자리, f"qs + {b} * 열수" if b else "qs", f"q{b}", ind, "열수")
        for b in range(nb):
            for i in range(8):
                out.append(f"{ind}wv = {칸값식(형식, f'q{b}', i)}.")
                out += [f"{ind}a{r} = 곱해더하기(입력[x바탕{r} + kb * 32 + {32 * b + 4 * i}], wv, a{r})." for r in rr]
        out += [f"{ind}qe = qe + {nb} * 걸음.", f"{ind}qs = qs + {nb} * 열수."]
        return out
    L.append(f"    반복 (: kb + {UB - 1} < 블록수: kb += {UB}) {{")
    L += 몸(UB, "        ")
    L.append("    }")
    L.append("    반복 (: kb < 블록수: kb += 1) {")
    L += 몸(1, "        ")
    L.append("    }")
    return L + 줄끝(R, epi, 32)


def 양자타일선형(epi, 이름, 형식=None):
    """타일선형(레지 판)의 양자 판 — 블록·스레드 배치, 판, 곱해더하는 순서, 끝손질이 같다. 가중치 조각(k 32 × 열 64 = kb 하나의
    칸 가닥 4 × 열 64)은 스레드마다 칸 하나(가닥 = tid / 64, 열 = 열0 + tid % 64 — 열수 밖이면 마지막 열)를 입력처럼 한 조각 앞서
    레지스터로 읽어 두었다가 판의 [k][열] 자리에 풀어 쓴다(정확). 비동기복사는 쓰지 않는다."""
    형식 = 형식 or 층형식
    I8, J8 = range(8), range(8)
    BK, AB, BB = 32, 32 * 64, 32 * 64
    B0 = 3 * AB
    e0, 걸음 = 칸자리(형식, "가닥", "bn", "열수")

    def 읽기A(ind):
        return [f"{ind}ra{h}_{u} = 입력[ra원{h} + {u}]." for h in range(2) for u in range(4)]

    def 쓰기A(판식, ind):
        return [f"{ind}판[{판식} + 저a + {u * 64 + 32 * h}] = ra{h}_{u}." for h in range(2) for u in range(4)]

    def 읽기B(ind):
        return 칸읽기(형식, "가중치", "척도", "qe", "qs", "qb", ind, "열수")

    def 쓰기B(판식, ind):
        return [f"{ind}판[{판식} + b저장 + {256 * i}] = {칸값식(형식, 'qb', i)}." for i in range(8)]

    L = [f"(* 64 × 64 칸을 블록 하나가 — 타일선형과 같은 배치·순서. 가중치({형식})는 칸을 레지스터로 한 조각 앞서 읽어 판에 풀어 둔다 *)",
         f"(* 실행한도 {이름} 256 2 *)",
         f"[{머리(epi, False, 형식)} {이름}]는 {{",
         "    정수 tid = 블록안가로().",
         "    정수 가닥 = tid / 64.",
         "    정수 t64 = tid % 64.",
         "    정수 ty = t64 / 8.",
         "    정수 tx = t64 % 8.",
         "    정수 행0 = 블록가로() * 64.",
         "    정수 열0 = 블록세로() * 64.",
         "    짧은실수 참조 판 = 공유판48().",
         "    짧은실수 영 = 0 으로 짧은실수.",
         "    정수 ar0 = tid / 8.",
         "    정수 ac = (tid % 8) * 4.",
         "    정수 sa = 8 * ((tid % 8) / 2).",
         "    정수 깊이4 = 깊이 / 4 * 4.",
         "    정수 행a0 = 행0 + ar0.", "    행a0 >= 행수이면 { 행a0 = 행수 - 1. }",
         "    정수 행a1 = 행0 + ar0 + 32.", "    행a1 >= 행수이면 { 행a1 = 행수 - 1. }",
         "    정수 ra원0 = 행a0 * 깊이4 + ac.",
         "    정수 ra원1 = 행a1 * 깊이4 + ac.",
         "    정수 저a = ac * 64 + (ar0 ^ sa).",
         "    정수 bn = 열0 + t64.",
         "    bn >= 열수이면 { bn = 열수 - 1. }",
         f"    정수 qe = {e0}.",
         "    정수 qs = bn.",
         f"    정수 걸음 = {걸음}.",
         f"    정수 b저장 = {B0} + 가닥 * 64 + t64.",
         f"    정수 타일수 = 깊이 / {BK}."]
    L += [f"    짧은실수 ra{h}_{u} = 입력[ra원{h} + {u}]." for h in range(2) for u in range(4)]
    L += 칸선언(형식, "qb", "    ")
    L += 읽기B("    ")
    L += 쓰기A("0", "    ")
    L += 쓰기B("0", "    ")
    L.append("    타일수 > 1이면 {")
    L += [f"        ra원{h} = ra원{h} + {BK}." for h in range(2)]
    L += 읽기A("        ")
    L += ["        qe = qe + 걸음.", "        qs = qs + 열수."]
    L += 읽기B("        ")
    L.append("    }")
    L += [f"    짧은실수 a{i}_{j} = 영." for i in I8 for j in J8]
    L += [f"    짧은실수 x{i} = 영." for i in I8]
    L += [f"    짧은실수 w{j} = 영." for j in J8]
    L.append("    정수 aq = 0.")
    L.append("    정수 버퍼 = 0.")
    L.append("    반복 (정수 t는 0부터 타일수 전까지) {")
    L.append("        동기화().")
    L.append(f"        정수 B바탕 = {B0} + 버퍼 * {BB} + 가닥 * 64 + tx * 4.")
    for q in range(BK // 4):
        if q % 2 == 0:
            L.append(f"        aq = 버퍼 * {AB} + 가닥 * 64 + ((ty * 4) ^ {8 * (q // 2)}).")
        L += [f"        x{r} = 판[aq + {q * 256 + r}]." for r in range(4)]
        L += [f"        x{4 + r} = 판[aq + {q * 256 + 32 + r}]." for r in range(4)]
        L += [f"        w{c} = 판[B바탕 + {q * 256 + c}]." for c in range(4)]
        L += [f"        w{4 + c} = 판[B바탕 + {q * 256 + 32 + c}]." for c in range(4)]
        L += [f"        a{i}_{j} = 곱해더하기(x{i}, w{j}, a{i}_{j})." for i in I8 for j in J8]
    L.append("        t + 1 < 타일수이면 {")
    L.append("            정수 다음버퍼 = 버퍼 + 1.")
    L.append("            다음버퍼 == 3이면 { 다음버퍼 = 0. }")
    L += 쓰기A(f"다음버퍼 * {AB}", "            ")
    L += 쓰기B(f"다음버퍼 * {BB}", "            ")
    L.append("            t + 2 < 타일수이면 {")
    L += [f"                ra원{h} = ra원{h} + {BK}." for h in range(2)]
    L += 읽기A("                ")
    L += ["                qe = qe + 걸음.", "                qs = qs + 열수."]
    L += 읽기B("                ")
    L.append("            }")
    L.append("        }")
    L.append("        버퍼 = 버퍼 + 1.")
    L.append("        버퍼 == 3이면 { 버퍼 = 0. }")
    L.append("    }")
    return L + 타일끝(epi)


def 양자작은타일선형(epi, 이름, 형식=None):
    """작은타일선형(레지 판)의 양자 판 — 32 × 32 칸, 같은 배치·순서·끝손질. 가중치 조각(k 32 × 열 32 = 칸 가닥 4 × 열 32)은
    스레드 128 개(가닥 = tid / 32, 열 = 열0 + tid % 32)가 칸 하나씩 한 조각 앞서 레지스터로 읽어 판에 풀어 쓴다."""
    형식 = 형식 or 층형식
    I4, J4 = range(4), range(4)
    BK, AB, BB = 32, 32 * 32, 32 * 32
    B0 = 3 * AB
    e0, 걸음 = 칸자리(형식, "bg", "bn", "열수")

    def 읽기A(ind):
        return [f"{ind}ra{u} = 입력[ra원 + {u}]." for u in range(4)]

    def 쓰기A(판식, ind):
        return [f"{ind}판[{판식} + a저장 + {32 * u}] = ra{u}." for u in range(4)]

    def 읽기B(ind):
        return [f"{ind}tid < 128이면 {{"] + 칸읽기(형식, "가중치", "척도", "qe", "qs", "qb", ind + "    ", "열수") + [f"{ind}}}"]

    def 쓰기B(판식, ind):
        return [f"{ind}tid < 128이면 {{"] + \
               [f"{ind}    판[{판식} + b저장 + {128 * i}] = {칸값식(형식, 'qb', i)}." for i in range(8)] + [f"{ind}}}"]

    L = [f"(* 32 × 32 칸을 블록 하나가 — 작은타일선형과 같은 배치·순서. 가중치({형식})는 칸을 레지스터로 한 조각 앞서 읽어 판에 풀어 둔다 *)",
         f"(* 실행한도 {이름} 256 4 *)",
         f"[{머리(epi, False, 형식)} {이름}]는 {{",
         "    정수 tid = 블록안가로().",
         "    정수 가닥 = tid / 64.",
         "    정수 t64 = tid % 64.",
         "    정수 ty = t64 / 8.",
         "    정수 tx = t64 % 8.",
         "    정수 행0 = 블록가로() * 32.",
         "    정수 열0 = 블록세로() * 32.",
         "    짧은실수 참조 판 = 공유판24().",
         "    짧은실수 영 = 0 으로 짧은실수.",
         "    정수 a행 = 행0 + tid / 8.",
         "    a행 >= 행수이면 { a행 = 행수 - 1. }",
         "    정수 ak = (tid % 8) * 4.",
         "    정수 a저장 = ak * 32 + ((tid / 8) ^ ((tid % 8) * 4)).",
         "    정수 깊이4 = 깊이 / 4 * 4.",
         "    정수 ra원 = a행 * 깊이4 + ak.",
         "    정수 bg = (tid / 32) % 4.",
         "    정수 bn = 열0 + tid % 32.",
         "    bn >= 열수이면 { bn = 열수 - 1. }",
         f"    정수 qe = {e0}.",
         "    정수 qs = bn.",
         f"    정수 걸음 = {걸음}.",
         f"    정수 b저장 = {B0} + bg * 32 + tid % 32.",
         f"    정수 타일수 = 깊이 / {BK}."]
    L += [f"    짧은실수 ra{u} = 입력[ra원 + {u}]." for u in range(4)]
    L += 칸선언(형식, "qb", "    ")
    L += 읽기B("    ")
    L += 쓰기A("0", "    ")
    L += 쓰기B("0", "    ")
    L.append("    타일수 > 1이면 {")
    L.append(f"        ra원 = ra원 + {BK}.")
    L += 읽기A("        ")
    L += ["        qe = qe + 걸음.", "        qs = qs + 열수."]
    L += 읽기B("        ")
    L.append("    }")
    L += [f"    짧은실수 a{i}_{j} = 영." for i in I4 for j in J4]
    L += [f"    짧은실수 x{i} = 영." for i in I4]
    L += [f"    짧은실수 w{j} = 영." for j in J4]
    L += [f"    정수 ty4x{q} = (ty * 4) ^ {4 * q}." for q in range(8)]
    L.append("    정수 버퍼 = 0.")
    L.append("    반복 (정수 t는 0부터 타일수 전까지) {")
    L.append("        동기화().")
    L.append(f"        정수 A바탕 = 버퍼 * {AB} + 가닥 * 32.")
    L.append(f"        정수 B바탕 = {B0} + 버퍼 * {BB} + 가닥 * 32 + tx * 4.")
    for q in range(BK // 4):
        L.append(f"        정수 aq{q} = A바탕 + ty4x{q}.")
        L += [f"        x{r} = 판[aq{q} + {q * 128 + r}]." for r in I4]
        L += [f"        w{c} = 판[B바탕 + {q * 128 + c}]." for c in J4]
        L += [f"        a{i}_{j} = 곱해더하기(x{i}, w{j}, a{i}_{j})." for i in I4 for j in J4]
    L.append("        t + 1 < 타일수이면 {")
    L.append("            정수 다음버퍼 = 버퍼 + 1.")
    L.append("            다음버퍼 == 3이면 { 다음버퍼 = 0. }")
    L += 쓰기A(f"다음버퍼 * {AB}", "            ")
    L += 쓰기B(f"다음버퍼 * {BB}", "            ")
    L.append("            t + 2 < 타일수이면 {")
    L.append(f"                ra원 = ra원 + {BK}.")
    L += 읽기A("                ")
    L += ["                qe = qe + 걸음.", "                qs = qs + 열수."]
    L += 읽기B("                ")
    L.append("            }")
    L.append("        }")
    L.append("        버퍼 = 버퍼 + 1.")
    L.append("        버퍼 == 3이면 { 버퍼 = 0. }")
    L.append("    }")
    return L + 작은타일끝(epi)


def 낱말풀기(형식, 토큰, c, 결과, ind):
    """낱말표(양자 형식, 열 = 토큰 50257, k = 768)에서 (토큰, c) 의 값 하나를 정확히 풀어 새 짧은실수 결과 에 — 임베딩용.
    c 는 음이 아닌 식(< 768)."""
    N = 낱말수
    if 계약 == "정수":                                  # 6단계 정수 배치: [블록][열][32 바이트](Q8_0 — 부호 있는 바이트), 척도 [블록][50304]
        assert 형식 == "Q8_0", "정수 배치의 낱말표는 Q8_0 만 (GGUF 의 Q4_0 · Q8_0 파일 모두)"
        return [f"{ind}정수 {결과}kb = ({c}) >> 5.",
                f"{ind}중간정수 {결과}w = 낱말표[(({결과}kb * {N} + {토큰}) * 32 + (({c}) & 31)) / 4].",
                f"{ind}정수 {결과}s = (({c}) & 3) * 8.",
                f"{ind}짧은실수 {결과} = ((((({결과}w >> {결과}s) & 255) ^ 128) - 128) 으로 짧은실수) * 낱말척도[{결과}kb * {(N + 63) // 64 * 64} + {토큰}]."]
    out = [f"{ind}정수 {결과}kb = ({c}) >> 5.", f"{ind}정수 {결과}g = ({c}) & 3.", f"{ind}정수 {결과}v = (({c}) & 31) >> 2."]
    kb, g, v = f"{결과}kb", f"{결과}g", f"{결과}v"
    if 형식 == "Q4_0":
        out += [f"{ind}중간정수 {결과}w = 낱말표[({kb} * 4 + {g}) * {N} + {토큰}].",
                f"{ind}정수 {결과}s = ({v} & 3) * 8 + ({v} >> 2) * 4.",
                f"{ind}짧은실수 {결과} = (((({결과}w >> {결과}s) & 15) - 8) 으로 짧은실수) * 낱말척도[{kb} * {N} + {토큰}]."]
    elif 형식 == "Q8_0":
        out += [f"{ind}중간정수 {결과}w = 낱말표[({kb} * 8 + {g} * 2 + ({v} >> 2)) * {N} + {토큰}].",
                f"{ind}짧은실수 {결과} = (((({결과}w >> (({v} & 3) * 8)) & 255) - 128) 으로 짧은실수) * 낱말척도[{kb} * {N} + {토큰}]."]
    else:
        out += [f"{ind}짧은실수 {결과} = 낱말표[(({kb} * 4 + {g}) * {N} + {토큰}) * 8 + {v}]."]
    return out


def 양자임베딩(형식=None):
    """gpt2.gl 의 임베딩과 같은 계산(출력 = 낱말표의 값 + 위치표의 값) — 낱말표만 양자 형식에서 값 하나씩 정확히 풀어 읽는다."""
    형식 = 형식 or 낱말형식
    L = ["(* 임베딩 — gpt2.gl 의 것과 같은 계산. 낱말표는 양자 형식(블록 평면 배치)에서 값 하나를 정확히 풀어 *)",
         f"[정수 참조 토큰에서 {가중선언('낱말표', '낱말척도', 형식)}짧은실수 참조 위치표와 짧은실수 참조 출력에 정수 행수로 "
         "정수 묶음안행수로 정수 위치시작으로 임베딩]는 {",
         "    정수 i = 실행번호().",
         f"    i < 행수 * {너비}이면 {{",
         f"        정수 r = i / {너비}.",
         f"        정수 c = i % {너비}.",
         "        정수 t = 토큰[r]."]
    L += 낱말풀기(형식, "t", "c", "낱값", "        ")
    L += [f"        출력[i] = 낱값 + 위치표[(위치시작 + r % 묶음안행수) * {너비} + c].", "    }", "}"]
    return L


def 흐름어텐션(정수=False, 빠른=False):
    """프롬프트 처리의 어텐션: 블록 하나(256 스레드)가 (머리, 한 문장의 질의 64 개). 키 조각(위치 64 개)마다 한 번에 — 점수를 다시
    계산하지도, 점수 표를 두지도 않는다. KV 캐시의 배치: 키는 [문장][머리][d][위치](전치), 값은 [문장][머리][위치][d].
    스레드 (tq = tid/16, tt = tid%16):
      점수 — 질의 4tq + i, 키 4tt + j (i, j < 4) 의 16 칸을 d 오름차순 곱해더하기로, × 0.125. 가린 키(t > 위치)는 −3e38.
             판의 Qᵀ [d][q] 와 Kᵀ [d][t] 에서 d 마다 네 칸씩 붙여 읽는다.
      조각의 최댓값 — 질의마다 16 레인(같은 tq)의 셔플(순서와 상관없다).
      지수 E [q][t] — 판의 Kᵀ 자리에 다시 쓴다(Kᵀ 를 다 읽은 뒤). 16 바이트 칸은 c ^ (q % 8) 에 둔다(뱅크가 겹치지 않게).
             같은 tq 의 레인만 주고받으니 워프 안의 동기화로 된다.
      합 l — 레인 tt = i 가 질의 4tq + i 의 유효한 키를 t 오름차순으로 더한다. 접기의 비율(옛비·새비)도 그 레인이 구해 셔플로 나눈다.
      가중합 o — 질의 4tq + i, 차원 4tt .. 4tt+3 의 16 칸을 t 오름차순 곱해더하기로(대각 조각은 유효한 키만), 그다음 접기.
    판: Qᵀ [64][64] 0, Kᵀ·E [64][64] 4096, V [64][64] 8192.
    격자: (머리, 문장 · 질의 조각) — 질의 조각은 뒤에서부터(일이 많은 조각을 먼저).
    정수 = 참(6단계, 흐름어텐션정수): 출력을 짧은실수로 쓰는 대신 c_proj 의 네 자리 · 정보로 바로 — 같은 값(O / L)을 정수로와 같이
    바꾼다. 머리의 한 행 64 칸은 블록 둘(32 칸)이고, 같은 tq 의 레인 여덟(tt 의 아래 셋)이 블록 하나를 네 칸씩 들고 있다 — 정수로의
    배치 그대로. 넘치는 질의(끝r 밖)는 0 으로 바꿔(쓰지 않는다) 범위 검사가 켜지지 않게.
    빠른 = 참(6단계 — 정수 판 모듈): 값은 그대로 두고 일의 차례만 바꾼다. (1) 점수의 d 반복에서 판 읽기를 곱해더하기보다 먼저 몰아
    낸다. (2) 합 l 을 가중합의 t 반복 안에서 모든 스레드가 제 질의 넷에 대해 t 오름차순으로 더한다 — 가린 키의 지수는 +0 이라 더해도
    값이 그대로(l ≥ +0)이니 유효한 키만 차례로 더한 것과 비트가 같다. 그래서 레인 넷만 일하던 차례 합이 없어지고, 접기(M · L · 비율)도
    모든 스레드가 제 질의에 대해 같은 식으로 구한다(셔플이 없다)."""
    Q0, K0, V0 = 0, 4096, 8192
    이름 = "흐름어텐션정수" if 정수 else "흐름어텐션"
    L = ["(* 프롬프트 처리의 어텐션 — 블록 하나가 (머리, 질의 64 개). 키 조각마다 점수·최댓값·지수·합·가중합·접기. 순서 약속은 커널생성.py 의 설명 *)",
         f"(* 실행한도 {이름} 256 2 *)",
         (f"[짧은실수 참조 q에서 {KV} 참조 키칸과 {KV} 참조 값칸과 짧은실수 참조 출력에 정수 묶음안행수로 정수 위치시작으로 "
          "정수 최대길이로 흐름어텐션]는 {" if not 정수 else
          f"[짧은실수 참조 q에서 {KV} 참조 키칸과 {KV} 참조 값칸과 중간정수 참조 정보와 중간정수 참조 자릿값에 정수 행수로 "
          "정수 묶음안행수로 정수 위치시작으로 정수 최대길이로 흐름어텐션정수]는 {"),
         "    정수 tid = 블록안가로().",
         "    정수 머리 = 블록가로().",
         "    정수 질조각수 = (묶음안행수 + 63) / 64.",
         "    정수 문장 = 블록세로() / 질조각수.",
         "    정수 r0 = (질조각수 - 1 - 블록세로() % 질조각수) * 64.",
         "    정수 끝r = r0 + 63.",
         "    끝r >= 묶음안행수이면 { 끝r = 묶음안행수 - 1. }",
         "    정수 p0 = 위치시작 + r0.",
         "    정수 끝조각 = (위치시작 + 끝r) / 64.",
         "    정수 행바탕 = 문장 * 묶음안행수.",
         f"    정수 캐시 = (문장 * {머리수} + 머리) * 64 * 최대길이.",
         "    짧은실수 참조 판 = 공유판48().",
         "    정수 tq = tid / 16.",
         "    정수 tt = tid % 16.",
         "    정수 우두 = tid % 32 - tt.",
         "    정수 qx = tq * 4.",
         "    정수 kx = tt * 4.",
         "    (* Qᵀ: 스레드가 질의 행 tid % 64 의 d 칸 넷(16 바이트) 넷을 읽어 [d][q] 에 *)",
         "    정수 qr = r0 + tid % 64.",
         "    qr > 끝r이면 { qr = 끝r. }",
         f"    정수 qsrc = (행바탕 + qr) * {너비} + 머리 * 64.",
         "    정수 qc = (tid / 64) * 4.",
         "    정수 qdst = qc * 64 + tid % 64."]
    for k in range(4):
        L += [f"    짧은실수 qv{k}_{u} = q[qsrc + qc + {16 * k + u}]." for u in range(4)]
        L += [f"    판[qdst + {(16 * k + u) * 64}] = qv{k}_{u}." for u in range(4)]
    L += [f"    정수 pq{i} = p0 + qx + {i}." for i in range(4)]
    L += [f"    정수 ex{i} = (qx + {i}) % 8." for i in range(4)]
    L += [f"    정수 eb{i} = {K0} + (qx + {i}) * 64." for i in range(4)]
    L += ["    정수 vq = " + f"{V0} + kx.",
          "    짧은실수 영 = 0 으로 짧은실수.",
          "    짧은실수 M = 영.",
          "    짧은실수 L = 영.",
          "    짧은실수 옛비 = 영.",
          "    짧은실수 새비 = 영.",
          "    정수 방식 = 0."]
    L += [f"    짧은실수 O{i}_{u} = 영." for i in range(4) for u in range(4)]
    if 빠른:
        L += [f"    짧은실수 M{i} = 영." for i in range(4)] + [f"    짧은실수 L{i} = 영." for i in range(4)]
    L.append("    반복 (정수 조각 = 0: 조각 <= 끝조각: 조각 += 1) {")
    I = "        "
    L.append(f"{I}정수 tb = 조각 * 64.")
    if KV == "짧은실수":
        for k in range(4):
            L += [f"{I}비동기복사16(판 에, {K0} + (tq + {16 * k}) * 64 + kx 를, 키칸 에서, 캐시 + (tq + {16 * k}) * 최대길이 + tb + kx 로).",
                  f"{I}비동기복사16(판 에, {V0} + (tq + {16 * k}) * 64 + kx 를, 값칸 에서, 캐시 + (tb + tq + {16 * k}) * 64 + kx 로)."]
        L += [f"{I}비동기묶기().", f"{I}비동기기다리기(0).", f"{I}동기화()."]
    else:
        # 반실수 판: 키·값 조각을 레지스터로 읽어 넓혀(정확) 판에 짧은실수로 — 판 위의 계산은 짧은실수 판과 같다
        for k in range(4):
            L += [f"{I}짧은실수 kh{k}_{u} = 키칸[캐시 + 조각 * 4096 + (tq + {16 * k}) * 64 + kx + {u}]." for u in range(4)]
            L += [f"{I}짧은실수 vh{k}_{u} = 값칸[캐시 + (tb + tq + {16 * k}) * 64 + kx + {u}]." for u in range(4)]
        for k in range(4):
            L += [f"{I}판[{K0} + (tq + {16 * k}) * 64 + kx + {u}] = kh{k}_{u}." for u in range(4)]
            L += [f"{I}판[{V0} + (tq + {16 * k}) * 64 + kx + {u}] = vh{k}_{u}." for u in range(4)]
        L += [f"{I}동기화()."]
    # 점수
    L += [f"{I}짧은실수 s{i}_{j} = 영." for i in range(4) for j in range(4)]
    L.append(f"{I}반복 (정수 d0 = 0: d0 < 64: d0 += 4) {{")
    L += [f"{I}    정수 qo = qx + d0 * 64.", f"{I}    정수 ko = kx + d0 * 64."]
    if 빠른:
        for dd in range(4):
            L += [f"{I}    짧은실수 a{dd}_{i} = 판[qo + {Q0 + dd * 64 + i}]." for i in range(4)]
            L += [f"{I}    짧은실수 b{dd}_{j} = 판[ko + {K0 + dd * 64 + j}]." for j in range(4)]
        for dd in range(4):
            L += [f"{I}    s{i}_{j} = 곱해더하기(a{dd}_{i}, b{dd}_{j}, s{i}_{j})." for i in range(4) for j in range(4)]
    else:
        for dd in range(4):
            L += [f"{I}    짧은실수 a{dd}_{i} = 판[qo + {Q0 + dd * 64 + i}]." for i in range(4)]
            L += [f"{I}    짧은실수 b{dd}_{j} = 판[ko + {K0 + dd * 64 + j}]." for j in range(4)]
            L += [f"{I}    s{i}_{j} = 곱해더하기(a{dd}_{i}, b{dd}_{j}, s{i}_{j})." for i in range(4) for j in range(4)]
    L.append(f"{I}}}")
    L += [f"{I}s{i}_{j} = s{i}_{j} * 0.125." for i in range(4) for j in range(4)]
    for i in range(4):
        for j in range(4):
            L.append(f"{I}tb + kx + {j} > pq{i}이면 {{ s{i}_{j} = -3.0e38. }}")
    for i in range(4):
        L.append(f"{I}짧은실수 mx{i} = 큰쪽(큰쪽(s{i}_0, s{i}_1), 큰쪽(s{i}_2, s{i}_3)).")
        L += [f"{I}mx{i} = 큰쪽(mx{i}, 아래에서받기(mx{i}, {sft}))." for sft in (8, 4, 2, 1)]
        L.append(f"{I}mx{i} = 레인에서받기(mx{i}, 우두).")
    L.append(f"{I}동기화().")
    # 지수 → E [q][t] (16 바이트 칸 tt 를 tt ^ (q % 8) 에)
    for i in range(4):
        for j in range(4):
            L.append(f"{I}짧은실수 e{i}_{j} = 근사지수(s{i}_{j} - mx{i}).")
            L.append(f"{I}tb + kx + {j} > pq{i}이면 {{ e{i}_{j} = 영. }}")
    for i in range(4):
        L.append(f"{I}정수 ec{i} = eb{i} + ((tt ^ ex{i}) * 4).")
        L += [f"{I}판[ec{i} + {j}] = e{i}_{j}." for j in range(4)]
    L.append(f"{I}워프동기화().")
    if 빠른:
        L += 빠른가중합(I, K0, V0)
        L.append(f"{I}동기화().")
        L.append("    }")
        return L + 흐름어텐션출력(정수)
    # 합과 접기의 비율 — 레인 tt = i 가 질의 4tq + i 를
    L += [f"{I}짧은실수 내큰 = mx0.",
          f"{I}tt == 1이면 {{ 내큰 = mx1. }}",
          f"{I}tt == 2이면 {{ 내큰 = mx2. }}",
          f"{I}tt == 3이면 {{ 내큰 = mx3. }}",
          f"{I}방식 = 0.",
          f"{I}tt < 4이면 {{",
          f"{I}    정수 개수 = p0 + qx + tt - tb + 1.",
          f"{I}    개수 > 64이면 {{ 개수 = 64. }}",
          f"{I}    개수 > 0이면 {{",
          f"{I}        정수 lr = {K0} + (qx + tt) * 64.",
          f"{I}        정수 lx = (qx + tt) % 8.",
          f"{I}        짧은실수 l = 영.",
          f"{I}        정수 lc = 0."]
    for c in range(16):
        L.append(f"{I}        lc = lr + (({c} ^ lx) * 4).")
        L += [f"{I}        짧은실수 lv{c}_{u} = 판[lc + {u}]." for u in range(4)]
        L += [f"{I}        {4 * c + u} < 개수이면 {{ l = l + lv{c}_{u}. }}" for u in range(4)]
    L += [
          f"{I}        조각 == 0이면 {{",
          f"{I}            방식 = 1.",
          f"{I}            M = 내큰.",
          f"{I}            L = l.",
          f"{I}        }}",
          f"{I}        아니면 {{",
          f"{I}            방식 = 2.",
          f"{I}            짧은실수 M2 = 큰쪽(M, 내큰).",
          f"{I}            옛비 = 근사지수(M - M2).",
          f"{I}            새비 = 근사지수(내큰 - M2).",
          f"{I}            L = 곱해더하기(l, 새비, L * 옛비).",
          f"{I}            M = M2.",
          f"{I}        }}",
          f"{I}    }}",
          f"{I}}}"]
    for i in range(4):
        L += [f"{I}짧은실수 옛비{i} = 레인에서받기(옛비, 우두 + {i}).",
              f"{I}짧은실수 새비{i} = 레인에서받기(새비, 우두 + {i}).",
              f"{I}정수 방식{i} = 정수레인에서받기(방식, 우두 + {i})."]
    # 가중합 — t 넷씩: E 의 네 행에서 16 바이트 하나씩, V 의 네 행에서 16 바이트 하나씩
    L += [f"{I}짧은실수 o{i}_{u} = 영." for i in range(4) for u in range(4)]

    def 몸(ind, 가림):
        out = [f"{ind}반복 (정수 t0 = 0: t0 < 64: t0 += 4) {{",
               f"{ind}    정수 t4 = t0 / 4.",
               f"{ind}    정수 vt = vq + t0 * 64."]
        for i in range(4):
            out.append(f"{ind}    정수 er{i} = eb{i} + ((t4 ^ ex{i}) * 4).")
            out += [f"{ind}    짧은실수 ev{i}_{k} = 판[er{i} + {k}]." for k in range(4)]
        for k in range(4):
            out += [f"{ind}    짧은실수 vv{k}_{u} = 판[vt + {k * 64 + u}]." for u in range(4)]
        for k in range(4):
            for i in range(4):
                if 가림:
                    out.append(f"{ind}    t0 + {k} <= 한계{i}이면 {{")
                    out += [f"{ind}        o{i}_{u} = 곱해더하기(ev{i}_{k}, vv{k}_{u}, o{i}_{u})." for u in range(4)]
                    out.append(f"{ind}    }}")
                else:
                    out += [f"{ind}    o{i}_{u} = 곱해더하기(ev{i}_{k}, vv{k}_{u}, o{i}_{u})." for u in range(4)]
        out.append(f"{ind}}}")
        return out
    L.append(f"{I}tb + 63 <= p0이면 {{")
    L += 몸(I + "    ", False)
    L.append(f"{I}}}")
    L.append(f"{I}아니면 {{")
    L += [f"{I}    정수 한계{i} = pq{i} - tb." for i in range(4)]
    L += 몸(I + "    ", True)
    L.append(f"{I}}}")
    # 접기
    for i in range(4):
        L.append(f"{I}방식{i} == 1이면 {{")
        L += [f"{I}    O{i}_{u} = o{i}_{u}." for u in range(4)]
        L.append(f"{I}}}")
        L.append(f"{I}아니면 방식{i} == 2이면 {{")
        L += [f"{I}    O{i}_{u} = 곱해더하기(o{i}_{u}, 새비{i}, O{i}_{u} * 옛비{i})." for u in range(4)]
        L.append(f"{I}}}")
    L.append(f"{I}동기화().")
    L.append("    }")
    for i in range(4):
        L.append(f"    짧은실수 L{i} = 레인에서받기(L, 우두 + {i}).")
    return L + 흐름어텐션출력(정수)


def 빠른가중합(I, K0, V0):
    """흐름어텐션(빠른 판)의 가중합 · 합 · 접기 — 질의 4tq + i 마다 모든 스레드가(같은 tq 의 레인 열여섯이 같은 값을 구한다)."""
    L = [f"{I}짧은실수 o{i}_{u} = 영." for i in range(4) for u in range(4)]
    L += [f"{I}짧은실수 ll{i} = 영." for i in range(4)]

    def 몸(ind, 가림):
        out = [f"{ind}반복 (정수 t0 = 0: t0 < 64: t0 += 4) {{",
               f"{ind}    정수 t4 = t0 / 4.",
               f"{ind}    정수 vt = vq + t0 * 64."]
        for i in range(4):
            out.append(f"{ind}    정수 er{i} = eb{i} + ((t4 ^ ex{i}) * 4).")
            out += [f"{ind}    짧은실수 ev{i}_{k} = 판[er{i} + {k}]." for k in range(4)]
        for k in range(4):
            out += [f"{ind}    짧은실수 vv{k}_{u} = 판[vt + {k * 64 + u}]." for u in range(4)]
        for k in range(4):
            for i in range(4):
                if 가림:
                    out.append(f"{ind}    t0 + {k} <= 한계{i}이면 {{")
                    out += [f"{ind}        o{i}_{u} = 곱해더하기(ev{i}_{k}, vv{k}_{u}, o{i}_{u})." for u in range(4)]
                    out.append(f"{ind}    }}")
                else:
                    out += [f"{ind}    o{i}_{u} = 곱해더하기(ev{i}_{k}, vv{k}_{u}, o{i}_{u})." for u in range(4)]
        out += [f"{ind}    ll{i} = ((((ll{i} + ev{i}_0) + ev{i}_1) + ev{i}_2) + ev{i}_3)." for i in range(4)]
        out.append(f"{ind}}}")
        return out
    L.append(f"{I}tb + 63 <= p0이면 {{")
    L += 몸(I + "    ", False)
    L.append(f"{I}}}")
    L.append(f"{I}아니면 {{")
    L += [f"{I}    정수 한계{i} = pq{i} - tb." for i in range(4)]
    L += 몸(I + "    ", True)
    L.append(f"{I}}}")
    # 접기 — 이 조각에 유효한 키가 있는 질의만(pq ≥ tb): 첫 조각이면 그대로, 아니면 비율로
    for i in range(4):
        L += [f"{I}pq{i} >= tb이면 {{",
              f"{I}    조각 == 0이면 {{",
              f"{I}        M{i} = mx{i}.", f"{I}        L{i} = ll{i}."]
        L += [f"{I}        O{i}_{u} = o{i}_{u}." for u in range(4)]
        L += [f"{I}    }}",
              f"{I}    아니면 {{",
              f"{I}        짧은실수 새큰 = 큰쪽(M{i}, mx{i}).",
              f"{I}        짧은실수 옛 = 근사지수(M{i} - 새큰).",
              f"{I}        짧은실수 새 = 근사지수(mx{i} - 새큰).",
              f"{I}        L{i} = 곱해더하기(ll{i}, 새, L{i} * 옛)."]
        L += [f"{I}        O{i}_{u} = 곱해더하기(o{i}_{u}, 새, O{i}_{u} * 옛)." for u in range(4)]
        L += [f"{I}        M{i} = 새큰.", f"{I}    }}", f"{I}}}"]
    return L


def 흐름어텐션출력(정수):
    """흐름어텐션의 마지막: 질의 4tq + i 의 출력 O / L (L{i} 가 있어야 한다)."""
    L = []
    if 정수:
        L += ["    정수 lane = tid % 32.", "    정수 정보폭 = (행수 + 63) / 64 * 64.", "    정수 b = 머리 * 2 + tt / 8."]
        for i in range(4):
            r = f"(행바탕 + r0 + qx + {i})"
            L += ["    {"]
            L += [f"        짧은실수 w{u} = O{i}_{u} / L{i}." for u in range(4)]
            L.append(f"        r0 + qx + {i} > 끝r이면 {{ " + " ".join(f"w{u} = 영." for u in range(4)) + " }")
            L += 블록바꾸기몸(lambda u: f"w{u}", lambda j: f"정수 자{j} = 0. 자{j}",
                            lambda v: f"r0 + qx + {i} <= 끝r이면 {{ 정보[b * 정보폭 + {r}] = {v}. }}", "        ")
            L.append(f"        r0 + qx + {i} <= 끝r이면 {{")
            L += [f"            자릿값[({j} * 행수 + {r}) * {너비 // 4} + b * 8 + (lane % 4) * 2 + (lane % 8) / 4] = 자{j}." for j in range(자리수)]
            L += ["        }", "    }"]
    else:
        for i in range(4):
            L.append(f"    r0 + qx + {i} <= 끝r이면 {{")
            L += [f"        출력[(행바탕 + r0 + qx + {i}) * {너비} + 머리 * 64 + kx + {u}] = O{i}_{u} / L{i}." for u in range(4)]
            L.append("    }")
    L.append("}")
    return L


def 조각계산(ind, 판바탕, q식, 키, 값, 캐시, 위치, 조각, 바탕식, 조각칸):
    """조각 하나(묶음 g = tid/64 의 64 스레드, j = tid%64): 점수(키 조각·64 + j), 조각의 최댓값, 지수, 합 l, 가중합 o.
    값 64 행은 한꺼번에 읽는다(조각이 덜 찼어도 — 캐시 안의 자리라 읽을 수 있고, 곱해더하는 것은 유효한 키뿐이다).
    판바탕: q [64], 최댓값 [8], E [4][64] 을 둘 자리. 유효한 키가 없으면 아무것도 쓰지 않는다. 블록의 모든 스레드가 함께 부른다."""
    QB, MB, EB = 판바탕, 판바탕 + 64, 판바탕 + 72
    out = [f"{ind}정수 t = {조각} * 64 + j.",
           f"{ind}정수 개수 = {위치} - {조각} * 64 + 1.",
           f"{ind}개수 > 64이면 {{ 개수 = 64. }}",
           f"{ind}정수 vb = {캐시} + {조각} * 4096 + j."]
    out += [f"{ind}짧은실수 s = -3.0e38.",
            f"{ind}t <= {위치}이면 {{",
            f"{ind}    짧은실수 a = 영."]
    if KV == "짧은실수":
        out += [f"{ind}    정수 kp = {캐시} + t.",
                f"{ind}    정수 길2 = 최대길이 * 2.",
                f"{ind}    정수 길3 = 최대길이 * 3.",
                f"{ind}    정수 길4 = 최대길이 * 4."]
    else:                                                  # 반실수 판: 키는 [조각][d][위치 64] — d 사이가 64 칸
        out += [f"{ind}    정수 kp = {캐시} + {조각} * 4096 + j.",
                f"{ind}    정수 길1 = 64.",
                f"{ind}    정수 길2 = 128.",
                f"{ind}    정수 길3 = 192.",
                f"{ind}    정수 길4 = 256."]
    for d4 in range(16):
        out += [f"{ind}    짧은실수 qa{d4}_{u} = 판[{QB + 4 * d4 + u}]." for u in range(4)]
        out += [f"{ind}    짧은실수 ka{d4}_0 = {키}[kp].",
                f"{ind}    짧은실수 ka{d4}_1 = {키}[kp + {'최대길이' if KV == '짧은실수' else '길1'}].",
                f"{ind}    짧은실수 ka{d4}_2 = {키}[kp + 길2].",
                f"{ind}    짧은실수 ka{d4}_3 = {키}[kp + 길3].",
                f"{ind}    kp = kp + 길4."]
        out += [f"{ind}    a = 곱해더하기(qa{d4}_{u}, ka{d4}_{u}, a)." for u in range(4)]
    out += [f"{ind}    s = a * 0.125.",
            f"{ind}}}",
            f"{ind}짧은실수 mx = s."]
    out += [f"{ind}mx = 큰쪽(mx, 아래에서받기(mx, {sft}))." for sft in (16, 8, 4, 2, 1)]
    out += [f"{ind}tid % 32 == 0이면 {{ 판[{MB} + tid / 32] = mx. }}",
            f"{ind}동기화().",
            f"{ind}짧은실수 m = 큰쪽(판[{MB} + g * 2], 판[{MB} + g * 2 + 1]).",
            f"{ind}짧은실수 e = 영.",
            f"{ind}t <= {위치}이면 {{ e = 근사지수(s - m). }}",
            f"{ind}판[{EB} + tid] = e.",
            f"{ind}동기화().",
            f"{ind}개수 > 0이면 {{",
            f"{ind}    정수 ebg = {EB} + g * 64.",
            f"{ind}    정수 바탕 = {바탕식}.",
            f"{ind}    j == 0이면 {{",
            f"{ind}        짧은실수 l = 영."]
    out += [f"{ind}        짧은실수 le{k} = 판[ebg + {k}]." for k in range(64)]
    out += [f"{ind}        {k} < 개수이면 {{ l = l + le{k}. }}" for k in range(64)]
    out += [f"{ind}        {조각칸}[바탕] = m.",
            f"{ind}        {조각칸}[바탕 + 1] = l.",
            f"{ind}    }}",
            f"{ind}    짧은실수 o = 영."]
    out += [f"{ind}    짧은실수 vw{k} = {값}[vb + {k * 64}]." for k in range(64)]
    out += [f"{ind}    개수 == 64이면 {{"]
    out += [f"{ind}        o = 곱해더하기(판[ebg + {k}], vw{k}, o)." for k in range(64)]
    out += [f"{ind}    }}",
            f"{ind}    아니면 {{"]
    out += [f"{ind}        {k} < 개수이면 {{ o = 곱해더하기(판[ebg + {k}], vw{k}, o). }}" for k in range(64)]
    out += [f"{ind}    }}",
            f"{ind}    {조각칸}[바탕 + 4 + j] = o.",
            f"{ind}}}",
            f"{ind}동기화()."]
    return out


def 조각계산워프(ind, 판바탕, 키, 값, 캐시, 위치, 조각, 바탕식, 조각칸):
    """반실수 판, 생성 메가커널의 긴 문맥 — 워프 하나(레인 rl = tid % 32, 워프 rw = tid / 32)가 조각 하나. 값은 조각계산과 같다(같은
    순서 약속 — 사슬과 연산 순서가 그대로이고, 일을 나누는 모양만 다르다):
      점수 — 레인 r 이 키 t₀ + 2r, t₀ + 2r + 1 둘을 d 오름차순 곱해더하기로. 키는 [조각][d][위치 64] 라 이웃한 반실수 둘을 한 번에 읽는다
             (워프 한 번에 128 바이트 — 64 스레드가 2 바이트씩 읽던 것의 두 배).
      최댓값 — 워프 셔플(순서와 상관없다). 지수 E [64] 는 워프의 판 자리에(워프 안의 동기화).
      합 l — 레인 0 이 t 오름차순으로 0 에서부터. 가중합 — 레인 r 이 차원 2r, 2r + 1 둘을 t 오름차순 곱해더하기로(값 행의 이웃한 둘).
    블록 동기화가 없다 — 워프들이 따로 간다. 판바탕: q [64] (블록 공유), E [워프 8][64] 는 판바탕 + 72 + rw·64."""
    QB, EB = 판바탕, 판바탕 + 72
    out = [f"{ind}정수 t0 = {조각} * 64.",
           f"{ind}정수 개수 = {위치} - t0 + 1.",
           f"{ind}개수 > 64이면 {{ 개수 = 64. }}",
           f"{ind}정수 ta = t0 + 2 * rl.",
           f"{ind}정수 eb = {EB} + rw * 64.",
           f"{ind}짧은실수 sa = -3.0e38.",
           f"{ind}짧은실수 sb = -3.0e38.",
           f"{ind}ta <= {위치}이면 {{",
           f"{ind}    정수 kb = {캐시} + {조각} * 4096 + 2 * rl.",
           f"{ind}    짧은실수 a0 = 영.",
           f"{ind}    짧은실수 a1 = 영."]
    for d in range(64):
        out += [f"{ind}    짧은실수 qd{d} = 판[{QB + d}].",
                f"{ind}    짧은실수 ka{d} = {키}[kb + {64 * d}].",
                f"{ind}    짧은실수 kc{d} = {키}[kb + {64 * d + 1}].",
                f"{ind}    a0 = 곱해더하기(qd{d}, ka{d}, a0).",
                f"{ind}    a1 = 곱해더하기(qd{d}, kc{d}, a1)."]
    out += [f"{ind}    sa = a0 * 0.125.",
            f"{ind}    ta + 1 <= {위치}이면 {{ sb = a1 * 0.125. }}",
            f"{ind}}}",
            f"{ind}짧은실수 mx = 큰쪽(sa, sb)."]
    out += [f"{ind}mx = 큰쪽(mx, 아래에서받기(mx, {sft}))." for sft in (16, 8, 4, 2, 1)]
    out += [f"{ind}짧은실수 m = 레인에서받기(mx, 0).",
            f"{ind}짧은실수 ea = 영.",
            f"{ind}짧은실수 ec = 영.",
            f"{ind}ta <= {위치}이면 {{ ea = 근사지수(sa - m). }}",
            f"{ind}ta + 1 <= {위치}이면 {{ ec = 근사지수(sb - m). }}",
            f"{ind}판[eb + 2 * rl] = ea.",
            f"{ind}판[eb + 2 * rl + 1] = ec.",
            f"{ind}워프동기화().",
            f"{ind}개수 > 0이면 {{",
            f"{ind}    정수 바탕 = {바탕식}.",
            f"{ind}    rl == 0이면 {{",
            f"{ind}        짧은실수 l = 영."]
    out += [f"{ind}        짧은실수 le{k} = 판[eb + {k}]." for k in range(64)]
    out += [f"{ind}        {k} < 개수이면 {{ l = l + le{k}. }}" for k in range(64)]
    out += [f"{ind}        {조각칸}[바탕] = m.",
            f"{ind}        {조각칸}[바탕 + 1] = l.",
            f"{ind}    }}",
            f"{ind}    정수 vb = {캐시} + {조각} * 4096 + 2 * rl.",
            f"{ind}    짧은실수 o0 = 영.",
            f"{ind}    짧은실수 o1 = 영.",
            f"{ind}    반복 (정수 t16 = 0: t16 < 64: t16 += 16) {{"]
    for k in range(16):
        out += [f"{ind}        짧은실수 va{k} = {값}[vb + t16 * 64 + {64 * k}].",
                f"{ind}        짧은실수 vc{k} = {값}[vb + t16 * 64 + {64 * k + 1}]."]
    out += [f"{ind}        개수 >= t16 + 16이면 {{"]
    for k in range(16):
        out += [f"{ind}            o0 = 곱해더하기(판[eb + t16 + {k}], va{k}, o0).",
                f"{ind}            o1 = 곱해더하기(판[eb + t16 + {k}], vc{k}, o1)."]
    out += [f"{ind}        }}",
            f"{ind}        아니면 {{"]
    for k in range(16):
        out += [f"{ind}            t16 + {k} < 개수이면 {{",
                f"{ind}                o0 = 곱해더하기(판[eb + t16 + {k}], va{k}, o0).",
                f"{ind}                o1 = 곱해더하기(판[eb + t16 + {k}], vc{k}, o1).",
                f"{ind}            }}"]
    out += [f"{ind}        }}",
            f"{ind}    }}",
            f"{ind}    {조각칸}[바탕 + 4 + 2 * rl] = o0.",
            f"{ind}    {조각칸}[바탕 + 5 + 2 * rl] = o1.",
            f"{ind}}}",
            f"{ind}워프동기화()."]                    # 다음 조각이 E 를 덮어쓰기 전에
    return out


def 접기(ind, 조각칸, 바탕, 조각끝, 목적, FB):
    """조각 0 … 조각끝 의 (m, l, o) 를 차례로 접어 목적 = O / L (목적 식은 차원 tid, tid < 64 에서). 블록의 256 스레드가 함께 부른다.
    값은 정의대로 차례로 접는 것과 비트까지 같다: 누적 최댓값 P_σ = max(P_{σ−1}, m_σ) 는 순서와 상관없이 같고(스레드 0 이 차례로),
    비율 가_σ = 근사지수(P_{σ−1} − P_σ)·나_σ = 근사지수(m_σ − P_σ) 는 조각마다 따로 구할 수 있다(스레드마다). 그다음 사슬
    L = 곱해더하기(l_σ, 나_σ, L·가_σ) 는 스레드 64 가, O_d = 곱해더하기(o_σd, 나_σ, O_d·가_σ) 는 스레드 d 가 σ 차례로.
    판: m [256] FB, P [256] FB+256, 가 [256] FB+512, 나 [256] FB+768, L FB+1024 — 조각은 256 개(위치 16384)까지."""
    FM, FP, FA, FN, FL = FB, FB + 256, FB + 512, FB + 768, FB + 1024
    if KV != "짧은실수":
        return 빠른접기(ind, 조각칸, 바탕, 조각끝, 목적, FB)
    out = [f"{ind}정수 조각수끝 = {조각끝} + 1.",
           f"{ind}반복 (정수 c = tid: c < 조각수끝: c += 256) {{ 판[{FM} + c] = {조각칸}[{바탕} + c * 68]. }}",
           f"{ind}동기화().",
           f"{ind}tid == 0이면 {{",
           f"{ind}    짧은실수 누적 = 판[{FM}].",
           f"{ind}    판[{FP}] = 누적.",
           f"{ind}    반복 (정수 c = 1: c < 조각수끝: c += 1) {{ 누적 = 큰쪽(누적, 판[{FM} + c]). 판[{FP} + c] = 누적. }}",
           f"{ind}}}",
           f"{ind}동기화().",
           f"{ind}반복 (정수 c = tid + 1: c < 조각수끝: c += 256) {{",
           f"{ind}    판[{FA} + c] = 근사지수(판[{FP} + c - 1] - 판[{FP} + c]).",
           f"{ind}    판[{FN} + c] = 근사지수(판[{FM} + c] - 판[{FP} + c]).",
           f"{ind}}}",
           f"{ind}동기화().",
           f"{ind}tid == 64이면 {{",
           f"{ind}    짧은실수 L = {조각칸}[{바탕} + 1].",
           f"{ind}    반복 (정수 c = 1: c < 조각수끝: c += 1) {{ L = 곱해더하기({조각칸}[{바탕} + c * 68 + 1], 판[{FN} + c], L * 판[{FA} + c]). }}",
           f"{ind}    판[{FL}] = L.",
           f"{ind}}}",
           f"{ind}짧은실수 O = 0 으로 짧은실수.",
           f"{ind}tid < 64이면 {{",
           f"{ind}    O = {조각칸}[{바탕} + 4 + tid].",
           f"{ind}    정수 c = 1.",
           f"{ind}    반복 (: c + 7 < 조각수끝: c += 8) {{"]
    out += [f"{ind}        짧은실수 oo{k} = {조각칸}[{바탕} + (c + {k}) * 68 + 4 + tid]." for k in range(8)]
    out += [f"{ind}        O = 곱해더하기(oo{k}, 판[{FN} + c + {k}], O * 판[{FA} + c + {k}])." for k in range(8)]
    out += [f"{ind}    }}",
            f"{ind}    반복 (: c < 조각수끝: c += 1) {{ O = 곱해더하기({조각칸}[{바탕} + c * 68 + 4 + tid], 판[{FN} + c], O * 판[{FA} + c]). }}",
            f"{ind}}}",
            f"{ind}동기화().",
            f"{ind}tid < 64이면 {{ {목적} = O / 판[{FL}]. }}"]
    return out


def 빠른접기(ind, 조각칸, 바탕, 조각끝, 목적, FB):
    """접기와 같은 값(같은 순서 약속) — 기다림만 줄였다(4단계 2, 반실수 판에서 먼저; 짧은실수 판은 4e 의 바이트 대조 뒤에).
      누적 최댓값: 스레드 c 가 m_c 를 들고 워프 셔플로 앞쪽 레인의 최댓값을, 그다음 앞 워프들의 최댓값을 — 최댓값은 순서와 상관없이
                  같으므로 P_σ 가 차례로 구한 것과 같다.
      L 사슬: l_σ 를 m_σ 와 함께 판에 올려 두고(스레드 64 가 전역 메모리를 걸음마다 기다리지 않게) 여덟 개씩 먼저 읽는다 — 사슬의 순서는 그대로.
    판: m [256] FB, P [256] FB+256, 가 [256] FB+512, 나 [256] FB+768, L FB+1024, l [256] FB+1028, 워프 최댓값 [8] FB+1284."""
    FM, FP, FA, FN, FL, FLV, FW = FB, FB + 256, FB + 512, FB + 768, FB + 1024, FB + 1028, FB + 1284
    out = [f"{ind}정수 조각수끝 = {조각끝} + 1.",
           f"{ind}반복 (정수 c = tid: c < 조각수끝: c += 256) {{",
           f"{ind}    판[{FM} + c] = {조각칸}[{바탕} + c * 68].",
           f"{ind}    판[{FLV} + c] = {조각칸}[{바탕} + c * 68 + 1].",
           f"{ind}}}",
           f"{ind}동기화().",
           f"{ind}{{",
           f"{ind}    짧은실수 pv = -3.0e38.",
           f"{ind}    tid < 조각수끝이면 {{ pv = 판[{FM} + tid]. }}",
           f"{ind}    정수 레인 = tid % 32."]
    for sft in (1, 2, 4, 8, 16):
        out += [f"{ind}    정수 kk{sft} = 레인 - {sft}.",
                f"{ind}    kk{sft} < 0이면 {{ kk{sft} = 레인. }}",
                f"{ind}    pv = 큰쪽(pv, 레인에서받기(pv, kk{sft})).",]
    out += [f"{ind}    레인 == 31이면 {{ 판[{FW} + tid / 32] = pv. }}",
            f"{ind}    동기화().",
            f"{ind}    반복 (정수 w = 0: w < tid / 32: w += 1) {{ pv = 큰쪽(pv, 판[{FW} + w]). }}",
            f"{ind}    tid < 조각수끝이면 {{ 판[{FP} + tid] = pv. }}",
            f"{ind}}}",
            f"{ind}동기화().",
            f"{ind}반복 (정수 c = tid + 1: c < 조각수끝: c += 256) {{",
            f"{ind}    판[{FA} + c] = 근사지수(판[{FP} + c - 1] - 판[{FP} + c]).",
            f"{ind}    판[{FN} + c] = 근사지수(판[{FM} + c] - 판[{FP} + c]).",
            f"{ind}}}",
            f"{ind}동기화().",
            f"{ind}tid == 64이면 {{",
            f"{ind}    짧은실수 L = 판[{FLV}].",
            f"{ind}    정수 cl = 1.",
            f"{ind}    반복 (: cl + 7 < 조각수끝: cl += 8) {{"]
    out += [f"{ind}        짧은실수 la{k} = 판[{FLV} + cl + {k}]." for k in range(8)]
    out += [f"{ind}        짧은실수 lb{k} = 판[{FN} + cl + {k}]." for k in range(8)]
    out += [f"{ind}        짧은실수 lc{k} = 판[{FA} + cl + {k}]." for k in range(8)]
    out += [f"{ind}        L = 곱해더하기(la{k}, lb{k}, L * lc{k})." for k in range(8)]
    out += [f"{ind}    }}",
            f"{ind}    반복 (: cl < 조각수끝: cl += 1) {{ L = 곱해더하기(판[{FLV} + cl], 판[{FN} + cl], L * 판[{FA} + cl]). }}",
            f"{ind}    판[{FL}] = L.",
            f"{ind}}}",
            f"{ind}짧은실수 O = 0 으로 짧은실수.",
            f"{ind}tid < 64이면 {{",
            f"{ind}    O = {조각칸}[{바탕} + 4 + tid].",
            f"{ind}    정수 c = 1.",
            f"{ind}    반복 (: c + 31 < 조각수끝: c += 32) {{"]       # o 32 개를 먼저 읽고(L2 를 한 번 기다리고) 사슬은 차례로
    out += [f"{ind}        짧은실수 op{k} = {조각칸}[{바탕} + (c + {k}) * 68 + 4 + tid]." for k in range(32)]
    out += [f"{ind}        O = 곱해더하기(op{k}, 판[{FN} + c + {k}], O * 판[{FA} + c + {k}])." for k in range(32)]
    out += [f"{ind}    }}",
            f"{ind}    반복 (: c + 7 < 조각수끝: c += 8) {{"]
    out += [f"{ind}        짧은실수 oo{k} = {조각칸}[{바탕} + (c + {k}) * 68 + 4 + tid]." for k in range(8)]
    out += [f"{ind}        O = 곱해더하기(oo{k}, 판[{FN} + c + {k}], O * 판[{FA} + c + {k}])." for k in range(8)]
    out += [f"{ind}    }}",
            f"{ind}    반복 (: c < 조각수끝: c += 1) {{ O = 곱해더하기({조각칸}[{바탕} + c * 68 + 4 + tid], 판[{FN} + c], O * 판[{FA} + c]). }}",
            f"{ind}}}",
            f"{ind}동기화().",
            f"{ind}tid < 64이면 {{ {목적} = O / 판[{FL}]. }}"]
    return out


def 조각어텐션():
    """생성(문장마다 행 하나)의 어텐션 (가): 블록 하나(256 스레드)가 (행, 머리)의 키 조각 넷 — 묶음 g = tid/64 가 조각 블록·4 + g.
    조각마다 (m, l, o[64]) 를 조각칸 [행][머리][조각 (최대길이/64)][68] 에(m 0, l 1, o 4..67). 격자: (조각 묶음, 행 · 머리)."""
    L = ["(* 생성의 어텐션 (가) — 블록 하나가 (행, 머리)의 키 조각 넷. 순서 약속은 커널생성.py 의 설명 *)",
         "(* 실행한도 조각어텐션 256 2 *)",
         f"[짧은실수 참조 q에서 {KV} 참조 키칸과 {KV} 참조 값칸과 짧은실수 참조 조각칸에 정수 묶음안행수로 정수 위치시작으로 "
         "정수 최대길이로 조각어텐션]는 {",
         "    정수 tid = 블록안가로().",
         f"    정수 행 = 블록세로() / {머리수}.",
         f"    정수 머리 = 블록세로() % {머리수}.",
         "    정수 g = tid / 64.",
         "    정수 j = tid % 64.",
         "    정수 조각 = 블록가로() * 4 + g.",
         "    정수 위치 = 위치시작 + 행 % 묶음안행수.",
         f"    정수 캐시 = ((행 / 묶음안행수) * {머리수} + 머리) * 64 * 최대길이.",
         "    짧은실수 참조 판 = 공유판4().",
         "    짧은실수 영 = 0 으로 짧은실수.",
         f"    tid < 64이면 {{ 판[tid] = q[행 * {너비} + 머리 * 64 + tid]. }}",
         "    동기화()."]
    L += 조각계산("    ", 0, None, "키칸", "값칸", "캐시", "위치", "조각",
                  f"((행 * {머리수} + 머리) * (최대길이 / 64) + 조각) * 68", "조각칸")
    L.append("}")
    return L


def 조각접기():
    """생성의 어텐션 (나): 블록 하나(256 스레드)가 (행, 머리) 하나 — 조각 0, 1, … 의 (m, l, o) 를 위치 순서대로 접는다(접기의 설명)."""
    L = ["(* 생성의 어텐션 (나) — 조각들을 위치 순서대로 접는다. 순서 약속은 커널생성.py 의 설명 *)",
         "[짧은실수 참조 조각칸에서 짧은실수 참조 출력에 정수 행수로 정수 묶음안행수로 정수 위치시작으로 정수 최대길이로 조각접기]는 {",
         "    정수 tid = 블록안가로().",
         "    정수 쌍 = 블록가로().",
         f"    정수 행 = 쌍 / {머리수}.",
         f"    정수 머리 = 쌍 % {머리수}.",
         "    정수 조각끝 = (위치시작 + 행 % 묶음안행수) / 64.",
         "    정수 바탕 = 쌍 * (최대길이 / 64) * 68.",
         "    짧은실수 참조 판 = 공유판8()."]
    L += 접기("    ", "조각칸", "바탕", "조각끝", f"출력[행 * {너비} + 머리 * 64 + tid]", 0)
    L += ["}"]
    return L


def 생성메가(G=120, U=16, T=256):
    """토큰 생성(배치 1)을 커널 하나로 — 협력 실행 한 번에 토큰 n 개. 블록 G 개(T 스레드)가 모두 함께 올라 있고, 단계 사이는
    격자 장벽(원자더하기·획득읽기)이다. 단계: 층마다 [층정규화1 + c_attn + KV] [어텐션] [c_proj + 잔차] [층정규화2 + c_fc + GELU]
    [mlp c_proj + 잔차] → 마지막 층정규화 + 로짓 + 다음 토큰(블록 0 이 그 자리에서 다음 걸음의 임베딩까지). 어텐션은 머리마다 블록
    10 개가 키 조각을 나눠 맡고 마지막에 도착한 블록이 접는다. c_attn 단계에 일이 없는 블록이 지난 키·값을 L2 로 미리 올린다. 단계마다 산술은 따로 도는 커널(줄층정규화·줄선형1·조각어텐션·조각접기·가장큰번호)과
    같다. 블록은 T = 256 스레드 — 행렬곱 단계에서는 두 반쪽(128 스레드씩)이 서로 다른 열 묶음을 맡는다. 일이 없는 블록과 일을 마친 블록은 다음 단계의 가중치를
    비동기복사로 L2 에 미리 올린다(버림칸에 — 값과는 상관없다).
    판(짧은실수): x [3072] 0, 가닥 합치기 [2][64] 3072, 층정규화 [128] 3200, 어텐션 [1348] 3328, 최댓값 [64] 4676, 버림칸 [1024] 4740.
    G·T·U 는 재서 정했다: G = 120 (SM 60 × 2 — 240 은 장벽과 겹치는 층정규화가 늘어 더 느렸다), T = 256 (128 보다 로짓 단계가
    빠르다), 층의 행렬곱은 48 개씩·로짓은 16 개씩 먼저 읽는다."""
    X크기 = max(너비, 확장폭)                                # 판의 x — 행렬곱의 입력(깊이 너비 · 확장폭)
    XS, RD, LT, AT, MX, DM = 0, X크기, X크기 + 128, X크기 + 256, X크기 + 1604, X크기 + 1668
    정수 = 계약 == "정수" and 층형식 != "짧은실수"
    # 정수 판(6단계): 판을 40 KB 로(공유메모리2 의 4 KB 와 합쳐 블록당 정적 한도 48 KB 안) — 네 자리 [자리 4][깊이] 바이트 5764 부터
    # (낱말 3072), 블록 마법수 M' [블록 96][4] 8836 부터, M_0 [블록 96] 9220 부터, 블록 값 u [블록][열 묶음] 9316 부터(768 칸까지)
    DX, DMG, DM0, US = 5764, 8836, 9220, 9316
    SD = None
    if not 작은가():                                       # 7단계(큰 깊이): 네 자리는 x 의 자리에(정수판바꾸기제자리), M_0 · u · 척도는 버림칸 뒤에
        DX, DM0 = XS, DM + 1024
        US = DM0 + X크기 // 32
        SD = US + 800
    판끝 = (SD + 800) if (정수 and SD is not None) else DM + 1024
    판크기 = (40 if 정수 else 24) if 작은가() else next(kb for kb in range(4, 49, 4) if 판끝 * 4 <= kb * 1024)
    L = []
    L.append("(* 생성 메가커널 — 커널생성.py 의 설명. 협력 실행으로만 띄운다(블록이 모두 함께 올라 있어야 장벽이 끝난다) *)")
    L.append(f"(* 실행한도 생성메가 {T} {G // 60} *)")
    낱말 = ("짧은실수 참조 낱말표와 짧은실수 참조 위치표와 짧은실수 참조 전치낱말표와 " if 낱말형식 == "짧은실수" else
           가중선언("낱말표", "낱말척도", 낱말형식) + "짧은실수 참조 위치표와 ")
    가중 = {k: 가중선언(f"{k}가중", f"{k}척도", 층형식) for k in ("주의", "투영", "확장", "축소")}
    L.append("[정수 참조 토큰칸에 " + 낱말 +
             "짧은실수 참조 첫감마와 짧은실수 참조 첫베타와 " + 가중["주의"] + "짧은실수 참조 주의치우침과 " +
             가중["투영"] + "짧은실수 참조 투영치우침과 짧은실수 참조 둘감마와 짧은실수 참조 둘베타와 " +
             가중["확장"] + "짧은실수 참조 확장치우침과 " + 가중["축소"] + "짧은실수 참조 축소치우침과 "
             "짧은실수 참조 끝감마와 짧은실수 참조 끝베타와 " + (정수KV선언() + " " if KV == "정수" else f"{KV} 참조 키칸과 {KV} 참조 값칸과 ") +
             "짧은실수 참조 숨칸과 짧은실수 참조 질의칸과 짧은실수 참조 주의출력과 짧은실수 참조 확장출력과 짧은실수 참조 로짓칸과 "
             "짧은실수 참조 부분값과 정수 참조 부분번호와 정수 참조 장벽과 정수 참조 시각칸과 짧은실수 참조 조각칸과 정수 참조 주의셈과 "
             "정수 시작위치로 정수 생성수로 정수 최대길이로 정수 캐시문장수로 정수 기록으로 정수 시각기록으로 생성메가]는 {")
    L += ["    정수 tid = 블록안가로().",
          "    정수 블록 = 블록가로().",
          "    정수 가닥 = (tid % 128) / 32.",
          "    정수 tx = tid % 32.",
          "    정수 반 = tid / 128.",
          f"    짧은실수 참조 판 = 공유판{판크기}().",
          "    정수 참조 번판 = 공유메모리2().",
          "    짧은실수 영 = 0 으로 짧은실수.",
          "    정수 장벽수 = 0.",
          "    정수 옛 = 0.",
          "    정수 토큰 = 0.",
          "    정수 위치 = 0.",
          f"    정수 캐시크기 = 캐시문장수 * 최대길이 * {너비}."]
    if KV == "정수":                                       # 9단계: 층마다 키(값) 캐시 낱말 수 — 머리수 · 2 자리 · 최대길이 · 16 낱말 = 최대길이 · 너비 / 2
        L += [f"    정수 캐시정수 = 캐시문장수 * 최대길이 * {너비 // 2}.",
              "    짧은정수 참조 판s = 판 으로 짧은정수 참조.",
              "    부호없는 작은정수 참조 값바이트 = 값칸 으로 부호없는 작은정수 참조."]
    # 양자 판: L2 미리 올리기는 가중치의 자리를 짧은실수 참조로 본다(밝힌 변환 — 값을 읽지 않고 올리기만 한다, 4 바이트 단위)
    if 층형식 != "짧은실수":
        L += [f"    짧은실수 참조 {k}넓 = {k}가중 으로 짧은실수 참조." for k in ("주의", "투영", "확장", "축소")]
    if 낱말형식 != "짧은실수":
        L.append("    짧은실수 참조 낱말넓 = 낱말표 으로 짧은실수 참조.")
    모양 = {"주의": (너비, 3 * 너비), "투영": (너비, 너비), "확장": (너비, 확장폭), "축소": (확장폭, 너비)}

    if 정수:
        L += ["    중간정수 참조 판i = 판 으로 중간정수 참조.", "    작은정수 참조 판b = 판 으로 작은정수 참조.",
              "    짧은실수 참조 판d = 번판 으로 짧은실수 참조."]

    def 층넓(k):
        """양자 가중치 한 층의 4 바이트 단위 수(값 + 척도)."""
        return sum((층크기정수 if 정수 else 층크기)(층형식, *모양[k])) // 4

    def 장벽(ind):
        return [f"{ind}동기화().",
                f"{ind}tid == 0이면 {{",
                f"{ind}    울타리().",
                f"{ind}    옛 = 원자더하기(장벽 에, 0 를, 1 로).",
                f"{ind}    장벽수 = 장벽수 + 1.",
                f"{ind}    (획득읽기(장벽 에서, 0 로) < 장벽수 * {G}) 동안 {{ }}",
                f"{ind}    (시각기록 > 0 그리고 블록 == 시각기록 - 1)이면 {{ 시각칸[장벽수 - 1] = 시각(). }}",
                f"{ind}    울타리().",
                f"{ind}}}",
                f"{ind}동기화()."]

    def 미리(원본, 바탕, 수, ind):
        """원본[바탕 .. 바탕 + 수) 를 L2 로 — 256 바이트마다 넓게미리올리기 하나(버림칸에), 블록들이 나눠서."""
        return [f"{ind}반복 (정수 미 = (블록 * {T} + tid) * 64: 미 < {수}: 미 += {G * T * 64}) {{",
                f"{ind}    넓게미리올리기(판 에, {DM} + tid * 4 를, {원본} 에서, {바탕} + 미 로).",
                f"{ind}}}",
                f"{ind}비동기묶기()."]

    def x자리(c, K, i):
        """판의 입력 x 에서 칸 c = tid + T·i 의 자리. 짧은실수 판은 XS + c 그대로, 양자 판은 가닥끼리 붙여 —
        XS + (c % 4)·(K/4) + c / 4 (가닥 g 가 읽는 k = 32·kb + g + 4i 여덟 칸이 이어진다 — 넷씩 묶어 읽는다. 값과는 상관없다)."""
        if 층형식 == "짧은실수" or 정수:
            return f"{XS} + {c}"
        assert T % 4 == 0
        return f"{XS} + (tid % 4) * {K // 4} + tid / 4 + {T // 4 * i}"

    def 층정규화(감마, 베타, 바탕, ind):
        """숨칸 [768] → 판[x]. 워프 0 의 레인 l 이 가상 스레드 l + 32k (k < 8) 의 부분합(칸 v, v+256, v+512 를 0 에서부터)을 만들고,
        반씩 접기 128·64·32 는 레인 안에서, 16..1 은 셔플로 — 줄층정규화(블록 판)와 같은 짝·같은 순서라 비트가 같다."""
        def 나무(접두, 결과, ind2):
            return [f"{ind2}짧은실수 {결과} = (({접두}0 + {접두}4) + ({접두}2 + {접두}6)) + (({접두}1 + {접두}5) + ({접두}3 + {접두}7))."] + \
                   [f"{ind2}{결과} = {결과} + 아래에서받기({결과}, {sft})." for sft in (16, 8, 4, 2, 1)] + \
                   [f"{ind2}{결과} = 레인에서받기({결과}, 0)."]
        out = [f"{ind}{{", f"{ind}    tid < 32이면 {{"]
        J = ind + "        "
        for k in range(8):
            out += [f"{J}짧은실수 x{k}_{j} = 숨칸[tid + {32 * k + 256 * j}]." for j in range(칸수(k))]
            out.append(f"{J}짧은실수 p{k} = {차례합([f'x{k}_{j}' for j in range(칸수(k))])}.")
        out += 나무("p", "합", J)
        out.append(f"{J}짧은실수 평균0 = 합 / {너비}.0.")
        for k in range(8):
            out += [f"{J}짧은실수 e{k}_{j} = x{k}_{j} - 평균0." for j in range(칸수(k))]
            out.append(f"{J}짧은실수 r{k} = {차례합([f'e{k}_{j} * e{k}_{j}' for j in range(칸수(k))])}.")
        out += 나무("r", "제곱합", J)
        out += [f"{J}tid == 0이면 {{ 판[{LT}] = 평균0. 판[{LT} + 1] = 1.0 / 제곱근(제곱합 / {너비}.0 + 0.00001). }}",
                f"{ind}    }}",
                f"{ind}    동기화().",
                f"{ind}    짧은실수 평균 = 판[{LT}].",
                f"{ind}    짧은실수 역표준 = 판[{LT} + 1]."]
        for i in range((너비 + T - 1) // T):
            c = f"tid + {T * i}"
            줄 = f"판[{x자리(c, 너비, i)}] = (숨칸[{c}] - 평균) * 역표준 * {감마}[{바탕} + {c}] + {베타}[{바탕} + {c}]."
            out.append(f"{ind}    {줄}" if T * (i + 1) <= 너비 else f"{ind}    {c} < {너비}이면 {{ {줄} }}")
        out += [f"{ind}    동기화().", f"{ind}}}"]
        return out

    def 옮겨두기(원본, 수, ind):
        out = [f"{ind}{{"]
        for i in range((수 + T - 1) // T):
            줄 = f"판[{x자리(f'tid + {T * i}', 수, i)}] = {원본}[tid + {T * i}]."
            out.append(f"{ind}    {줄}" if T * (i + 1) <= 수 else f"{ind}    tid + {T * i} < {수}이면 {{ {줄} }}")
        out += [f"{ind}    동기화().", f"{ind}}}"]
        return out

    def 줄곱(가중, 가중바탕, 치우침식, K, N, 끝식, ind, 최대=False, U=U, 입력=None):
        """판[x] (K) × 가중[가중바탕 + k·N + n] — 줄선형1 과 같은 산술(가닥 4, ((p0+p2)+(p1+p3)) + 치우침). 끝식(v, 열) = 끝손질 줄들."""
        groups = (N + 31) // 32
        x = (lambda e: f"{입력}[{e}]") if 입력 else (lambda e: f"판[{XS} + {e}]")
        out = [f"{ind}반복 (정수 cg0 = 블록: cg0 < {groups}: cg0 += {2 * G}) {{",
               f"{ind}    정수 cg = cg0 + 반 * {G}.",
               f"{ind}    정수 열 = cg * 32 + tx.",
               f"{ind}    정수 c = 열.",
               f"{ind}    c >= {N}이면 {{ c = {N} - 1. }}",
               f"{ind}    정수 rb = {RD} + 반 * 64.",
               f"{ind}    짧은실수 a = 영.",
               f"{ind}    cg < {groups}이면 {{"]
        out += [f"{ind}        짧은실수 w{u} = 영." for u in range(U)]
        out += [f"{ind}        정수 k = 가닥.",
                f"{ind}        반복 (: k + {4 * (U - 1)} < {K}: k += {4 * U}) {{"]
        out += [f"{ind}            w{u} = {가중}[{가중바탕} + (k + {4 * u}) * {N} + c]." for u in range(U)]
        out += [f"{ind}            a = 곱해더하기({x(f'k + {4 * u}')}, w{u}, a)." for u in range(U)]
        out += [f"{ind}        }}",
                f"{ind}        반복 (: k < {K}: k += 4) {{ a = 곱해더하기({x('k')}, {가중}[{가중바탕} + k * {N} + c], a). }}",
                f"{ind}    }}",
                f"{ind}    가닥 >= 2이면 {{ 판[rb + (가닥 - 2) * 32 + tx] = a. }}",
                f"{ind}    동기화().",
                f"{ind}    가닥 < 2이면 {{ a = a + 판[rb + 가닥 * 32 + tx]. }}",
                f"{ind}    동기화().",
                f"{ind}    가닥 == 1이면 {{ 판[rb + tx] = a. }}",
                f"{ind}    동기화().",
                f"{ind}    (가닥 == 0 그리고 cg < {groups} 그리고 열 < {N})이면 {{",
                f"{ind}        짧은실수 v = (a + 판[rb + tx]) + {치우침식}."]
        out += [f"{ind}        " + x for x in 끝식]
        out += [f"{ind}    }}",
                f"{ind}    동기화().",
                f"{ind}}}"]
        return out

    def 양자줄곱(값, 척, 형식, 층, K, N, 치우침식, 끝식, ind, UB):
        """줄곱의 양자 판 — 같은 스레드 배치(반 · 가닥 · tx), 같은 순서(가닥 g 가 k = 32·kb + g + 4i 를 오름차순 곱해더하기), 같은
        합치기와 끝손질. 층 l 의 값은 값[l · 층값 …], 척도는 척[l · 층척 …] (원소 단위 — 호스트가 층마다 [값][척도] 를 잇는다).
        칸은 UB 개씩 두 벌의 레지스터로 번갈아 읽는다(한 벌을 풀어 곱해더하는 동안 다음 벌이 온다). 입력 x 는 판에 가닥끼리 붙여
        둔 것(x자리)이라 여덟 칸을 넷씩 묶어 읽는다."""
        groups = (N + 31) // 32
        KB = K // 32
        assert KB % (2 * UB) == 0
        vb, sb = 층크기(형식, K, N)
        층값 = (vb + sb) // (2 if 형식 == "F16" else 4)
        층척 = (vb + sb) // 2
        e0, 걸음 = 칸자리(형식, "가닥", "c", N)
        걸음 = int(걸음)
        층식 = lambda a: "" if 층 == "0" else f"{층} * {a} + "
        out = [f"{ind}반복 (정수 cg0 = 블록: cg0 < {groups}: cg0 += {2 * G}) {{",
               f"{ind}    정수 cg = cg0 + 반 * {G}.",
               f"{ind}    정수 열 = cg * 32 + tx.",
               f"{ind}    정수 c = 열.",
               f"{ind}    c >= {N}이면 {{ c = {N} - 1. }}",
               f"{ind}    정수 rb = {RD} + 반 * 64.",
               f"{ind}    짧은실수 a = 영.",
               f"{ind}    cg < {groups}이면 {{",
               f"{ind}        짧은실수 wv = 영.",
               f"{ind}        정수 xb = {XS} + 가닥 * {K // 4}.",
               f"{ind}        정수 qe = {층식(층값)}{e0}.",
               f"{ind}        정수 qs = {층식(층척)}c."]
        for b in range(2 * UB):
            out += 칸선언(형식, f"q{b}", ind + "        ")

        def 읽기(벌, ind2):
            """칸 UB 개(지금의 qe · qs 부터)를 벌(0 · 1)의 레지스터로 — 그리고 qe · qs 를 UB 칸 뒤로."""
            o = []
            for b in range(UB):
                자리 = f"qe + {b * 걸음}" if b else "qe"
                o += 칸읽기(형식, 값, 척, 자리, f"qs + {b * N}" if b else "qs", f"q{벌 * UB + b}", ind2, N)
            return o + [f"{ind2}qe = qe + {UB * 걸음}.", f"{ind2}qs = qs + {UB * N}."]

        def 계산(벌, 앞, ind2):
            """벌의 칸 UB 개(블록 kb + 앞 …)를 풀어 곱해더한다 — x 는 판[xb + 8·(kb + 앞 + b) + i]."""
            o = []
            for b in range(UB):
                for i in range(8):
                    o += [f"{ind2}wv = {칸값식(형식, f'q{벌 * UB + b}', i)}.",
                          f"{ind2}a = 곱해더하기(판[xb + kb * 8 + {8 * (앞 + b) + i}], wv, a)."]
            return o
        J2 = ind + "            "
        out += 읽기(0, ind + "        ")
        out.append(f"{ind}        반복 (정수 kb = 0: kb < {KB}: kb += {2 * UB}) {{")
        out += 읽기(1, J2)
        out += 계산(0, 0, J2)
        out.append(f"{J2}kb + {2 * UB} < {KB}이면 {{")
        out += 읽기(0, J2 + "    ")
        out.append(f"{J2}}}")
        out += 계산(1, UB, J2)
        out += [f"{ind}        }}",
                f"{ind}    }}",
                f"{ind}    가닥 >= 2이면 {{ 판[rb + (가닥 - 2) * 32 + tx] = a. }}",
                f"{ind}    동기화().",
                f"{ind}    가닥 < 2이면 {{ a = a + 판[rb + 가닥 * 32 + tx]. }}",
                f"{ind}    동기화().",
                f"{ind}    가닥 == 1이면 {{ 판[rb + tx] = a. }}",
                f"{ind}    동기화().",
                f"{ind}    (가닥 == 0 그리고 cg < {groups} 그리고 열 < {N})이면 {{",
                f"{ind}        짧은실수 v = (a + 판[rb + tx]) + {치우침식}."]
        out += [f"{ind}        " + x for x in 끝식]
        out += [f"{ind}    }}",
                f"{ind}    동기화().",
                f"{ind}}}"]
        return out

    UB층, UB낱말 = 메가UB.get(층형식), 메가UB.get(낱말형식)
    if not 작은가():
        UB층 = UB낱말 = 5

    def 정수줄곱(값, 척, 형식, 층, K, N, 치우침식, 끝식, ind):
        """정수 블록 계약의 행렬곱(생성 — 행 하나): 판의 x 를 네 자리로 바꾸고(정수판바꾸기) 열 묶음마다 정수열곱 — 따로 도는
        정수줄선형과 같은 코드. 열 묶음 w: 정수줄선형과 같은 규칙(열 3840 이상 32, 1920 이상 16, 아니면 8)."""
        KB, Np = K // 32, (N + 63) // 64 * 64
        w = 정수열묶음(K, N)
        groups = (N + w - 1) // w
        vb, sb = 층크기정수(형식, K, N)
        층식 = lambda a: "" if 층 == "0" else f"{층} * {a} + "
        if 작은가():
            o = 정수판바꾸기(str(XS), str(K), str(KB), DX, DM0, T, ind)
        else:
            o = 정수판바꾸기제자리(lambda e: f"판[{XS} + {e}]", str(K), str(KB), DX, DM0, T, ind, (KB + T // 8 - 1) // (T // 8))
        o += [f"{ind}반복 (정수 cg = 블록: cg < {groups}: cg += {G}) {{"]
        o += 정수열곱(형식, str(K // 4), str(KB), str(N), str(Np), str(w), 값, 척, 층식((vb + sb) // 4), 층식((vb + sb) // 2),
                     DX, DM0, US, "판d" if SD is None else "판", 0 if SD is None else SD, T, 치우침식, 끝식, "cg", ind + "    ")
        o += [f"{ind}}}"]
        return o

    def 가중곱(k, 층, 치우침식, 끝식, ind):
        """층 층 의 가중치 k(주의 · 투영 · 확장 · 축소) 곱 — 짧은실수 판은 원래의 줄곱 그대로(48 개씩 먼저 읽기)."""
        K, N = 모양[k]
        if 층형식 == "짧은실수":
            return 줄곱(f"{k}가중", f"{층} * {K * N}", 치우침식, K, N, 끝식, ind, U=48)
        if 정수:
            return 정수줄곱(f"{k}가중", f"{k}척도", 층형식, 층, K, N, 치우침식, 끝식, ind)
        return 양자줄곱(f"{k}가중", f"{k}척도", 층형식, 층, K, N, 치우침식, 끝식, ind, UB층)

    def 가중미리(k, 층, ind):
        """층 층 의 가중치 k 를 L2 로 — 짧은실수 판은 원래의 식 그대로. 7단계(XL): 미리 올리지 않는다 — 행렬 하나가 L2(48 MB)를
        거의 채워(짧은실수 c_fc 41 MB) 올린 것이 쓰기 전에 밀려나 DRAM 대역만 쓴다(재서 정함: 짧은실수 17.0 → 14.1 ms/토큰, Q4_0 같음)."""
        if not 작은가():
            return []
        K, N = 모양[k]
        if 층형식 == "짧은실수":
            return 미리(f"{k}가중", "0" if 층 == "0" else f"{층} * {K * N}", K * N, ind)
        return 미리(f"{k}넓", "0" if 층 == "0" else f"{층} * {층넓(k)}", 층넓(k), ind)

    def 낱말미리(바탕, ind):
        """로짓 단계의 낱말표 앞부분을 L2 로 — 4 바이트 단위 768 · 4096 개씩(짧은실수 판은 원래의 식 그대로). XL 은 하지 않는다."""
        if not 작은가():
            return []
        return 미리("전치낱말표" if 낱말형식 == "짧은실수" else "낱말넓", 바탕, 너비 * 4096, ind)

    def 임베딩줄(토큰, 위치, c, ind):
        """숨칸[c] = 낱말표의 (토큰, c) + 위치표의 (위치, c) — 짧은실수 판은 원래의 줄 그대로, 양자 판은 값 하나를 정확히 풀어."""
        if 낱말형식 == "짧은실수":
            return [f"{ind}숨칸[{c}] = 낱말표[{토큰} * {너비} + {c}] + 위치표[{위치} * {너비} + {c}]."]
        return ([f"{ind}{{"] + 낱말풀기(낱말형식, 토큰, c, "낱값", ind + "    ") +
                [f"{ind}    숨칸[{c}] = 낱값 + 위치표[{위치} * {너비} + {c}].", f"{ind}}}"])

    def 겔루(목적):
        return ["짧은실수 u = 0.7978845608 * (v + 0.044715 * v * v * v).",
                "짧은실수 th = 1.0 - 2.0 / (근사지수(2.0 * u) + 1.0).",
                f"{목적} = 0.5 * v * (1.0 + th)."]

    # ── 생성 고리 ──
    # 첫 걸음의 임베딩(토큰칸[0] 은 프롬프트 처리가 고른 것) — 뒤 걸음의 것은 다음 토큰을 고른 블록 0 이 그 자리에서 만든다
    L += ["    토큰 = 토큰칸[0].", "    위치 = 시작위치."]
    if 너비 % T:                                          # 7단계: 너비가 T 의 배수가 아니면 마지막 블록은 너비까지만
        L += [f"    블록 < {(너비 + T - 1) // T}이면 {{", f"        정수 ec = 블록 * {T} + tid.", f"        ec < {너비}이면 {{"] + \
             임베딩줄("토큰", "위치", "ec", "            ") + ["        }", "    }"]
    elif 낱말형식 == "짧은실수":
        L.append(f"    블록 < {너비 // T}이면 {{ 숨칸[블록 * {T} + tid] = 낱말표[토큰 * {너비} + 블록 * {T} + tid] + 위치표[위치 * {너비} + 블록 * {T} + tid]. }}")
    else:
        L += [f"    블록 < {너비 // T}이면 {{", f"        정수 ec = 블록 * {T} + tid."] + 임베딩줄("토큰", "위치", "ec", "        ") + ["    }"]
    L += 가중미리("주의", "0", "    ")
    L += 장벽("    ")
    L.append("    반복 (정수 s = 1: s < 생성수: s += 1) {")
    I = "        "
    L += [f"{I}위치 = 시작위치 + s - 1."]
    L.append(f"{I}반복 (정수 l = 0: l < {층수}: l += 1) {{")
    J = I + "    "
    # P1: 층정규화1 + c_attn + KV
    L += 층정규화("첫감마", "첫베타", f"l * {너비}", J)
    L += 가중곱("주의", "l", f"주의치우침[l * {3 * 너비} + 열]",
               ["질의칸[열] = v."] if KV == "정수" else
               [f"열 < {너비}이면 {{ 질의칸[열] = v. }}",
                f"아니면 열 < {2 * 너비}이면 {{ 키칸[{키자리('l * 캐시크기', f'열 - {너비}', '위치')}] = {좁힘('v')}. }}",
                f"아니면 {{ 값칸[l * 캐시크기 + ((열 - {2 * 너비}) / 64) * 최대길이 * 64 + 위치 * 64 + (열 - {2 * 너비}) % 64] = {좁힘('v')}. }}"], J)
    L += 가중미리("투영", "l", J)
    L += 가중미리("확장", "l", J)
    # c_attn 단계에 일이 없는 블록(열 묶음 72 개 뒤)이 지난 키·값(위치 0 … 위치 − 1)을 L2 로 — 문맥이 1024 를 넘으면 하지 않는다
    # (그때는 어텐션 단계가 KV 를 메모리 대역폭으로 읽으니, 앞당겨 읽어도 같은 대역폭을 나눌 뿐이다 — 재서 정함) — 키는 전치라
    # 행(머리·d) 768 개마다 위치 64 개(256 바이트)씩, 값은 머리마다 위치 하나(256 바이트)씩
    # 반실수 판은 같은 자리를 짧은실수 참조로 보고(밝힌 변환 — 값을 읽지 않고 L2 에 올리기만 한다) 색인을 반으로
    키원, 값원, 반 = ("키칸", "값칸", "") if KV == "짧은실수" else ("키넓", "값넓", " / 2")
    열묶음 = 3 * 너비 // 32
    L += [f"{J}블록 >= {열묶음}이면 {{",
          f"{J}    정수 끝t = 위치.",
          f"{J}    끝t > 1024이면 {{ 끝t = 0. }}",
          f"{J}    정수 미0 = (블록 - {열묶음}) * {T} + tid."] if 열묶음 < G and KV != "정수" else []
    if KV not in ("짧은실수", "정수") and 열묶음 < G:
        L += [f"{J}    짧은실수 참조 키넓 = 키칸 으로 짧은실수 참조.",
              f"{J}    짧은실수 참조 값넓 = 값칸 으로 짧은실수 참조."]
    키식 = f"({키자리('l * 캐시크기', '미0', 'pt')}){반}" if 반 else "l * 캐시크기 + 미0 * 최대길이 + pt"
    값식 = f"(l * 캐시크기 + (h * 최대길이 + tr) * 64){반}" if 반 else "l * 캐시크기 + (h * 최대길이 + tr) * 64"
    L += [f"{J}    미0 < {너비}이면 {{",
          f"{J}        반복 (정수 pt = 0: pt < 끝t: pt += 64) {{ 넓게미리올리기(판 에, {DM} + tid * 4 를, {키원} 에서, {키식} 로). }}",
          f"{J}    }}",
          f"{J}    반복 (정수 h는 0부터 {머리수} 전까지) {{",
          f"{J}        반복 (정수 tr = 미0: tr < 끝t: tr += {(G - 열묶음) * T}) {{ 넓게미리올리기(판 에, {DM} + tid * 4 를, {값원} 에서, {값식} 로). }}",
          f"{J}    }}",
          f"{J}    비동기묶기().",
          f"{J}}}"] if 열묶음 < G and KV != "정수" else []
    L += 장벽(J)
    if KV == "정수":                                       # 9단계 — 정수 KV 계약의 어텐션(정수메가어텐션)
        L += 정수메가어텐션(J, G // 머리수, AT, G)
    else:
        # P2: 어텐션 — 머리 h 는 블록 10h … 10h + 9 가, 블록의 묶음 g (64 스레드)가 조각 (블록 % 10)·4 + g + 40k 를. 머리마다 마지막에
        # 도착한 블록이 조각들을 접는다(도착은 주의셈[머리] 에 센다 — 걸음·층마다 10 씩 는다).
        G12 = G // 머리수
        L.append(f"{J}{{" if G12 * 머리수 == G else f"{J}블록 < {G12 * 머리수}이면 {{")   # 머리에 블록 G12 개씩 — 남는 블록은 쉰다
        K = J + "    "
        L += [f"{K}정수 머리 = 블록 / {G12}.",
              f"{K}정수 b10 = 블록 % {G12}.",
              f"{K}정수 g = tid / 64.",
              f"{K}정수 j = tid % 64.",
              f"{K}정수 캐시 = l * 캐시크기 + 머리 * 64 * 최대길이.",
              f"{K}정수 조각끝 = 위치 / 64.",
              f"{K}tid < 64이면 {{ 판[{AT} + tid] = 질의칸[머리 * 64 + tid]. }}",
              f"{K}동기화().",
              # 조각이 넷 이하(위치 256 까지)면 머리의 첫 블록이 조각을 모두 맡아 판 안에서 바로 접는다(원자 연산·전역 왕복 없이 — 값은 같다)
              f"{K}조각끝 < 4이면 {{",
              f"{K}    b10 == 0이면 {{",
              f"{K}        정수 조각 = g."]
        L += 조각계산(K + "        ", AT, None, "키칸", "값칸", "캐시", "위치", "조각", f"{AT + 400} + 조각 * 68", "판")
        L += [f"{K}        tid < 64이면 {{",
              f"{K}            짧은실수 M = 판[{AT + 400}].",
              f"{K}            짧은실수 L = 판[{AT + 401}].",
              f"{K}            짧은실수 O = 판[{AT + 404} + tid].",
              f"{K}            반복 (정수 c = 1: c <= 조각끝: c += 1) {{",
              f"{K}                정수 cb = {AT + 400} + c * 68.",
              f"{K}                짧은실수 mc = 판[cb].",
              f"{K}                짧은실수 M2 = 큰쪽(M, mc).",
              f"{K}                짧은실수 옛비 = 근사지수(M - M2).",
              f"{K}                짧은실수 새비 = 근사지수(mc - M2).",
              f"{K}                L = 곱해더하기(판[cb + 1], 새비, L * 옛비).",
              f"{K}                O = 곱해더하기(판[cb + 4 + tid], 새비, O * 옛비).",
              f"{K}                M = M2.",
              f"{K}            }}",
              f"{K}            주의출력[머리 * 64 + tid] = O / L.",
              f"{K}        }}",
              f"{K}    }}",
              f"{K}}}",
              f"{K}아니면 {{"]
        if KV == "짧은실수":
            L += [f"{K}    반복 (정수 조각0 = b10 * 4: 조각0 <= 조각끝: 조각0 += {4 * G12}) {{",
                  f"{K}        정수 조각 = 조각0 + g."]
            L += 조각계산(K + "        ", AT, None, "키칸", "값칸", "캐시", "위치", "조각", "(머리 * (최대길이 / 64) + 조각) * 68", "조각칸")
            L += [f"{K}    }}"]
        else:
            # 반실수 판: 워프 하나가 조각 하나(조각계산워프). 조각 σ 는 블록 σ mod 10 의 워프 (σ mod 80) / 10 이 — 블록에 엇갈려 나눠,
            # 조각 수가 80 의 배수가 아닐 때 남는 바퀴(꼬리)가 머리의 블록 열 개(모든 SM)에 퍼진다(블록 둘에 몰리면 SM 몇 개만 읽었다)
            L += [f"{K}    정수 rl = tid % 32.",
                  f"{K}    정수 rw = tid / 32.",
                  f"{K}    반복 (정수 조각0 = 0: 조각0 <= 조각끝: 조각0 += {8 * G12}) {{",
                  f"{K}        정수 조각 = 조각0 + b10 + {G12} * rw."]
            L += 조각계산워프(K + "        ", AT, "키칸", "값칸", "캐시", "위치", "조각", "(머리 * (최대길이 / 64) + 조각) * 68", "조각칸")
            L += [f"{K}    }}",
                  f"{K}    동기화()."]                    # 워프 여덟이 모두 조각칸에 쓴 뒤에 도착을 센다
        L += [f"{K}    tid == 0이면 {{",
              f"{K}        울타리().",
              f"{K}        번판[100] = 원자더하기(주의셈 에, 머리 를, 1 로).",
              f"{K}        울타리().",
              f"{K}    }}",
              f"{K}    동기화().",
              f"{K}    (번판[100] + 1) % {G12} == 0이면 {{",
              f"{K}        정수 접바탕 = 머리 * (최대길이 / 64) * 68."]
        L += 접기(K + "        ", "조각칸", "접바탕", "조각끝", "주의출력[머리 * 64 + tid]", AT)
        L += [f"{K}    }}",
              f"{K}}}",
              f"{J}}}"]
    L += 가중미리("확장", "l", J)
    L += 가중미리("축소", "l", J)
    L += 장벽(J)
    # P3: c_proj + 잔차
    L += 옮겨두기("주의출력", 너비, J)
    L += 가중곱("투영", "l", f"투영치우침[l * {너비} + 열]", ["숨칸[열] = 숨칸[열] + v."], J)
    L += 가중미리("축소", "l", J)
    L += [f"{J}l < {층수 - 1}이면 {{"]
    L += 가중미리("주의", "(l + 1)", J + "    ")
    L += [f"{J}}}"]
    L += 장벽(J)
    # P4: 층정규화2 + c_fc + GELU
    L += 층정규화("둘감마", "둘베타", f"l * {너비}", J)
    L += 가중곱("확장", "l", f"확장치우침[l * {확장폭} + 열]", 겔루("확장출력[열]"), J)
    L += [f"{J}l < {층수 - 1}이면 {{"]
    L += 가중미리("주의", "(l + 1)", J + "    ")
    L += 가중미리("투영", "(l + 1)", J + "    ")
    L += [f"{J}}}"]
    L += [f"{J}아니면 {{"]
    L += 낱말미리("0", J + "    ")
    L += [f"{J}}}"]
    L += 장벽(J)
    # P5: mlp c_proj + 잔차
    L += 옮겨두기("확장출력", 확장폭, J)
    L += 가중곱("축소", "l", f"축소치우침[l * {너비} + 열]", ["숨칸[열] = 숨칸[열] + v."], J)
    L += [f"{J}l < {층수 - 1}이면 {{"]
    L += 가중미리("투영", "(l + 1)", J + "    ")
    L += 가중미리("확장", "(l + 1)", J + "    ")
    L += [f"{J}}}"]
    L += [f"{J}아니면 {{"]
    L += 낱말미리(f"{너비} * 4096", J + "    ")
    L += [f"{J}}}"]
    L += 장벽(J)
    L.append(f"{I}}}")
    # 마지막 층정규화 + 로짓 + 다음 토큰
    L += 층정규화("끝감마", "끝베타", "0", I)
    L += [f"{I}짧은실수 최고 = -3.0e38.", f"{I}정수 최고번호 = 0."]
    로짓끝 = [f"기록 == 1이면 {{ 로짓칸[(s - 1) * {낱말수} + 열] = v. }}", "v > 최고이면 { 최고 = v. 최고번호 = 열. }"]
    if 낱말형식 == "짧은실수":
        L += 줄곱("전치낱말표", "0", "0.0", 너비, 낱말수, 로짓끝, I)
    elif 정수:
        L += 정수줄곱("낱말표", "낱말척도", 낱말형식, "0", 너비, 낱말수, "0.0", 로짓끝, I)
    else:
        L += 양자줄곱("낱말표", "낱말척도", 낱말형식, "0", 너비, 낱말수, "0.0", 로짓끝, I, UB낱말)
    L += [f"{I}tid % 128 < 32이면 {{ 판[{MX} + 반 * 32 + tx] = 최고. 번판[반 * 32 + tx] = 최고번호. }}",
          f"{I}동기화().",
          f"{I}tid == 0이면 {{",
          f"{I}    짧은실수 큰 = 판[{MX}].",
          f"{I}    정수 큰번호 = 번판[0].",
          f"{I}    반복 (정수 i = 1: i < 64: i += 1) {{",
          f"{I}        (판[{MX} + i] > 큰 또는 (판[{MX} + i] == 큰 그리고 번판[i] < 큰번호))이면 {{ 큰 = 판[{MX} + i]. 큰번호 = 번판[i]. }}",
          f"{I}    }}",
          f"{I}    부분값[블록] = 큰.",
          f"{I}    부분번호[블록] = 큰번호.",
          f"{I}}}"]
    L += 장벽(I)
    L += [f"{I}(블록 == 0 그리고 tid < 32)이면 {{",
          f"{I}    짧은실수 큰2 = 부분값[tid].",
          f"{I}    정수 큰번호2 = 부분번호[tid].",
          f"{I}    반복 (정수 i = tid + 32: i < {G}: i += 32) {{",
          f"{I}        (부분값[i] > 큰2 또는 (부분값[i] == 큰2 그리고 부분번호[i] < 큰번호2))이면 {{ 큰2 = 부분값[i]. 큰번호2 = 부분번호[i]. }}",
          f"{I}    }}"]
    for sft in (16, 8, 4, 2, 1):
        L += [f"{I}    짧은실수 남값{sft} = 아래에서받기(큰2, {sft}).",
              f"{I}    정수 남번호{sft} = 정수아래에서받기(큰번호2, {sft}).",
              f"{I}    (tid + {sft} < 32 그리고 (남값{sft} > 큰2 또는 (남값{sft} == 큰2 그리고 남번호{sft} < 큰번호2)))이면 {{ 큰2 = 남값{sft}. 큰번호2 = 남번호{sft}. }}"]
    L += [f"{I}    tid == 0이면 {{ 토큰칸[s] = 큰번호2. 판[{MX}] = 큰번호2 으로 짧은실수. }}",
          f"{I}}}",
          f"{I}(블록 == 0 그리고 s + 1 < 생성수)이면 {{",
          f"{I}    동기화().",
          f"{I}    정수 다음토큰 = 판[{MX}] 으로 정수.",
          f"{I}    정수 다음위치 = 위치 + 1."]
    for i in range((너비 + T - 1) // T):
        if T * (i + 1) <= 너비:
            L += 임베딩줄("다음토큰", "다음위치", f"tid + {T * i}", I + "    ")
        else:
            L += [f"{I}    tid + {T * i} < {너비}이면 {{"] + 임베딩줄("다음토큰", "다음위치", f"tid + {T * i}", I + "        ") + [f"{I}    }}"]
    L += [f"{I}}}"]
    L += 가중미리("주의", "0", I)
    L += 장벽(I)
    L.append("    }")
    L.append("    비동기기다리기(0).")
    L.append("}")
    return L


def 몸(줄들, 바꿈, 앞줄=()):
    """커널 하나의 글 소스(머리 주석·실행한도·서명 줄 뒤부터 끝 '}' 앞까지)를 메가커널 안의 블록으로 — 배열·좌표의 이름을 바꿔 낀다.
    산술은 같은 생성기에서 나오므로 따로 도는 커널과 비트가 같다. 바꿈: [(정규식, 바꿀 글)] — 앞에서부터 차례로."""
    import re
    본문 = 줄들[3:-1]
    out = list(앞줄)
    for 줄 in 본문:
        for 꼴, 새 in 바꿈:
            줄 = re.sub(꼴, 새, 줄)
        out.append(줄)
    return out


def 배열바꿈(이름, 새이름, 바탕=None):
    """이름[ … ] 과 '이름 에서, ' 를 새이름(+ 바탕)으로 — 앞뒤가 이름의 일부가 아닐 때만."""
    앞 = r"(?<![\w])"
    if 바탕 is None:
        return [(앞 + 이름 + r"\[", 새이름 + "["), (앞 + 이름 + " 에서, ", 새이름 + " 에서, ")]
    return [(앞 + 이름 + r"\[", 새이름 + "[" + 바탕 + " + "), (앞 + 이름 + " 에서, ", 새이름 + " 에서, " + 바탕 + " + ")]


def 칸수(k):
    """층정규화의 가상 스레드 v = l + 32k (레인 l) 가 맡는 칸 v + 256j 의 수 — 너비는 32 의 배수라 레인과 상관없다(small 은 셋)."""
    return len([j for j in range(64) if 32 * k + 256 * j < 너비])


def 차례합(항들):
    """0 에서부터 차례로 더한 식 — ((영 + a) + b) + c."""
    식 = "영"
    for i, t in enumerate(항들):
        식 = f"({식} + {t})" if i < len(항들) - 1 else f"{식} + {t}"
    return 식


def 줄층정규화몸(ind, 입력, 감마, 감마바탕, 출력, 행식, 출력바탕="바탕"):
    """워프 하나가 한 행 — gpt2.gl 의 층정규화(워프 판)와 같은 산술(같은 나무, eps 1e-5). 출력바탕: 출력의 행 바탕(식 — 기본은
    입력과 같은 바탕). 가상 스레드 v = l + 32k 는 칸 v + 256j (< 너비)를 0 에서부터 차례로 더한다."""
    out = [f"{ind}{{",
           f"{ind}    정수 바탕 = ({행식}) * {너비}.",
           f"{ind}    정수 l = tid % 32.",
           f"{ind}    짧은실수 영 = 0 으로 짧은실수."]
    I = ind + "    "
    for k in range(8):
        out += [f"{I}짧은실수 x{k}_{j} = {입력}[바탕 + l + {32 * k + 256 * j}]." for j in range(칸수(k))]
    out += [f"{I}짧은실수 p{k} = {차례합([f'x{k}_{j}' for j in range(칸수(k))])}." for k in range(8)]
    out.append(f"{I}짧은실수 합 = ((p0 + p4) + (p2 + p6)) + ((p1 + p5) + (p3 + p7)).")
    out += [f"{I}합 = 합 + 아래에서받기(합, {s})." for s in (16, 8, 4, 2, 1)]
    out += [f"{I}합 = 레인에서받기(합, 0).", f"{I}짧은실수 평균 = 합 / {너비}.0."]
    for k in range(8):
        out += [f"{I}짧은실수 d{k}_{j} = x{k}_{j} - 평균." for j in range(칸수(k))]
        out.append(f"{I}짧은실수 r{k} = {차례합([f'd{k}_{j} * d{k}_{j}' for j in range(칸수(k))])}.")
    out.append(f"{I}짧은실수 제곱합 = ((r0 + r4) + (r2 + r6)) + ((r1 + r5) + (r3 + r7)).")
    out += [f"{I}제곱합 = 제곱합 + 아래에서받기(제곱합, {s})." for s in (16, 8, 4, 2, 1)]
    out += [f"{I}제곱합 = 레인에서받기(제곱합, 0).",
            f"{I}짧은실수 역표준 = 1.0 / 제곱근(제곱합 / {너비}.0 + 0.00001)."]
    for k in range(8):
        for j in range(칸수(k)):
            c = 32 * k + 256 * j
            out.append(f"{I}{출력}[{출력바탕} + l + {c}] = (x{k}_{j} - 평균) * 역표준 * {감마}[{감마바탕} + l + {c}] + "
                       f"{감마.replace('감마', '베타')}[{감마바탕} + l + {c}].")
    out.append(f"{ind}}}")
    return out


def 프롬메가(G=120, T=256):
    """프롬프트 처리(문장 하나)를 커널 하나로 — 협력 실행 한 번. 블록 G 개(T 스레드)가 "일"을 차례로 가져가고(원자 더하기), 일마다
    앞선 일들 가운데 기대는 것의 끝난 수(행 묶음 64 행마다)를 기다린 뒤 한다(데이터 흐름 — 격자 장벽이 없어 단계의 꼬리가 다음 단계와
    겹친다). 일의 차례(R = 행 묶음 수): 임베딩 8R(8 행씩), 그리고 층마다 [층정규화1 8R] [c_attn] [어텐션 12R] [c_proj] [층정규화2 8R]
    [c_fc] [mlp c_proj]. 행렬곱 단계는 64 × 64 타일 수(R × 열/64)가 240 보다 적으면 32 × 32 타일(작은타일선형의 몸, 행 묶음마다
    2 × 열/32 개)로 — 짧은 프롬프트에서 한 타일이 길을 막지 않게. 기다림: 층정규화1(r) ← 임베딩(r) 8 개 또는 앞 층 mlp c_proj(r)
    전부, 타일 ← 그 행 묶음의 층정규화 8 개, 어텐션(머리, r) ← c_attn 의 행 묶음 0 … r 전부, c_proj(r) ← 어텐션(r) 12 개,
    층정규화2(r) ← c_proj(r) 전부, mlp c_proj(r) ← c_fc(r) 전부. 일은 늘 앞선 일만 기다리고 블록이 모두 올라 있으니 막히지 않는다.
    일의 몸은 따로 도는 커널(타일선형넷 레지·작은타일선형, 흐름어텐션, 층정규화 워프 판, 임베딩)의 소스를 이름만 바꿔 낀 것이라 비트가
    같다. 마지막: 모든 블록이 마지막 행 묶음의 mlp c_proj 를 기다린 뒤 마지막 행의 층정규화 + 로짓(줄선형1 과 같은 산술)을 나눠 하고,
    격자 장벽 뒤 블록 0 이 다음 토큰을 고른다.
    끝셈 [층 12][단계 8][행 묶음 묶음최대] (정수 — 단계 0 임베딩 … 7 mlp c_proj; 임베딩은 층 0 자리), 일셈·장벽 — 호스트가 띄우기 전에 0 으로."""
    XS, RD, MX = 0, 3072, 3200          # 마지막 단계의 판: 행 [768] 0, 가닥 합치기 [2][64] 3072, 최댓값·번호 [2][64] 3200
    단계열 = {2: 2304, 4: 768, 6: 3072, 7: 768}
    L = ["(* 프롬프트 메가커널 — 커널생성.py 의 설명. 협력 실행으로만 띄운다(블록이 모두 함께 올라 있어야 기다림이 끝난다) *)",
         f"(* 실행한도 프롬메가 {T} {G // 60} *)",
         "[정수 참조 토큰칸에 짧은실수 참조 낱말표와 짧은실수 참조 위치표와 짧은실수 참조 전치낱말표와 "
         "짧은실수 참조 첫감마와 짧은실수 참조 첫베타와 짧은실수 참조 주의가중과 짧은실수 참조 주의치우침과 "
         "짧은실수 참조 투영가중과 짧은실수 참조 투영치우침과 짧은실수 참조 둘감마와 짧은실수 참조 둘베타와 "
         "짧은실수 참조 확장가중과 짧은실수 참조 확장치우침과 짧은실수 참조 축소가중과 짧은실수 참조 축소치우침과 "
         "짧은실수 참조 끝감마와 짧은실수 참조 끝베타와 짧은실수 참조 키칸과 짧은실수 참조 값칸과 "
         "짧은실수 참조 숨칸과 짧은실수 참조 정규칸과 짧은실수 참조 질의칸과 짧은실수 참조 주의출력과 짧은실수 참조 확장출력과 "
         "짧은실수 참조 로짓칸과 짧은실수 참조 부분값과 정수 참조 부분번호와 정수 참조 장벽과 정수 참조 일셈과 정수 참조 끝셈과 "
         "정수 참조 블록일과 정수 참조 생성칸과 정수 참조 시각칸과 정수 행수로 정수 최대길이로 정수 캐시문장수로 정수 묶음최대로 "
         "정수 시각기록으로 프롬메가]는 {",
         "    정수 tid = 블록안가로().",
         "    정수 블록 = 블록가로().",
         "    짧은실수 참조 판 = 공유판48().",
         "    짧은실수 영 = 0 으로 짧은실수.",
         "    정수 캐시크기 = 캐시문장수 * 최대길이 * 768.",
         "    정수 R = (행수 + 63) / 64."]
    for 단, N in 단계열.items():
        L += [f"    정수 작{단} = 0.",
              f"    R * {N // 64} < 240이면 {{ 작{단} = 1. }}",
              f"    정수 T{단} = {N // 64}.",
              f"    작{단} == 1이면 {{ T{단} = {2 * (N // 32)}. }}"]
    L += ["    정수 경1 = 8 * R.",
          "    정수 경2 = 경1 + T2 * R.",
          "    정수 경3 = 경2 + 12 * R.",
          "    정수 경4 = 경3 + T4 * R.",
          "    정수 경5 = 경4 + 8 * R.",
          "    정수 경6 = 경5 + T6 * R.",
          "    정수 층일 = 경6 + T7 * R.",
          "    정수 총일 = 8 * R + 12 * 층일."]

    def 기다림(ind, 자리식, 목표):
        return [f"{ind}(획득읽기(끝셈 에서, {자리식} 로) < {목표}) 동안 {{ }}"]

    # ── 일 고리 ──
    L += ["    반복 (정수 영원 = 0: 영원 < 1: 영원 = 0) {",
          "        tid == 0이면 { 블록일[블록] = 원자더하기(일셈 에, 0 를, 1 로). }",
          "        동기화().",
          "        정수 일 = 블록일[블록].",
          "        동기화().",
          "        일 >= 총일이면 { 탈출. }",
          "        (시각기록 > 0 그리고 tid == 0)이면 { 시각칸[일 * 4] = 시각(). 시각칸[일 * 4 + 3] = 블록. }",
          "        정수 단계 = 0.",
          "        정수 층 = 0.",
          "        정수 r = 일 / 8.",
          "        정수 서브 = 일 % 8.",
          "        일 >= 8 * R이면 {",
          "            정수 j = 일 - 8 * R.",
          "            층 = j / 층일.",
          "            정수 k = j % 층일.",
          "            k < 경1이면 { 단계 = 1. r = k / 8. 서브 = k % 8. }",
          "            아니면 k < 경2이면 { 단계 = 2. r = (k - 경1) / T2. 서브 = (k - 경1) % T2. }",
          "            아니면 k < 경3이면 { 단계 = 3. r = (k - 경2) / 12. 서브 = (k - 경2) % 12. }",
          "            아니면 k < 경4이면 { 단계 = 4. r = (k - 경3) / T4. 서브 = (k - 경3) % T4. }",
          "            아니면 k < 경5이면 { 단계 = 5. r = (k - 경4) / 8. 서브 = (k - 경4) % 8. }",
          "            아니면 k < 경6이면 { 단계 = 6. r = (k - 경5) / T6. 서브 = (k - 경5) % T6. }",
          "            아니면 { 단계 = 7. r = (k - 경6) / T7. 서브 = (k - 경6) % T7. }",
          "        }",
          "        정수 셈바탕 = 층 * 8 * 묶음최대.",
          "        tid == 0이면 {",
          "            단계 == 1이면 {",
          "                층 == 0이면 {"] + 기다림("                    ", "r", "8") + [
          "                }",
          "                아니면 {"] + 기다림("                    ", "셈바탕 - 묶음최대 + r", "T7") + [
          "                }",
          "            }",
          "            단계 == 2이면 {"] + 기다림("                ", "셈바탕 + 묶음최대 + r", "8") + [
          "            }",
          "            단계 == 3이면 {",
          "                반복 (정수 rr = 0: rr <= r: rr += 1) {"] + 기다림("                    ", "셈바탕 + 2 * 묶음최대 + rr", "T2") + [
          "                }",
          "            }",
          "            단계 == 4이면 {"] + 기다림("                ", "셈바탕 + 3 * 묶음최대 + r", "12") + [
          "            }",
          "            단계 == 5이면 {"] + 기다림("                ", "셈바탕 + 4 * 묶음최대 + r", "T4") + [
          "            }",
          "            단계 == 6이면 {"] + 기다림("                ", "셈바탕 + 5 * 묶음최대 + r", "8") + [
          "            }",
          "            단계 == 7이면 {"] + 기다림("                ", "셈바탕 + 6 * 묶음최대 + r", "T6") + [
          "            }",
          "            울타리().",
          "            시각기록 > 0이면 { 시각칸[일 * 4 + 1] = 시각(). }",
          "        }",
          "        동기화()."]
    I = "        "
    # 단계 0: 임베딩 — 8 행, 스레드마다 열 셋 (임베딩 커널과 같은 덧셈 하나)
    L += [f"{I}단계 == 0이면 {{"]
    for k in range(8):
        L += [f"{I}    (r * 64 + 서브 * 8 + {k} < 행수)이면 {{",
              f"{I}        정수 행 = r * 64 + 서브 * 8 + {k}.",
              f"{I}        정수 토 = 토큰칸[행]."]
        L += [f"{I}        숨칸[행 * 768 + tid + {T * i}] = 낱말표[토 * 768 + tid + {T * i}] + 위치표[행 * 768 + tid + {T * i}]."
              for i in range(768 // T)]
        L += [f"{I}    }}"]
    L += [f"{I}}}"]
    # 단계 1·5: 층정규화 — 8 행, 워프 하나가 한 행
    for 단, 감 in ((1, "첫감마"), (5, "둘감마")):
        L += [f"{I}단계 == {단}이면 {{",
              f"{I}    (r * 64 + 서브 * 8 + tid / 32 < 행수)이면 {{"]
        L += 줄층정규화몸(I + "        ", "숨칸", 감, "층 * 768", "정규칸", "r * 64 + 서브 * 8 + tid / 32")
        L += [f"{I}    }}", f"{I}}}"]
    # 단계 2·4·6·7: 행렬곱 타일 — 64 × 64 (타일선형넷 레지) 또는 32 × 32 (작은타일선형)
    for 단, epi, A, W, Wb, Bv, Bb, K, N, O in (
            (2, "_KV", "정규칸", "주의가중", "층 * 1769472", "주의치우침", "층 * 2304", 768, 2304, "질의칸"),
            (4, "_잔차", "주의출력", "투영가중", "층 * 589824", "투영치우침", "층 * 768", 768, 768, "숨칸"),
            (6, "_겔루", "정규칸", "확장가중", "층 * 2359296", "확장치우침", "층 * 3072", 768, 3072, "확장출력"),
            (7, "_잔차", "확장출력", "축소가중", "층 * 2359296", "축소치우침", "층 * 768", 3072, 768, "숨칸")):
        공통 = 배열바꿈("입력", A) + 배열바꿈("가중치", W, Wb) + 배열바꿈("치우침", Bv, Bb)
        공통 += 배열바꿈("잔차", O) + 배열바꿈("출력", O)
        공통 += 배열바꿈("키칸", "키칸", "층 * 캐시크기") + 배열바꿈("값칸", "값칸", "층 * 캐시크기")
        큰 = [(r"정수 행0 = 블록가로\(\) \* 64\.", "정수 행0 = r * 64."),
             (r"정수 열0 = 블록세로\(\) \* 64\.", "정수 열0 = 서브 * 64.")] + 공통
        작 = [(r"정수 행0 = 블록가로\(\) \* 32\.", f"정수 행0 = r * 64 + (서브 / {N // 32}) * 32."),
             (r"정수 열0 = 블록세로\(\) \* 32\.", f"정수 열0 = (서브 % {N // 32}) * 32."),
             (r"공유판24\(\)", "공유판48()")] + 공통
        L += [f"{I}단계 == {단}이면 {{",
              f"{I}    정수 깊이 = {K}.",
              f"{I}    정수 열수 = {N}.",
              f"{I}    정수 묶음안행수 = 행수.",
              f"{I}    정수 위치시작 = 0.",
              f"{I}    작{단} == 0이면 {{"]
        L += [I + "        " + 줄 for 줄 in 몸(타일선형(epi, 넷=True, 레지=True), 큰)]
        L += [f"{I}    }}",
              f"{I}    아니면 {{"]
        L += [I + "        " + 줄 for 줄 in 몸(작은타일선형(epi), 작)]
        L += [f"{I}    }}",
              f"{I}}}"]
    # 단계 3: 어텐션 (머리 서브, 질의 조각 r) — 흐름어텐션의 몸
    바꿈 = [(r"정수 머리 = 블록가로\(\)\.", "정수 머리 = 서브."),
          (r"정수 문장 = 블록세로\(\) / 질조각수\.", "정수 문장 = 0."),
          (r"정수 r0 = \(질조각수 - 1 - 블록세로\(\) % 질조각수\) \* 64\.", "정수 r0 = r * 64.")]
    바꿈 += 배열바꿈("q", "질의칸") + 배열바꿈("키칸", "키칸", "층 * 캐시크기") + 배열바꿈("값칸", "값칸", "층 * 캐시크기")
    바꿈 += 배열바꿈("출력", "주의출력")
    L += [f"{I}단계 == 3이면 {{",
          f"{I}    정수 묶음안행수 = 행수.",
          f"{I}    정수 위치시작 = 0."]
    L += [I + "    " + 줄 for 줄 in 몸(흐름어텐션(), 바꿈)]
    L += [f"{I}}}"]
    # 끝남을 센다
    L += [f"{I}동기화().",
          f"{I}tid == 0이면 {{",
          f"{I}    울타리().",
          f"{I}    정수 끝자리 = 셈바탕 + 단계 * 묶음최대 + r.",
          f"{I}    정수 옛 = 원자더하기(끝셈 에, 끝자리 를, 1 로).",
          f"{I}    시각기록 > 0이면 {{ 시각칸[일 * 4 + 2] = 시각(). }}",
          f"{I}}}",
          "    }"]
    # ── 마지막 행: 층정규화 + 로짓 + 다음 토큰 ──
    L += ["    tid == 0이면 {"] + 기다림("        ", "11 * 8 * 묶음최대 + 7 * 묶음최대 + R - 1", "T7") + [
          "        울타리().",
          "    }",
          "    동기화()."]
    L += ["    {", "        tid < 32이면 {",
          "            정수 바탕 = (행수 - 1) * 768."]
    J = "            "
    for k in range(8):
        L += [f"{J}짧은실수 x{k}_{j} = 숨칸[바탕 + tid + {32 * k + 256 * j}]." for j in range(3)]
        L.append(f"{J}짧은실수 p{k} = ((영 + x{k}_0) + x{k}_1) + x{k}_2.")
    L.append(f"{J}짧은실수 합 = ((p0 + p4) + (p2 + p6)) + ((p1 + p5) + (p3 + p7)).")
    L += [f"{J}합 = 합 + 아래에서받기(합, {s})." for s in (16, 8, 4, 2, 1)]
    L += [f"{J}합 = 레인에서받기(합, 0).", f"{J}짧은실수 평균0 = 합 / 768.0."]
    for k in range(8):
        L += [f"{J}짧은실수 e{k}_{j} = x{k}_{j} - 평균0." for j in range(3)]
        L.append(f"{J}짧은실수 rr{k} = ((영 + e{k}_0 * e{k}_0) + e{k}_1 * e{k}_1) + e{k}_2 * e{k}_2.")
    L.append(f"{J}짧은실수 제곱합 = ((rr0 + rr4) + (rr2 + rr6)) + ((rr1 + rr5) + (rr3 + rr7)).")
    L += [f"{J}제곱합 = 제곱합 + 아래에서받기(제곱합, {s})." for s in (16, 8, 4, 2, 1)]
    L += [f"{J}제곱합 = 레인에서받기(제곱합, 0).",
          f"{J}tid == 0이면 {{ 판[{MX + 128}] = 평균0. 판[{MX + 129}] = 1.0 / 제곱근(제곱합 / 768.0 + 0.00001). }}",
          "        }",
          "        동기화().",
          f"        짧은실수 평균 = 판[{MX + 128}].",
          f"        짧은실수 역표준 = 판[{MX + 129}]."]
    L += [f"        판[{XS} + tid + {T * i}] = (숨칸[(행수 - 1) * 768 + tid + {T * i}] - 평균) * 역표준 * 끝감마[tid + {T * i}] + "
          f"끝베타[tid + {T * i}]." for i in range(768 // T)]
    L += ["        동기화().", "    }"]
    L += ["    정수 가닥 = (tid % 128) / 32.",
          "    정수 tx = tid % 32.",
          "    정수 반 = tid / 128.",
          "    짧은실수 최고 = -3.0e38.",
          "    정수 최고번호 = 0.",
          f"    반복 (정수 cg0 = 블록: cg0 < 1571: cg0 += {2 * G}) {{",
          f"        정수 cg = cg0 + 반 * {G}.",
          "        정수 열 = cg * 32 + tx.",
          "        정수 cc = 열.",
          "        cc >= 50257이면 { cc = 50256. }",
          f"        정수 rb = {RD} + 반 * 64.",
          "        짧은실수 a = 영.",
          "        cg < 1571이면 {"]
    U = 16
    L += [f"            짧은실수 w{u} = 영." for u in range(U)]
    L += ["            정수 k = 가닥.",
          f"            반복 (: k + {4 * (U - 1)} < 768: k += {4 * U}) {{"]
    L += [f"                w{u} = 전치낱말표[(k + {4 * u}) * 50257 + cc]." for u in range(U)]
    L += [f"                a = 곱해더하기(판[{XS} + k + {4 * u}], w{u}, a)." for u in range(U)]
    L += ["            }",
          f"            반복 (: k < 768: k += 4) {{ a = 곱해더하기(판[{XS} + k], 전치낱말표[k * 50257 + cc], a). }}",
          "        }",
          "        가닥 >= 2이면 { 판[rb + (가닥 - 2) * 32 + tx] = a. }",
          "        동기화().",
          "        가닥 < 2이면 { a = a + 판[rb + 가닥 * 32 + tx]. }",
          "        동기화().",
          "        가닥 == 1이면 { 판[rb + tx] = a. }",
          "        동기화().",
          "        (가닥 == 0 그리고 cg < 1571 그리고 열 < 50257)이면 {",
          "            짧은실수 v = (a + 판[rb + tx]) + 0.0.",
          "            로짓칸[열] = v.",
          "            v > 최고이면 { 최고 = v. 최고번호 = 열. }",
          "        }",
          "        동기화().",
          "    }",
          f"    tid % 128 < 32이면 {{ 판[{MX} + 반 * 32 + tx] = 최고. 판[{MX} + 64 + 반 * 32 + tx] = 최고번호 으로 짧은실수. }}",
          "    동기화().",
          "    tid == 0이면 {",
          f"        짧은실수 큰 = 판[{MX}].",
          f"        정수 큰번호 = 판[{MX + 64}] 으로 정수.",
          "        반복 (정수 i = 1: i < 64: i += 1) {",
          f"            정수 번 = 판[{MX + 64} + i] 으로 정수.",
          f"            (판[{MX} + i] > 큰 또는 (판[{MX} + i] == 큰 그리고 번 < 큰번호))이면 {{ 큰 = 판[{MX} + i]. 큰번호 = 번. }}",
          "        }",
          "        부분값[블록] = 큰.",
          "        부분번호[블록] = 큰번호.",
          "        울타리().",
          "        정수 옛2 = 원자더하기(장벽 에, 0 를, 1 로).",
          "    }",
          "    블록 == 0이면 {",
          "        tid == 0이면 {",
          f"            (획득읽기(장벽 에서, 0 로) < {G}) 동안 {{ }}",
          "            울타리().",
          "            짧은실수 큰2 = 부분값[0].",
          "            정수 큰번호2 = 부분번호[0].",
          f"            반복 (정수 i = 1: i < {G}: i += 1) {{",
          "                (부분값[i] > 큰2 또는 (부분값[i] == 큰2 그리고 부분번호[i] < 큰번호2))이면 { 큰2 = 부분값[i]. 큰번호2 = 부분번호[i]. }",
          "            }",
          "            생성칸[0] = 큰번호2.",
          "        }",
          "    }",
          "}"]
    return L


# ── 6단계: 정수 블록 계약 (Q8_0 · Q4_0) ─────────────────────────────────────────────────────────────────────────────
# 출력 (행 r, 열 n), 블록 b = k 32 줄:
#   E = ⌊log₂ max_k |x_k|⌋ (최댓값 0 이면 −98, [−98, 100] 로 자른다), n_k = 가까운정수(x_k · 2^(29 − E)) (|n| ≤ 2³⁰),
#   균형 256진 네 자리 D₀ · D₁ · D₂ ∈ [−128, 127], D₃ ∈ [−64, 64] (n = D₀ + 2⁸D₁ + 2¹⁶D₂ + 2²⁴D₃).
#   S_j = Σ_k D_j,k · q_k,n — 정수로 정확(정수 텐서 코어 · dp4a 어느 것이든 같다).
#   v_j = S_j · 2^(8j + E − 29) (정확 — 실수 1.5 · 2^(8j + E − 6) 의 비트 M_j 에 S_j 를 더하고 M_j 를 빼서), u = ((v₃ + v₂) + v₁) + v₀,
#   y ← 곱해더하기(u, d_b,n, y) 를 b 오름차순(y 는 +0 에서), 출력 = y + 치우침 → 끝손질.
# 가중치 배치(정수 판, 5단계/gguf읽기.py 의 깔기정수): Q8_0 — [블록][열][32 바이트](k 차례, 부호 있는 8 비트), Q4_0 — [블록][열][낱말 4]
# (낱말 j 의 바이트 m: 아래 니블 = q[8j + m] + 8, 위 니블 = q[8j + 4 + m] + 8 — 쓸 때 바이트마다 부호 있는 q 로 바꾼다: t = 니블 ^ 8,
# q = t | ((t & 8) · 30) — 바이트를 넘는 자리올림이 없다). 척도 — [블록][척도폭](반실수, 척도폭 = 열수를 64 로 올림).
# 활성값의 자리: [자리 4][행][깊이] 바이트, 정보: [행][블록][4] — M_0 … M_3 (중간정수 — 실수의 비트).

def 정수머리줄():
    return ["외부 [정수 j를 중간정수 a0를 중간정수 a1를 중간정수 a2를 중간정수 a3를 중간정수 b0를 중간정수 b1를 중간정수 c0를 "
            "중간정수 c1를 중간정수 c2를 중간정수 c3를 정수텐서곱]는 -> 중간정수.",
            "외부 [중간정수 a를 중간정수 b를 중간정수 c를 바이트넷곱더하기]는 -> 중간정수.",
            "외부 [중간정수 a를 중간정수 b를 중간정수 c를 바이트넷곱더하기_나부호없음]는 -> 중간정수.",
            "외부 [짧은실수 x를 실수비트]는 -> 중간정수.", "외부 [중간정수 i를 비트실수]는 -> 짧은실수.",
            "외부 [짧은실수 x를 가까운정수]는 -> 중간정수."] + \
        ([f"외부 [공유판{kb}]는 -> 짧은실수 참조." for kb in ((16, 20, 28, 32, 44) if 자리수 == 2 else (16, 20, 28, 32))] if 작은가() else []) + \
        (["외부 [중간정수 a를 중간정수 b를 중간정수 선택자를 바이트고르기]는 -> 중간정수.", "외부 [공유판33]는 -> 짧은실수 참조.",
          "외부 [정수 j를 중간정수 참조 판을 정수 i를 행렬조각읽기]는 -> 중간정수."] if KV == "정수" else []) + [""]


def 니블부호(w):
    """니블을 바이트마다 하나씩 모은 낱말 w(식 — 바이트 ∈ [0, 15])를 부호 있는 바이트 넷(q = 니블 − 8)으로."""
    return f"((({w}) ^ 134744072) | (((({w}) ^ 134744072) & 134744072) * 30))"


def 넷자리식(x, ind, 접):
    """짧은실수 x(식)와 블록의 E(변수 E) → 자리 d{접}0 … d{접}{자리수−1} (중간정수) 선언 줄들 — 정수 블록 계약의 바꾸기
    (자리수 4: 네 자리, 2: 두 자리 — 맨 위 자리는 남은 몫)."""
    o = [f"{ind}중간정수 n{접} = 가까운정수({x} * s)."]
    앞 = f"n{접}"
    for j in range(자리수 - 1):
        o.append(f"{ind}중간정수 d{접}{j} = (({앞} + 128) & 255) - 128.")
        if j < 자리수 - 2:
            o.append(f"{ind}중간정수 m{접}{j + 1} = ({앞} - d{접}{j}) >> 8.")
            앞 = f"m{접}{j + 1}"
        else:
            o.append(f"{ind}중간정수 d{접}{j + 1} = ({앞} - d{접}{j}) >> 8.")
    return o


def 마법수0():
    """블록의 마법수 M_0 의 식 — v_0 = S_0 · 2^(E − P), P = 8·자리수 − 3: 지수 칸 127 + 23 + E − P = (153 − 8·자리수) + E (넷 121, 둘 137)."""
    return f"((({153 - 8 * 자리수} + E) << 23) + 4194304) 으로 중간정수"


def 지수식(ind):
    """블록의 최댓값 m(짧은실수 변수) → 지수 E (⌊log₂ m⌋, 0 이면 −98, [−98, 100] 로)와 s = 2^(P − E) 의 선언 줄들 (P = 8·자리수 − 3)."""
    return [f"{ind}정수 E = -98.",
            f"{ind}m > 0.0이면 {{",
            f"{ind}    E = ((실수비트(m) >> 23) & 255) - 127.",
            f"{ind}    E < -98이면 {{ E = -98. }}",
            f"{ind}    E > 100이면 {{ E = 100. }}",
            f"{ind}}}",
            f"{ind}짧은실수 s = 비트실수((({124 + 8 * 자리수} - E) << 23) 으로 중간정수)."]


def 블록바꾸기몸(읽기, 쓰기자리, 정보쓰기, ind):
    """레인 여덟이 블록(k 32 줄) 하나 — 레인마다 이어진 네 칸(읽기(i) 는 i = 0 … 3 번째 칸의 식). 블록의 최댓값은 레인 안의 넷과
    셔플 셋(같은 여덟 레인), 그다음 무리의 첫 레인에서 받는다. 네 칸의 자리 j 를 낱말 하나로(낮은 바이트가 먼저) 쓰기자리(j) 에,
    무리의 첫 레인이 정보쓰기(M_0 식) 를 한다. 바깥에 lane(레인 번호) 이 있어야 한다."""
    o = [f"{ind}짧은실수 x{i} = {읽기(i)}." for i in range(4)]
    o += [f"{ind}짧은실수 m = 큰쪽(큰쪽(큰쪽(x0, 0.0 - x0), 큰쪽(x1, 0.0 - x1)), 큰쪽(큰쪽(x2, 0.0 - x2), 큰쪽(x3, 0.0 - x3)))."]
    o += [f"{ind}m = 큰쪽(m, 아래에서받기(m, {sft}))." for sft in (4, 2, 1)]
    o += [f"{ind}m = 레인에서받기(m, lane - lane % 8)."] + 지수식(ind)
    for i in range(4):
        o += 넷자리식(f"x{i}", ind, str(i))
    for j in range(자리수):
        o.append(f"{ind}{쓰기자리(j)} = ((d0{j} & 255) | ((d1{j} & 255) << 8) | ((d2{j} & 255) << 16) | (d3{j} << 24)) 으로 중간정수.")
    o.append(f"{ind}lane % 8 == 0이면 {{ {정보쓰기(마법수0())} }}")
    return o


def 정수로():
    """활성값 x [행][깊이] → 네 자리 [자리 4][행][깊이] (바이트 — 낱말로 쓴다)와 정보 [블록][정보폭] (M_0 — 블록의 마법수,
    M_j = M_0 + 8j · 2²³; 정보폭 = 행수를 64 로 올림). 워프 하나가 블록 넷(레인 여덟이 하나 — 레인마다 이어진 네 칸). 블록의
    낱말 여덟(칸 4w … 4w+3 이 낱말 w)은 [0 4 1 5 2 6 3 7] 차례로 둔다 — 타일 판의 레인이 A 조각의 두 낱말을 한 번에 읽게.
    격자: (블록 수를 32 로 올린 것 / 32, 행수). 블록 번호가 넘치는 레인은 마지막 블록을 읽고 쓰지 않는다(셔플은 모든 레인이 함께)."""
    L = [f"(* 정수 블록 계약의 활성값 바꾸기 — 블록마다 지수, {8 * 자리수 - 2} 비트 고정소수점, 균형 256진 {'네' if 자리수 == 4 else '두'} 자리, 마법수 *)",
         "[짧은실수 참조 입력에서 중간정수 참조 자릿값에 중간정수 참조 정보에 정수 행수로 정수 깊이로 정수로]는 {",
         "    정수 tid = 블록안가로().",
         "    정수 lane = tid % 32.",
         "    정수 r = 블록세로().",
         "    정수 블록수 = 깊이 / 32.",
         "    정수 깊이4 = 깊이 / 4 * 4.",
         "    정수 면 = 깊이 / 4.",
         "    정수 정보폭 = (행수 + 63) / 64 * 64.",
         "    정수 b0 = 블록가로() * 32 + (tid / 32) * 4 + lane / 8.",
         "    정수 b = b0.",
         "    b >= 블록수이면 { b = 블록수 - 1. }",
         "    정수 xa = r * 깊이4 + b * 32 + (lane % 8) * 4."]
    L += 블록바꾸기몸(lambda i: f"입력[xa + {i}]", lambda j: f"정수 자{j} = 0. 자{j}",
                    lambda v: f"b0 < 블록수이면 {{ 정보[b * 정보폭 + r] = {v}. }}", "    ")
    L += ["    b0 < 블록수이면 {"]
    L += [f"        자릿값[({j} * 행수 + r) * 면 + b * 8 + (lane % 4) * 2 + (lane % 8) / 4] = 자{j}." for j in range(자리수)]
    L += ["    }", "}"]
    return L


def 층정규화정수():
    """층정규화(워프 판 — gpt2.gl 과 같은 산술) 뒤에 정수로와 같은 바꾸기 — 워프 하나가 한 행: 정규화한 768 칸을 판(워프마다
    768 칸)에 두고, 레인 여덟이 블록 하나씩(바퀴 여섯에 블록 24 개). 자릿값 · 정보만 쓴다(짧은실수 x 는 쓰지 않는다) — 값은
    층정규화 → 정수로 와 비트까지 같다(같은 식, 같은 바꾸기). 격자: (행수를 8 로 올린 것 / 8), 블록 256."""
    RB = 층정규화정수행()
    KB = 너비 // 32
    공유 = next(kb for kb in range(4, 49, 4) if RB * 너비 * 4 <= kb * 1024)
    L = ["(* 층정규화 + 정수 블록 계약의 활성값 바꾸기 — 커널생성.py 의 설명 *)",
         "[짧은실수 참조 입력에서 짧은실수 참조 감마와 짧은실수 참조 베타와 중간정수 참조 자릿값에 중간정수 참조 정보에 정수 행수로 "
         "층정규화정수]는 {",
         "    정수 tid = 블록안가로().",
         "    정수 lane = tid % 32.",
         f"    정수 행 = 블록가로() * {RB} + tid / 32.",
         f"    짧은실수 참조 판 = 공유판{공유}().",
         f"    정수 wb = (tid / 32) * {너비}.",
         "    행 < 행수이면 {"]
    L += 줄층정규화몸("        ", "입력", "감마", "0", "판", "행", 출력바탕="wb")
    L += ["        워프동기화().",
          "        정수 정보폭 = (행수 + 63) / 64 * 64.",
          f"        반복 (정수 bb = 0: bb < {KB}: bb += 4) {{"]
    if KB % 4 == 0:
        L += ["            정수 b = bb + lane / 8."]
        L += 블록바꾸기몸(lambda i: f"판[wb + b * 32 + (lane % 8) * 4 + {i}]", lambda j: f"정수 자{j} = 0. 자{j}",
                        lambda v: f"정보[b * 정보폭 + 행] = {v}.", "            ")
        L += [f"            자릿값[({j} * 행수 + 행) * {너비 // 4} + b * 8 + (lane % 4) * 2 + (lane % 8) / 4] = 자{j}." for j in range(자리수)]
    else:                                                # 넘치는 블록은 마지막 블록을 읽고 쓰지 않는다(셔플은 모든 레인이 함께)
        L += ["            정수 b0 = bb + lane / 8.", "            정수 b = b0.", f"            b >= {KB}이면 {{ b = {KB - 1}. }}"]
        L += 블록바꾸기몸(lambda i: f"판[wb + b * 32 + (lane % 8) * 4 + {i}]", lambda j: f"정수 자{j} = 0. 자{j}",
                        lambda v: f"b0 < {KB}이면 {{ 정보[b * 정보폭 + 행] = {v}. }}", "            ")
        L += [f"            b0 < {KB}이면 {{"]
        L += [f"                자릿값[({j} * 행수 + 행) * {너비 // 4} + b * 8 + (lane % 4) * 2 + (lane % 8) / 4] = 자{j}." for j in range(자리수)]
        L += ["            }"]
    L += ["        }", "    }", "}"]
    return L


def 층정규화정수행(D=None):
    """층정규화정수의 블록이 맡는 행(워프) 수 — 판에 행마다 너비 칸을 두므로 너비가 크면 넷(호스트의 격자도 이 함수로)."""
    D = D or 너비
    return 8 if 8 * D * 4 <= 24 * 1024 else 4


def 정수판바꾸기(판x, K, KB, DX, DM0, T, ind):
    """판의 x (K 칸 — 판x 는 판에서의 시작 자리, 식) → 네 자리 낱말(판i[DX + j·K/4 + b·8 + 레인 % 8])과 블록의 M_0(판i[DM0 + b]) —
    정수로 커널과 같은 계산. 워프 하나가 한 바퀴에 블록 넷. K · KB 는 식이어도 된다(K 는 4 의 배수)."""
    o = [f"{ind}{{", f"{ind}    정수 lane = tid % 32.",
         f"{ind}    반복 (정수 bb = (tid / 32) * 4: bb < {KB}: bb += {T // 32 * 4}) {{",
         f"{ind}        정수 b0 = bb + lane / 8.",
         f"{ind}        정수 b = b0.",
         f"{ind}        b >= {KB}이면 {{ b = {KB} - 1. }}"]
    o += 블록바꾸기몸(lambda i: f"판[{판x} + b * 32 + (lane % 8) * 4 + {i}]", lambda j: f"정수 자{j} = 0. 자{j}",
                    lambda v: f"b0 < {KB}이면 {{ 판i[{DM0} + b] = {v}. }}", ind + "        ")
    o += [f"{ind}        b0 < {KB}이면 {{"]
    o += [f"{ind}            판i[{DX} + {j} * (({K}) / 4) + b * 8 + lane % 8] = 자{j}." for j in range(자리수)]
    o += [f"{ind}        }}", f"{ind}    }}", f"{ind}    동기화().", f"{ind}}}"]
    return o


def 정수판바꾸기제자리(읽기, K, KB, DX, DM0, T, ind, 바퀴):
    """정수판바꾸기의 7단계 판(깊이가 커서 x 와 네 자리를 판에 따로 둘 수 없을 때): 스레드가 맡을 블록들(바퀴마다 T/8 블록 — 레인
    여덟이 블록 하나)의 네 칸씩을 모두 레지스터로 읽고(읽기(e) — 칸 e 의 식; 판이어도 전역이어도 된다), 동기화한 뒤 네 자리 낱말을
    판i[DX + j·K/4 + b·8 + 레인 % 8] 에 쓴다(x 의 자리와 겹쳐도 된다). 블록 번호가 넘치는 레인은 마지막 블록을 읽고 쓰지 않는다.
    값은 정수판바꾸기 · 정수로와 같다(같은 바꾸기)."""
    nb = T // 8
    o = [f"{ind}{{", f"{ind}    정수 lane = tid % 32."]
    for r in range(바퀴):
        o += [f"{ind}    정수 b0_{r} = {nb * r} + tid / 8.",
              f"{ind}    정수 b_{r} = b0_{r}.",
              f"{ind}    b_{r} >= {KB}이면 {{ b_{r} = {KB} - 1. }}"]
        o += [f"{ind}    짧은실수 xr{r}_{i} = {읽기(f'b_{r} * 32 + (lane % 8) * 4 + {i}')}." for i in range(4)]
    o.append(f"{ind}    동기화().")
    for r in range(바퀴):
        o.append(f"{ind}    {{")
        o += 블록바꾸기몸(lambda i: f"xr{r}_{i}", lambda j: f"정수 자{j} = 0. 자{j}",
                        lambda v: f"b0_{r} < {KB}이면 {{ 판i[{DM0} + b_{r}] = {v}. }}", ind + "        ")
        o += [f"{ind}        b0_{r} < {KB}이면 {{"]
        o += [f"{ind}            판i[{DX} + {j} * (({K}) / 4) + b_{r} * 8 + lane % 8] = 자{j}." for j in range(자리수)]
        o += [f"{ind}        }}", f"{ind}    }}"]
    o += [f"{ind}    동기화().", f"{ind}}}"]
    return o


def 정수열묶음(K, N, 작음=None):
    """정수 줄 판 · 메가커널의 열 묶음 w(블록이 한 번에 맡는 열 수) — small: 열수 3840 이상 32, 1920 이상 16, 아니면 8; 그 밖의 크기:
    w · 블록수 ≤ 800 (판의 u · 척도 자리). 작음: small 인가(호스트가 넘긴다 — 없으면 지금 만드는 크기)."""
    if 작은가() if 작음 is None else 작음:
        return 32 if N >= 3840 else (16 if N >= 1920 else 8)
    return 800 // (K // 32)


def 정수열곱(형식, 면, KB, N, Np, w, 값, 척, 값바탕, 척바탕, DX, DM0, US, 척판, SD, T, 치우침식, 끝식, 그룹, ind):
    """정수 블록 계약의 행 하나 × 열 묶음(w 열, 그룹 번호는 식 그룹): (열, 블록) 쌍을 스레드가 나눠 S_j = Σ dp4a(자리 낱말,
    가중치 낱말) — 정확한 블록 합 — 로 u 를 구해 판[US + b·w + 열] 에 두고, 열마다 스레드 하나가 y ← 곱해더하기(u_b, d_b, y)
    를 블록 차례로. Q4_0 은 니블을 부호 없이 곱하고(바이트넷곱더하기_나부호없음) 마법수 M' 로 8 · ΣD_j 를 뺀다 — 결과의 정수는
    같다(정수 텐서 코어 판과 비트까지 같다). 값바탕 · 척도바탕은 층의 바탕(원소 단위 식, 끝에 + 가 붙은 꼴
    또는 빈 문자열). 면 = 자리 한 면의 낱말 수(K / 4 — 4 의 배수임이 드러나는 식이어야 넷씩 묶어 읽는다). KB · N · Np · w 는 식이어도
    된다. 쌍을 맡은 스레드가 척도 d_b,n 도 판(척판[SD + b·w + 열])에 넓혀 두어, 사슬이 전역 메모리를 기다리지 않게 한다."""
    Q4 = 형식 == "Q4_0"
    o = [f"{ind}반복 (정수 p = tid: p < ({w}) * ({KB}): p += {T}) {{",
         f"{ind}    정수 nl = p % ({w}).",
         f"{ind}    정수 b = p / ({w}).",
         f"{ind}    정수 n = ({그룹}) * ({w}) + nl.",
         f"{ind}    n >= {N}이면 {{ n = {N} - 1. }}",
         f"{ind}    정수 wb = {값바탕}(b * ({N}) + n) * {4 if Q4 else 8}."]
    if Q4:
        for i in range(4):
            o += [f"{ind}    중간정수 ww{i} = {값}[wb + {i}].",
                  f"{ind}    중간정수 wq{2 * i} = {니블부호(f'ww{i} & 252645135')}.",
                  f"{ind}    중간정수 wq{2 * i + 1} = {니블부호(f'(ww{i} >> 4) & 252645135')}."]
    else:
        o += [f"{ind}    중간정수 wq{i} = {값}[wb + {i}]." for i in range(8)]
    곱 = "바이트넷곱더하기"
    for j in range(자리수):
        o += [f"{ind}    중간정수 x{j}_{q} = 판i[{DX} + {j} * {면} + b * 8 + {q}]." for q in range(8)]
        o.append(f"{ind}    중간정수 S{j} = 0.")
        o += [f"{ind}    S{j} = {곱}(x{j}_{q}, wq{q}, S{j})." for q in range(8)]
    o.append(f"{ind}    중간정수 M0 = 판i[{DM0} + b].")
    v = lambda j: f"(비트실수((M0 + {8 * j << 23}) + S{j}) - 비트실수(M0 + {8 * j << 23}))"
    u = v(자리수 - 1)                                        # ((v₃ + v₂) + v₁) + v₀ · v₁ + v₀ — 맨 위 자리부터 차례로
    for j in range(자리수 - 2, 0, -1):
        u = f"({u} + {v(j)})"
    u = f"{u} + {v(0)}"
    o += [f"{ind}    {척판}[{SD} + b * ({w}) + nl] = {척}[{척바탕}b * ({Np}) + n].",
          f"{ind}    판[{US} + b * ({w}) + nl] = {u}.",
          f"{ind}}}",
          f"{ind}동기화().",
          f"{ind}{{",
          f"{ind}    정수 열 = ({그룹}) * ({w}) + tid.",
          f"{ind}    (tid < {w} 그리고 열 < {N})이면 {{",
          f"{ind}        짧은실수 y = 0 으로 짧은실수.",
          f"{ind}        반복 (정수 b는 0부터 {KB} 전까지) {{ y = 곱해더하기(판[{US} + b * ({w}) + tid], {척판}[{SD} + b * ({w}) + tid], y). }}",
          f"{ind}        짧은실수 v = y + {치우침식}."]
    o += [f"{ind}        " + x for x in 끝식]
    o += [f"{ind}    }}", f"{ind}}}", f"{ind}동기화()."]
    return o


def 정수줄선형(epi, 이름, 형식):
    """정수 블록 계약의 행렬곱 — 행이 적을 때(로짓의 행 하나 · 생성 · 하나씩): 블록 하나(256 스레드)가 열 묶음 하나(열수 3840
    이상이면 32 열, 1920 이상이면 16, 아니면 8)를 행마다: 입력 행을 판에 올려 네 자리로 바꾸고(정수판바꾸기), 정수열곱. 생성
    메가커널의 행렬곱 단계와 같은 코드 — 그래서 같은 값(그리고 정수 텐서 코어 판과도 같은 값)."""
    T = 256
    if not 작은가():
        return 정수줄선형큰(epi, 이름, 형식)
    XS, DX, DM0, US = 0, 3072, 6144, 6240                     # x [3072], 네 자리 [4][3072] 바이트, M0 [96], u [96 · 8 · …], 척도 [같은 수]
    머리 = ("짧은실수 참조 입력에서 " + 가중선언("가중치", "척도", 형식) + "짧은실수 참조 치우침과 " +
           ("짧은실수 참조 잔차와 " if epi == "_잔차" else "") + (f"{KV} 참조 키칸과 {KV} 참조 값칸과 " if epi == "_KV" else "") +
           "짧은실수 참조 출력에 정수 행수로 정수 깊이로 정수 열수로" +
           (" 정수 묶음안행수로 정수 위치시작으로 정수 최대길이로" if epi == "_KV" else ""))
    L = [f"(* 정수 블록 계약의 행렬곱 — 행이 적을 때(dp4a). 커널생성.py 의 설명 *)",
         f"[{머리} {이름}]는 {{",
         "    정수 tid = 블록안가로().",
         "    짧은실수 참조 판 = 공유판40().",
         "    중간정수 참조 판i = 판 으로 중간정수 참조.",
         "    작은정수 참조 판b = 판 으로 작은정수 참조.",
         "    정수 블록수 = 깊이 / 32.",
         "    정수 깊이16 = 깊이 / 16 * 4.",
         "    정수 척도폭 = (열수 + 63) / 64 * 64.",
         "    정수 w = 8.",
         "    열수 >= 1920이면 { w = 16. }",
         "    열수 >= 3840이면 { w = 32. }",
         "    정수 그룹 = 블록가로().",
         "    정수 자리 = 0.", "    정수 자리위 = 0.", "    짧은실수 u = 0 으로 짧은실수.", "    짧은실수 th = 0 으로 짧은실수.",
         "    반복 (정수 행 = 0: 행 < 행수: 행 += 1) {",
         f"        반복 (정수 i = tid: i < 깊이: i += {T}) {{ 판[{XS} + i] = 입력[행 * 깊이 + i]. }}",
         "        동기화()."]
    L += 정수판바꾸기(str(XS), "깊이", "블록수", DX, DM0, T, "        ")
    끝식 = (자리두기("행", "") if epi == "_KV" else []) + 끝(epi, "v", "행", "열", "자리", "")
    L += 정수열곱(형식, "깊이16", "블록수", "열수", "척도폭", "w", "가중치", "척도", "", "", DX, DM0, US, "판", US + 768, T, "치우침[열]",
                 [x.strip() for x in 끝식], "그룹", "        ")
    L += ["    }", "}"]
    return L


def 정수줄선형큰(epi, 이름, 형식):
    """정수줄선형의 7단계 판(깊이가 6400 까지): 입력 행을 전역에서 바로 레지스터로 읽어 네 자리를 판의 0 부터(정수판바꾸기제자리),
    M_0 · u · 척도는 그 뒤에. 열 묶음 w = 800 / 블록수(u · 척도 자리 800 칸씩). 같은 계산이라 값은 small 의 판 · 타일 판과 같은 약속."""
    T = 256
    X크기 = max(너비, 확장폭)
    DX, DM0 = 0, X크기
    US = DM0 + X크기 // 32
    SD = US + 800
    공유 = next(kb for kb in range(4, 49, 4) if (SD + 800) * 4 <= kb * 1024)
    바퀴 = (X크기 // 32 + T // 8 - 1) // (T // 8)
    머리 = ("짧은실수 참조 입력에서 " + 가중선언("가중치", "척도", 형식) + "짧은실수 참조 치우침과 " +
           ("짧은실수 참조 잔차와 " if epi == "_잔차" else "") + (f"{KV} 참조 키칸과 {KV} 참조 값칸과 " if epi == "_KV" else "") +
           "짧은실수 참조 출력에 정수 행수로 정수 깊이로 정수 열수로" +
           (" 정수 묶음안행수로 정수 위치시작으로 정수 최대길이로" if epi == "_KV" else ""))
    L = [f"(* 정수 블록 계약의 행렬곱 — 행이 적을 때(dp4a), 큰 깊이 판. 커널생성.py 의 설명 *)",
         f"[{머리} {이름}]는 {{",
         "    정수 tid = 블록안가로().",
         f"    짧은실수 참조 판 = 공유판{공유}().",
         "    중간정수 참조 판i = 판 으로 중간정수 참조.",
         "    작은정수 참조 판b = 판 으로 작은정수 참조.",
         "    정수 블록수 = 깊이 / 32.",
         "    정수 깊이16 = 깊이 / 16 * 4.",
         "    정수 척도폭 = (열수 + 63) / 64 * 64.",
         "    정수 w = 800 / 블록수.",
         "    정수 그룹 = 블록가로().",
         "    정수 자리 = 0.", "    정수 자리위 = 0.", "    짧은실수 u = 0 으로 짧은실수.", "    짧은실수 th = 0 으로 짧은실수.",
         "    반복 (정수 행 = 0: 행 < 행수: 행 += 1) {"]
    L += 정수판바꾸기제자리(lambda e: f"입력[행 * 깊이 + {e}]", "깊이", "블록수", DX, DM0, T, "        ", 바퀴)
    끝식 = (자리두기("행", "") if epi == "_KV" else []) + 끝(epi, "v", "행", "열", "자리", "")
    L += 정수열곱(형식, "깊이16", "블록수", "열수", "척도폭", "w", "가중치", "척도", "", "", DX, DM0, US, "판", SD, T, "치우침[열]",
                 [x.strip() for x in 끝식], "그룹", "        ")
    L += ["    }", "}"]
    return L


# 정수 텐서 코어 타일 판: 이름 → (워프 행 WM, 워프 열 WN, 워프의 행 조각 MT, 열 조각 NT, 실행한도의 블록 수, 판 수). 블록이 맡는
# 칸은 (16 · MT · WM) × (8 · NT · WN), 스레드 32 · WM · WN, 비동기복사를 판 수 − 1 블록 앞서(공유 메모리가 48 KB 를 넘으면 판 둘).
# 판마다 칸을 나누는 모양만 다르고 칸마다의 계산은 같다 — 그래서 호스트가 모양마다 재서 빠른 것을 골라도 비트가 같다.
정수판들 = {"정수타일선형": (2, 2, 2, 8, 3, 2), "정수좁은타일선형": (2, 2, 2, 4, 3, 2), "정수작은타일선형": (2, 2, 1, 4, 4, 2),
           "정수아주작은타일선형": (2, 2, 1, 2, 5, 2), "정수넓은타일선형": (2, 4, 2, 8, 1, 3), "정수긴타일선형": (1, 4, 2, 8, 3, 3)}


# 자리 둘(8단계)의 판: 위의 여섯에 더해, 레지스터가 줄어든 만큼 워프를 더 띄우는 모양(블록 256 · 128 스레드, 워프마다 행 조각 하나,
# 판 넷) — 자리 둘 타일은 읽기 · 동기화의 지연에 묶여 있어(시간 나누기: 읽기만 155 / 전부 279 µs) 점유가 곧 속도다. 자리 넷의 소스는
# 그대로(판 여섯)다.
정수판들둘 = dict(정수판들, **{"정수긴4타일선형": (1, 4, 2, 8, 3, 4), "정수긴2타일선형": (1, 4, 2, 8, 2, 4),
                             "정수깊은타일선형": (1, 4, 4, 4, 3, 3), "정수깊은넓은타일선형": (2, 2, 4, 4, 3, 3)})
# 10단계(정수 KV 판만 — 8단계 모듈의 소스는 그대로): 판 표의 7째 칸 — True 는 겹침(앞 블록의 끝 계산을 다음 블록의 mma 와 같은 워프에서
# 겹친다; 합 두 벌이라 레지스터 255, SM 에 블록 한둘), "엇갈림" 은 열 조각 엇갈림. 재서 모두 느리거나 같았다(XL c_fc 1024: 깊은 275 µs 대
# 겹침긴 (1,4,2,4,2,3,True) 414 · 겹침깊은 (2,4,2,4,1,3,True) 383 · 반긴 (1,4,2,4,3,3) 323 · 엇갈림 같음) — 표에 두지 않는다.
정수판들KV = dict(정수판들둘)
# 11단계(새 길 — ldmatrix · 섞기 · Pd 접기): 타일선형에 비동기 판 셋 — XL 의 네 행렬곱 모두에서 가장 빨랐다(c_fc 251 µs · c_attn 194 ·
# c_proj 77 · mlp c_proj 268, Q8_0; 10단계 길의 깊은 판 284 · 221 · 91 · 320).
정수판들KV["정수세판타일선형"] = (2, 2, 2, 8, 3, 3)


def 정수판표(자리=None, 정수KV=None):
    """지금 만드는(또는 자리수의) 판 표 — 정수 KV 판(KV == "정수")은 10단계의 판까지."""
    if (KV == "정수" if 정수KV is None else 정수KV):
        return 정수판들KV
    return 정수판들둘 if (자리수 if 자리 is None else 자리) == 2 else 정수판들


def 정수판모양(판):
    """정수 텐서 코어 판 → (블록의 행 수, 열 수, 스레드 수)."""
    WM, WN, MT, NT = 정수판들KV[판][:4]
    return 16 * MT * WM, 8 * NT * WN, 32 * WM * WN


def 정수타일선형(epi, 이름, 형식, 판="정수타일선형"):
    """정수 블록 계약의 행렬곱 — BM × BN 칸을 블록 하나(워프 WM × WN, 워프마다 16·MT × 8·NT)가. k 를 블록(32 줄)씩: 판에
    [자리 4][행 BM][32 바이트], 가중치 [열][16 · 32 바이트], 정보 [행 BM](M_0), 척도 [열] 을 비동기복사로 앞서 올린다.
    워프는 네 자리의 A 조각(행 조각 MT 개)을 레지스터에 다 들고, 열 조각마다 네 자리의 정수텐서곱(서로 기대지 않는다)으로
    블록 합 S_j 를 얻어 u 를 구하고 y ← 곱해더하기(u, d, y). 판(공유 메모리의 버퍼)은 S 개 — 비동기복사를 S − 1 블록 앞서.

    u 는 계약의 ((v₃ + v₂) + v₁) + v₀ 와 비트까지 같은 다른 길로 구한다 (v_j = S_j · 2^(8j+E−29) 는 정확한 짧은실수, RN = 가까운
    쪽 반올림, E ∈ [−98, 100] 이라 아래 값은 모두 정규수 범위):
      Q4_0 (|q| ≤ 8 → |S₃| ≤ 2¹⁴, |S₀…₂| ≤ 2¹⁵): T = (256·S₃ + S₂)·256 + S₁ 은 정수로 정확(|T| < 2³¹). |256·S₃ + S₂| < 2²⁴ 라
        v₃ + v₂ 는 정확하고, (v₃ + v₂) + v₁ = RN(T · 2^(E−21)) = RN(T) · 2^(E−21). u = 곱해더하기(RN(T), 2^(E−21), v₀) — 곱이
        정확하니 RN(… + v₀) 그대로.
      Q8_0 (|q| ≤ 128): T = 256·S₃ + S₂ (|T| < 2²⁷), v₃ + v₂ = RN(T) · 2^(E−13), (v₃ + v₂) + v₁ = 곱해더하기(RN(T), 2^(E−13), v₁),
        u = 그것 + v₀.
    RN(T) 는 정수 → 짧은실수 변환(cvt.rn), v_j 는 마법수(비트실수(M_j + S_j) − 비트실수(M_j)), 2^(E−21) · 2^(E−13) 의 비트는
    M_0 − 2²² − 15·2²³ · M_0 − 2²² − 7·2²³.
    자리 둘(8단계, 자리수 = 2 — v_j = S_j · 2^(8j+E−13)): u = v₁ + v₀ 를 계약 그대로 — v_j 는 마법수로(정확), 덧셈 하나(반올림
    한 번 — 계약의 RN 그대로). 마법수 M_j 는 정수텐서곱의 누적 입력 C 로 넣는다 — 텐서 코어가 M_j + S_j 를 정수로 정확히 더해
    주니(출력 칸의 행에 맞춰 c₀ c₁ 은 행 g 의 M_j, c₂ c₃ 은 행 g + 8 의 M_j), 끝 계산은 칸마다 실수 뺄셈 둘 · 덧셈 하나 · 곱해더하기
    하나다. 자리 둘 타일은 텐서 파이프가 아니라 명령 발행에 묶여 있어(출력 칸마다 블록마다의 끝 계산), 명령 수가 곧 속도다.
    정수로가 블록의 낱말을 [0 4 1 5 2 6 3 7] 차례로 두어, 레인은 A 조각의 두 낱말(같은
    행의 k 4t… 와 16+4t…)을 8 바이트 하나로 읽는다(값과는 상관없다). 행 · 열이 넘치면 마지막 행 · 열을 읽고 쓰지 않는다. Q8_0
    가중치의 32 바이트 줄은 열의 비트 2 로 16 바이트 반쪽을 바꿔 둔다(뱅크가 겹치지 않게)."""
    WM, WN, MT, NT, 한도, S, *겹 = 정수판들KV[판]
    겹침 = bool(겹 and 겹[0] is True)                       # 10단계: 앞 블록의 끝 계산을 다음 블록의 mma 와 겹친다(자리 둘 · cvt 길만)
    엇갈림 = bool(겹 and 겹[0] == "엇갈림")                  # 10단계: 열 조각 n + 1 의 mma 뒤에 열 조각 n 의 끝 계산(같은 워프 안의 겹침)
    # 11단계(정수 KV 모듈만): A 조각을 ldmatrix 로 — 판의 A 는 행의 비트 2 로 16 바이트 반쪽을 바꿔 두고(뱅크 충돌 없이), 레인 ℓ 이 행렬
    # ⌊ℓ/8⌋(0: 행 0~7 · 반쪽 0 → a₀, 1: 행 8~15 · 반쪽 0 → a₁, 2: 행 0~7 · 반쪽 1 → a₂, 3: 행 8~15 · 반쪽 1 → a₃)의 줄 ℓ % 8 을 준다. 반쪽
    # 안의 낱말은 정수로의 차례 [0 4 1 5 | 2 6 3 7] 그대로 레인 t 에 오므로 mma 의 k 넷 묶음 t 는 원래의 묶음 π(t) (π = 0 4 1 5 2 6 3 7)
    # 이다 — B 도 같은 π 차례로 읽는다(b₀ = 묶음 π(t), b₁ = 묶음 π(t + 4) = π(t) + 2). 블록 합 S_j 는 정확한 정수 합이라 k 의 차례와
    # 상관없이 같다. 척도는 반실수 그대로 한 블록 앞서 읽고 판에 둘 때 넓힌다(읽기와 쓰임 사이가 한 블록 — 10단계는 읽자마자 넓혀 기다렸다).
    행렬 = KV == "정수" and 타일읽기 == "행렬"
    변형 = 타일변형 | (타일기본 if 행렬 and not 겹침 else frozenset())  # 새 길의 기본(값과 상관없음 — 11단계에서 번갈아 재서 고름)
    Q4 = 형식 == "Q4_0"
    T = 32 * WM * WN
    척수 = 1 if 8 * NT * WN <= T else 2                       # 11단계 새 길: 스레드마다 나르는 척도 수(BN ≤ T 면 하나)
    WR, WC = 16 * MT, 8 * NT                                # 워프의 행 · 열 수
    BM, BN = WR * WM, WC * WN                                # 블록의 행 · 열 수
    BW = 4 if Q4 else 8                                      # 열마다 가중치 낱말 수
    OA, OB = 0, 8 * 자리수 * BM                            # 자리마다 [행 BM][32 바이트] = 8·BM 낱말
    OI = OB + BN * BW
    OS = OI + BM
    BUF = OS + (BN if 자리수 == 2 else BN // 2)              # 척도: 자리 둘은 짧은실수(열마다 한 번 넓혀 둔다), 넷은 반실수 그대로
    if S * BUF * 4 > 48 * 1024:
        S = 2
    공유 = next(kb for kb in range(4, 49, 4) if S * BUF * 4 <= kb * 1024)
    머리 = ("중간정수 참조 자릿값에서 중간정수 참조 정보와 " + 가중선언("가중치", "척도", 형식) + "짧은실수 참조 치우침과 " +
           ("짧은실수 참조 잔차와 " if epi == "_잔차" else "") + (f"{KV} 참조 키칸과 {KV} 참조 값칸과 " if epi == "_KV" else "") +
           ("중간정수 참조 다음정보와 중간정수 참조 다음자리에" if epi == "_겔루정수" else
            "중간정수 참조 자릿값q와 중간정수 참조 정보q와 중간정수 참조 키칸과 중간정수 참조 값칸과 부호없는 작은정수 참조 키지수와 "
            "부호없는 작은정수 참조 값지수에" if epi == "_KV정수" else "짧은실수 참조 출력에") +
           " 정수 행수로 정수 깊이로 정수 열수로 정수 척도폭으로" +
           (" 정수 묶음안행수로 정수 위치시작으로 정수 최대길이로" if epi in ("_KV", "_KV정수") else ""))
    assert epi not in ("_겔루정수", "_KV정수") or WC % 32 == 0, "_겔루정수 · _KV정수 는 워프의 열이 블록(32 열)으로 나뉘어야 한다"
    L = [f"(* 정수 블록 계약의 행렬곱({형식}) — {BM} × {BN} 칸, 워프 {WM} × {WN}. 커널생성.py 의 설명 *)",
         f"(* 실행한도 {이름} {T} {한도} *)",
         f"[{머리} {이름}]는 {{",
         "    정수 tid = 블록안가로().",
         "    정수 lane = tid % 32.",
         "    정수 g = lane / 4.",
         "    정수 t = lane % 4.",
         f"    정수 wm = (tid / 32) / {WN}.",
         f"    정수 wn = (tid / 32) % {WN}.",
         f"    정수 행0 = 블록가로() * {BM}.",
         f"    정수 열0 = 블록세로() * {BN}.",
         f"    짧은실수 참조 판 = 공유판{공유}().",
         "    중간정수 참조 판i = 판 으로 중간정수 참조.",
         "    반실수 참조 판h = 판 으로 반실수 참조.",
         "    짧은실수 참조 자리넓 = 자릿값 으로 짧은실수 참조.",
         "    짧은실수 참조 정보넓 = 정보 으로 짧은실수 참조.",
         "    짧은실수 참조 가중넓 = 가중치 으로 짧은실수 참조.",
         "    짧은실수 참조 척도넓 = 척도 으로 짧은실수 참조.",
         "    정수 블록수 = 깊이 / 32.",
         "    정수 깊이4 = 깊이 / 4.",
         "    정수 정보폭 = (행수 + 63) / 64 * 64."]
    # 활성값의 자리 올리기: 16 바이트 조각 2·자리수·BM 개(자리 × 행 BM × 반쪽 2) — 조각 c 는 자리 c / 2BM, 행 (c / 2) % BM, 반쪽 c % 2
    assert (2 * 자리수 * BM) % T == 0
    NA = 2 * 자리수 * BM // T
    for u in range(NA):
        L += [f"    정수 ac{u} = tid + {T * u}.",
              f"    정수 ar{u} = (ac{u} / 2) % {BM}.",
              f"    정수 rg{u} = 행0 + ar{u}.",
              f"    rg{u} >= 행수이면 {{ rg{u} = 행수 - 1. }}",
              (f"    정수 a저장{u} = (ac{u} / {2 * BM}) * {8 * BM} + ar{u} * 8 + ((ac{u} % 2) ^ ((ar{u} >> 2) & 1)) * 4." if 행렬 else
               f"    정수 a저장{u} = (ac{u} / {2 * BM}) * {8 * BM} + ar{u} * 8 + (ac{u} % 2) * 4."),
              f"    정수 ga{u} = ((ac{u} / {2 * BM}) * 행수 + rg{u}) * 깊이4 + (ac{u} % 2) * 4."]
    L += ["    정수 gi = 행0 + tid * 4.",
          f"    정수 gs = 블록세로() * {BN // 2} + tid * 4.",
          "    정수 척도걸음 = 척도폭 / 2."]
    # 가중치 올리기: Q4_0 — 열마다 16 바이트 조각 하나, Q8_0 — 열마다 둘(반쪽)
    NBc = BN * (1 if Q4 else 2)
    nb = (NBc + T - 1) // T
    for u in range(nb):
        if Q4:
            L += [f"    정수 bc{u} = tid + {T * u}.", f"    정수 cg{u} = 열0 + bc{u}.", f"    cg{u} >= 열수이면 {{ cg{u} = 열수 - 1. }}",
                  f"    정수 b저장{u} = bc{u} * 4.", f"    정수 gb{u} = cg{u} * 4."]
        else:
            L += [f"    정수 bc{u} = (tid + {T * u}) / 2.", f"    정수 bh{u} = tid % 2.", f"    정수 cg{u} = 열0 + bc{u}.",
                  f"    cg{u} >= 열수이면 {{ cg{u} = 열수 - 1. }}",
                  f"    정수 b저장{u} = bc{u} * 8 + ((bh{u} ^ ((bc{u} >> 2) & 1)) * 4).", f"    정수 gb{u} = cg{u} * 8 + bh{u} * 4."]
    L.append(f"    정수 열걸음 = 열수 * {BW}.")
    L += [(f"    정수 oa = {OA} + (wm * {WR} + ((lane >> 3) & 1) * 8 + (lane & 7)) * 8 + ((lane >> 4) ^ ((lane >> 2) & 1)) * 4." if 행렬 else
           f"    정수 oa = {OA} + (wm * {WR} + g) * 8 + t * 2."),
          f"    정수 oi = {OI} + wm * {WR} + g.",
          f"    정수 os = {OS * 2 if 자리수 == 4 else OS} + wn * {WC} + t * 2."]
    if 자리수 == 2:                                          # 척도를 레지스터로 한 블록 앞서 읽어(넓히며) 판에 짧은실수로 둔다
        assert BN // 2 <= T
        if 행렬:
            L += [f"    정수 gsc = 블록세로() * {BN} + tid{' * 2' if 척수 == 2 else ''}."]
            L += [f"    반실수 sc{e} = (0 으로 짧은실수) 으로 반실수." for e in range(척수)]
            L += [f"    (tid < {BN // 척수} 그리고 gsc < 척도폭)이면 {{ " + " ".join(f"sc{e} = 척도[gsc + {e}]." for e in range(척수)) + " }"]
        else:
            L += [f"    정수 gsc = 블록세로() * {BN} + tid * 2.",
                  f"    짧은실수 sc0 = 0 으로 짧은실수.", "    짧은실수 sc1 = 0 으로 짧은실수.",
                  f"    (tid < {BN // 2} 그리고 gsc < 척도폭)이면 {{ sc0 = 척도[gsc]. sc1 = 척도[gsc + 1]. }}"]
    if Q4 and 행렬:                                          # 묶음 q 는 낱말 q/2 의 니블 q%2 — b₀ = 묶음 π(t): 낱말 2(t%2), 니블 t/2; b₁ = 그 다음 낱말
        L += [f"    정수 ob = {OB} + (wn * {WC} + g) * 4 + (t & 1) * 2.", "    정수 nsh = (t >> 1) * 4."]
    elif Q4:
        L += [f"    정수 ob = {OB} + (wn * {WC} + g) * 4 + (t >> 1).", "    정수 nsh = (t & 1) * 4."]
    elif 행렬:                                               # 묶음 q 는 낱말 q(열의 비트 2 로 반쪽을 바꿔 둠) — b₀ = π(t) = t/2 + 4(t%2), b₁ = π(t) + 2
        L += ["    정수 sw = (g >> 2) & 1.",
              f"    정수 ob0 = {OB} + (wn * {WC} + g) * 8 + (((t >> 1) + (t & 1) * 4) ^ (sw * 4)).", "    정수 ob1 = ob0 + 2."]
    else:
        L += ["    정수 sw = (g >> 2) & 1.",
              f"    정수 ob0 = {OB} + (wn * {WC} + g) * 8 + sw * 4 + t.", f"    정수 ob1 = {OB} + (wn * {WC} + g) * 8 + (1 - sw) * 4 + t."]

    def 올리기(bb, kb, ind):
        o = [f"{ind}정수 올바탕 = ({bb}) * {BUF}.", f"{ind}정수 k8 = ({kb}) * 8."]
        o += [f"{ind}비동기복사16(판 에, 올바탕 + {OA} + a저장{u} 를, 자리넓 에서, ga{u} + k8 로)." for u in range(NA)]
        o.append(f"{ind}tid < {BM // 4}이면 {{ 비동기복사16(판 에, 올바탕 + {OI} + tid * 4 를, 정보넓 에서, gi + ({kb}) * 정보폭 로). }}")
        for u in range(nb):
            n_th = NBc - T * u                              # 이 조각을 맡는 스레드 수
            c = f"{ind}비동기복사16(판 에, 올바탕 + {OB} + b저장{u} 를, 가중넓 에서, gb{u} + ({kb}) * 열걸음 로)."
            o.append(c if n_th >= T else f"{ind}tid < {n_th}이면 {{ {c.strip()} }}")
        if 자리수 == 2 and 행렬:                             # 11단계: 스레드마다 척수 개 — 반실수를 판에 둘 때 넓힌다
            o += [f"{ind}(tid < {BN // 척수} 그리고 gsc < 척도폭)이면 {{"]
            o += [f"{ind}    판[올바탕 + {OS} + tid{' * 2' if 척수 == 2 else ''} + {e}] = sc{e}." for e in range(척수)]
            o += [f"{ind}    ({kb}) + 1 < 블록수이면 {{ " + " ".join(f"sc{e} = 척도[(({kb}) + 1) * 척도폭 + gsc + {e}]." for e in range(척수)) + " }",
                  f"{ind}}}"]
            return o
        if 자리수 == 2:                                      # 레지스터의 척도(블록 kb)를 판에 짧은실수로, 다음 블록의 척도를 레지스터로
            o += [f"{ind}(tid < {BN // 2} 그리고 gsc < 척도폭)이면 {{",
                  f"{ind}    판[올바탕 + {OS} + tid * 2] = sc0.",
                  f"{ind}    판[올바탕 + {OS} + tid * 2 + 1] = sc1.",
                  f"{ind}    ({kb}) + 1 < 블록수이면 {{ sc0 = 척도[(({kb}) + 1) * 척도폭 + gsc]. sc1 = 척도[(({kb}) + 1) * 척도폭 + gsc + 1]. }}",
                  f"{ind}}}"]
            return o
        # 척도: 열 여덟씩 16 바이트 — 척도폭(열수를 64 로 올림) 밖의 조각은 읽지 않는다(그 열은 쓰지 않는다)
        o.append(f"{ind}(tid < {BN // 8} 그리고 열0 + tid * 8 < 척도폭)이면 {{ 비동기복사16(판 에, 올바탕 + {OS} + tid * 4 를, 척도넓 에서, "
                 f"gs + ({kb}) * 척도걸음 로). }}")
        return o

    for p in range(S - 1):                                 # 앞의 S − 1 블록 (묶음은 블록마다 하나 — 없는 블록은 빈 묶음)
        L.append("    {" if p == 0 else f"    {p} < 블록수이면 {{")
        L += 올리기(str(p), str(p), "        ")
        L.append("    }")
        L.append("    비동기묶기().")
    L.append("    중간정수 영i = 0.")
    L.append("    짧은실수 영 = 0 으로 짧은실수.")
    M, N, J, H = range(MT), range(NT), tuple(range(자리수 - 1, -1, -1)), range(2)
    L += [f"    짧은실수 y{m}_{n}_{i} = 영." for m in M for n in N for i in range(4)]
    L += [f"    중간정수 a{j}_{m}_{c} = 0." for j in J for m in M for c in range(4)]
    L += [f"    중간정수 mp{m}_{h} = 0." for m in M for h in H]
    L += [f"    짧은실수 mf{m}_{h} = 영." for m in M for h in H]
    L += [f"    짧은실수 P{m}_{h} = 영." for m in M for h in H]
    if (not Q4 and 자리수 == 4) or 자리수 == 2:
        L += [f"    중간정수 mq{m}_{h} = 0." for m in M for h in H]
        L += [f"    짧은실수 mqf{m}_{h} = 영." for m in M for h in H]
    L += ["    중간정수 b0 = 0.", "    중간정수 b1 = 0.", "    짧은실수 d0 = 영.", "    짧은실수 d1 = 영."]
    if 자리수 == 2 and "Pd접기" in 변형:
        L += [f"    짧은실수 Pd{m}_{h}_{e} = 영." for m in M for h in H for e in range(2)]
    L += ["    정수 버퍼 = 0.", f"    정수 올림버퍼 = {S - 1}."]      # 이번 블록의 판, 이번에 올릴 블록(kb + S − 1)의 판 — 나머지 연산 없이 돌린다
    if 자리수 == 4:
        빼기 = 130023424 if Q4 else 62914560                 # 2²² + 15·2²³ · 2²² + 7·2²³
    else:
        빼기 = 197132288                                      # 2²² + 23·2²³ — 2^(E−13) 의 비트 = M_0 − 빼기

    def 올리기묶음(kb, ind):
        """블록 kb + S − 1 을 올림버퍼에 올리고 묶는다(없는 블록은 빈 묶음) — 블록 kb 의 동기화 뒤 어디서든(그 판은 블록 kb − 1 이 다 썼다)."""
        return [f"{ind}{kb} + {S - 1} < 블록수이면 {{"] + 올리기("올림버퍼", f"{kb} + {S - 1}", ind + "    ") + [f"{ind}}}", f"{ind}비동기묶기()."]

    def 블록앞(kb, ind, 올림=True):
        """블록 kb 의 머리: 기다리기 · 동기화 · 다음 올리기(올림이 거짓이면 부르는 쪽이 뒤에서) · 판의 자리 · A 조각 · 정보."""
        o = ([] if "기다림없음" in 변형 else [f"{ind}비동기기다리기({S - 2})."]) + ([] if "장벽없음" in 변형 else [f"{ind}동기화()."])
        if 올림:
            o += 올리기묶음(kb, ind)
        o += [f"{ind}정수 BB = 버퍼 * {BUF}.",
              f"{ind}정수 BA = BB + oa.", f"{ind}정수 BI = BB + oi.", f"{ind}정수 BS = BB * 2 + os." if 자리수 == 4 else f"{ind}정수 BS = BB + os."]
        o += [f"{ind}정수 BBq = BB + ob."] if Q4 else [f"{ind}정수 BB0 = BB + ob0.", f"{ind}정수 BB1 = BB + ob1."]
        for j in J:
            for m in M:
                oo = 8 * BM * j + 128 * m
                if 행렬:
                    o += [f"{ind}a{j}_{m}_{c} = 행렬조각읽기({c}, 판i, BA + {oo})." for c in range(4)]
                else:
                    o += [f"{ind}a{j}_{m}_0 = 판i[BA + {oo}].", f"{ind}a{j}_{m}_2 = 판i[BA + {oo + 1}].",
                          f"{ind}a{j}_{m}_1 = 판i[BA + {oo + 64}].", f"{ind}a{j}_{m}_3 = 판i[BA + {oo + 65}]."]
        for m in M:
            for h in H:
                o += [f"{ind}mp{m}_{h} = 판i[BI + {16 * m + 8 * h}].",
                      f"{ind}mf{m}_{h} = 비트실수(mp{m}_{h}).",
                      f"{ind}P{m}_{h} = 비트실수(mp{m}_{h} - {빼기})."]
                if (not Q4 and 자리수 == 4) or 자리수 == 2:
                    o += [f"{ind}mq{m}_{h} = mp{m}_{h} + 67108864.", f"{ind}mqf{m}_{h} = 비트실수(mq{m}_{h})."]
        return o

    def 열적재(n, ind, 따로=False):
        """열 조각 n 의 B 조각 둘과 척도 둘(따로: 척도를 열 조각마다의 변수 dn{n}_e 로 — 앞 조각의 끝 계산이 뒤에 올 때)."""
        if Q4:
            w0 = f"(판i[BBq + {32 * n}] >> nsh) & 252645135"
            w1 = f"(판i[BBq + {32 * n + (1 if 행렬 else 2)}] >> nsh) & 252645135"
            o = [f"{ind}b0 = {니블부호(w0)}.", f"{ind}b1 = {니블부호(w1)}."]
        else:
            o = [f"{ind}b0 = 판i[BB0 + {64 * n}].", f"{ind}b1 = 판i[BB1 + {64 * n}]."]
        if 따로:
            o += [f"{ind}짧은실수 dn{n}_{e} = {'판h' if 자리수 == 4 else '판'}[BS + {8 * n + e}]." for e in range(2)]
            if 자리수 == 2 and "Pd접기" in 변형:
                o += [f"{ind}짧은실수 Pdn{n}_{m}_{h}_{e} = P{m}_{h} * dn{n}_{e}." for m in M for h in H for e in range(2)]
            return o
        o += [f"{ind}d{e} = {'판h' if 자리수 == 4 else '판'}[BS + {8 * n + e}]." for e in range(2)]
        if 자리수 == 2 and "Pd접기" in 변형:
            o += [f"{ind}Pd{m}_{h}_{e} = P{m}_{h} * d{e}." for m in M for h in H for e in range(2)]
        return o

    def 곱(n, ind, 접=""):
        """열 조각 n 의 자리마다 정수텐서곱(접 이 있으면 미리 선언한 s{접}… 에 대입 — 겹침)."""
        o = []
        for m in M:
            for j in J:
                if 자리수 == 2 and 둘자리길 == "누적":        # 누적 입력에 마법수 — 결과가 바로 M_j + S_j
                    mj = "mq" if j == 1 else "mp"
                    cs = f"{mj}{m}_0, {mj}{m}_0, {mj}{m}_1, {mj}{m}_1"
                else:
                    cs = "영i, 영i, 영i, 영i"
                o += [f"{ind}{'' if 접 else '중간정수 '}s{접}{n}_{j}_{m}_{c} = 정수텐서곱({c}, a{j}_{m}_0, a{j}_{m}_1, a{j}_{m}_2, a{j}_{m}_3, b0, b1, {cs})."
                      for c in range(4)]
        return o

    def 끝계산(n, ind, 접="", Pn="P", dn="d", Pdn="Pd"):
        """열 조각 n 의 u · 곱해더하기 — s{접}…, 2^(E−13) 은 Pn{m}_{h}, 척도는 dn{e}, Pd 접기의 곱은 Pdn{m}_{h}_{e}."""
        o = []
        for m in M:
            for c in range(4):
                h, s = c >> 1, lambda j: f"s{접}{n}_{j}_{m}_{c}"
                v0 = f"(비트실수(mp{m}_{h} + {s(0)}) - mf{m}_{h})"
                if 자리수 == 2 and 둘자리길 == "누적":
                    o += [f"{ind}y{m}_{n}_{c} = 곱해더하기((비트실수({s(1)}) - mqf{m}_{h}) + (비트실수({s(0)}) - mf{m}_{h}), {dn}{c & 1}, y{m}_{n}_{c})."]
                elif 자리수 == 2 and 둘자리길 == "마법둘":
                    v1 = f"(비트실수(mq{m}_{h} + {s(1)}) - mqf{m}_{h})"
                    o += [f"{ind}y{m}_{n}_{c} = 곱해더하기({v1} + {v0}, {dn}{c & 1}, y{m}_{n}_{c})."]
                elif 자리수 == 2 and "Pd접기" in 변형:
                    o += [f"{ind}중간정수 T{접}{n}_{m}_{c} = {s(1)} * 256 + {s(0)}.",
                          f"{ind}y{m}_{n}_{c} = 곱해더하기(T{접}{n}_{m}_{c} 으로 짧은실수, {Pdn}{m}_{h}_{c & 1}, y{m}_{n}_{c})."]
                elif 자리수 == 2:
                    o += [f"{ind}중간정수 T{접}{n}_{m}_{c} = {s(1)} * 256 + {s(0)}.",
                          f"{ind}y{m}_{n}_{c} = 곱해더하기((T{접}{n}_{m}_{c} 으로 짧은실수) * {Pn}{m}_{h}, {dn}{c & 1}, y{m}_{n}_{c})."]
                elif Q4:
                    o += [f"{ind}중간정수 T{n}_{m}_{c} = ({s(3)} * 256 + {s(2)}) * 256 + {s(1)}.",
                          f"{ind}y{m}_{n}_{c} = 곱해더하기(곱해더하기(T{n}_{m}_{c} 으로 짧은실수, P{m}_{h}, {v0}), d{c & 1}, y{m}_{n}_{c})."]
                else:
                    v1 = f"(비트실수(mq{m}_{h} + {s(1)}) - mqf{m}_{h})"
                    o += [f"{ind}중간정수 T{n}_{m}_{c} = {s(3)} * 256 + {s(2)}.",
                          f"{ind}y{m}_{n}_{c} = 곱해더하기(곱해더하기(T{n}_{m}_{c} 으로 짧은실수, P{m}_{h}, {v1}) + {v0}, d{c & 1}, y{m}_{n}_{c})."]
        return o

    def 버퍼돌리기(ind):
        return [f"{ind}버퍼 = 버퍼 + 1.", f"{ind}버퍼 == {S}이면 {{ 버퍼 = 0. }}", f"{ind}올림버퍼 = 올림버퍼 + 1.", f"{ind}올림버퍼 == {S}이면 {{ 올림버퍼 = 0. }}"]

    if not 겹침:
        L.append("    반복 (정수 kb는 0부터 블록수 전까지) {")
        I = "        "
        올리기뒤 = "올리기뒤" in 변형                     # 11단계(값과 상관없음): 다음 블록 올리기를 몸의 끝으로 — mma 앞의 명령을 줄인다
        L += 블록앞("kb", I, 올림=not 올리기뒤)
        끝 = lambda n, dn="d", Pdn="Pd": (끝계산(n, I, dn=dn, Pdn=Pdn) if "끝없음" not in 변형 else
                                          [f"{I}y{m}_{n}_{c} = y{m}_{n}_{c} + (s{n}_1_{m}_{c} 으로 짧은실수)." for m in M for c in range(4)])
        if "섞기" in 변형:
            # 11단계(값과 상관없음): 열 조각 n 의 mma 묶음(넷씩) 사이사이에 열 조각 n − 1 의 끝 계산을 고르게 — 척도는 조각마다 따로
            for n in N:
                L += 열적재(n, I, 따로=True)
                g = 곱(n, I)
                묶음 = [g[i:i + 4] for i in range(0, len(g), 4)]
                e = 끝(n - 1, f"dn{n - 1}_", f"Pdn{n - 1}_") if n > 0 else []
                k = len(묶음)
                for i, gi in enumerate(묶음):
                    L += gi + e[i * len(e) // k:(i + 1) * len(e) // k]
            L += 끝(N[-1], f"dn{N[-1]}_", f"Pdn{N[-1]}_")
        elif "엇갈림" in 변형 or 엇갈림:
            # 11단계에서 고침: 10단계의 이 길은 열 조각 n 의 척도(d0 · d1)를 읽은 뒤에 n − 1 의 끝 계산을 해서 값이 틀렸다(뒤 조각의 척도).
            # 척도를 조각마다 따로 둔다.
            for n in N:
                L += 열적재(n, I, 따로=True) + 곱(n, I) + (끝(n - 1, f"dn{n - 1}_", f"Pdn{n - 1}_") if n > 0 else [])
            L += 끝(N[-1], f"dn{N[-1]}_", f"Pdn{N[-1]}_")
        else:
            for n in N:
                L += 열적재(n, I) + 곱(n, I) + 끝(n)
        if 올리기뒤:
            L += 올리기묶음("kb", I)
        L += 버퍼돌리기(I) + ["    }"]
    else:
        # 겹침(10단계): 블록 kb 의 정수텐서곱을 띄운 뒤에 블록 kb − 1 의 끝 계산을 한다 — 텐서 파이프와 끝 계산(변환 · 곱해더하기)이 같은
        # 워프 안에서 겹친다. 합 s 는 두 벌(0 · 1), 2^(E−13) 과 척도도 두 벌 — 블록을 둘씩 풀어 벌을 번갈아 쓴다. 값은 같다(블록마다의 식이 그대로).
        assert 자리수 == 2 and 둘자리길 == "cvt"
        assert "Pd접기" not in 변형, "겹침 판의 끝 계산은 Pd 접기의 곱을 벌마다 두지 않는다(11단계에서 값이 틀림을 확인) — 함께 쓰지 않는다"
        L += [f"    중간정수 s{p}{n}_{j}_{m}_{c} = 0." for p in (0, 1) for n in N for j in J for m in M for c in range(4)]
        L += [f"    짧은실수 Pp{p}{m}_{h} = 영." for p in (0, 1) for m in M for h in H]
        L += [f"    짧은실수 dd{p}{n}_{e} = 영." for p in (0, 1) for n in N for e in range(2)]

        def 블록곱(kb, p, ind):
            o = 블록앞(kb, ind)
            o += [f"{ind}Pp{p}{m}_{h} = P{m}_{h}." for m in M for h in H]
            for n in N:
                o += 열적재(n, ind) + [f"{ind}dd{p}{n}_{e} = d{e}." for e in range(2)] + 곱(n, ind, str(p))
            return o

        def 블록끝(p, ind):
            o = []
            for n in N:
                o += 끝계산(n, ind, str(p), f"Pp{p}", f"dd{p}{n}_")
            return o
        L += ["    {"] + 블록곱("0", 0, "        ") + 버퍼돌리기("        ") + ["    }"]
        L.append("    반복 (정수 kb = 1: kb < 블록수: kb += 2) {")
        I = "        "
        L += 블록곱("kb", 1, I) + 블록끝(0, I) + 버퍼돌리기(I)
        L += [f"{I}kb + 1 < 블록수이면 {{"]
        L += 블록곱("kb + 1", 0, I + "    ") + 블록끝(1, I + "    ") + 버퍼돌리기(I + "    ")
        L += [f"{I}}}", "    }"]
        L += ["    블록수 % 2 == 0이면 {"] + 블록끝(1, "        ") + ["    }", "    아니면 {"] + 블록끝(0, "        ") + ["    }"]
    L += 정수타일끝(epi, M, N, WR, WC)
    L.append("}")
    return L


def 정수타일끝(epi, M, N, WR, WC):
    """정수 타일 판의 끝손질 — 스레드의 칸은 행 2·MT 개 × 열 2·NT 개. 쓰는 자리를 행 부분과 열 부분으로 나눠 행마다 · 열마다
    한 번씩 구해 두고, 칸마다 더하기 하나로 쓴다(값은 끝() 과 같다). _KV 의 열은 q · 키 · 값 셋 중 하나(종류)."""
    R = [(m, h) for m in M for h in range(2)]
    C = [(n, e) for n in N for e in range(2)]
    L = ["    짧은실수 v = 0 으로 짧은실수.", "    짧은실수 u = v.", "    짧은실수 th = v."]
    L += [f"    정수 행{m}_{h} = 행0 + wm * {WR} + {16 * m + 8 * h} + g." for m, h in R]
    L += [f"    정수 열{n}_{e} = 열0 + wn * {WC} + {8 * n + e} + t * 2." for n, e in C]
    L += [f"    짧은실수 치{n}_{e} = v." for n, e in C]
    L += [f"    열{n}_{e} < 열수이면 {{ 치{n}_{e} = 치우침[열{n}_{e}]. }}" for n, e in C]
    if epi == "_KV":
        L += ["    정수 자리 = 0.", "    정수 자리위 = 0.", "    정수 머리걸음 = 64 * 최대길이."]
        for m, h in R:
            L += 자리두기(f"행{m}_{h}", "    ")
            L += [f"    정수 rq{m}_{h} = 행{m}_{h} * {너비}.",
                  f"    정수 rk{m}_{h} = 자리 + (자리위 >> 6) * 4096 + (자리위 & 63).",
                  f"    정수 rv{m}_{h} = 자리 + 자리위 * 64."]
        for n, e in C:
            x = f"열{n}_{e}"
            L += [f"    정수 종{n}_{e} = 0.", f"    정수 부{n}_{e} = {x}.",
                  f"    ({x} >= {너비} 그리고 {x} < {2 * 너비})이면 {{ 종{n}_{e} = 1. 부{n}_{e} = (({x} - {너비}) >> 6) * 머리걸음 + (({x} - {너비}) & 63) * 64. }}",
                  f"    {x} >= {2 * 너비}이면 {{ 종{n}_{e} = 2. 부{n}_{e} = (({x} - {2 * 너비}) >> 6) * 머리걸음 + (({x} - {2 * 너비}) & 63). }}"]
    elif epi == "_겔루정수":
        return L + 겔루정수끝(M, N, WC)
    elif epi == "_KV정수":
        return L + KV정수끝(M, N, WC)
    else:
        L += [f"    정수 줄{m}_{h} = 행{m}_{h} * 열수." for m, h in R]
    for m in M:
        for n in N:
            for c in range(4):
                h, e = c >> 1, c & 1
                r, k = f"{m}_{h}", f"{n}_{e}"
                L += [f"    (행{r} < 행수 그리고 열{k} < 열수)이면 {{", f"        v = y{m}_{n}_{c} + 치{k}."]
                if epi == "_KV":
                    L += [f"        종{k} == 0이면 {{ 출력[rq{r} + 부{k}] = v. }}",
                          f"        아니면 종{k} == 1이면 {{ 키칸[rk{r} + 부{k}] = {좁힘('v')}. }}",
                          f"        아니면 {{ 값칸[rv{r} + 부{k}] = {좁힘('v')}. }}"]
                else:
                    L += 끝(epi, "v", f"행{r}", f"열{k}", "", "        ", 칸=f"줄{r} + 열{k}")
                L.append("    }")
    return L


def 겔루정수끝(M, N, WC):
    """_겔루정수: GELU(끝()의 _겔루 와 같은 식) 값을 다음 행렬곱(깊이 = 이 열수)의 네 자리로 바로 — 정수로와 같은 바꾸기(블록 =
    열 32 개 = 워프의 열 조각 넷). 행과 블록마다: 레인의 여덟 칸(열 8n' + 2t + e)의 |값| 최댓값을 같은 무리(t)의 레인 넷에서
    모으고(셔플 둘 + 받기), 지수 · 네 자리. 자리는 워프마다 판에 모은다 — (행 조각, 블록) 하나가 [자리 4][행 16][32 바이트] =
    2 KB, 레인은 이웃한 두 칸을 16 비트 하나로(낱말 2n' + t/2 의 아래 · 위 반쪽 — 정수로의 [0 4 1 5 2 6 3 7] 차례). 그다음 워프가
    16 바이트씩 읽어 전역에 16 바이트씩 쓴다(행마다 32 바이트가 한 번에 — 흩어진 16 비트 쓰기보다 L2 를 덜 쓴다). 정보는 t = 0
    레인이. 열수는 블록의 열 수(그리고 16)로 나뉘어야 한다(넘치는 열이 없다). 판은 고리가 끝난 뒤에만 쓴다(먼저 동기화)."""
    L = ["    짧은정수 참조 판s = 판 으로 짧은정수 참조.",
         "    짧은실수 참조 다음넓 = 다음자리 으로 짧은실수 참조.",
         "    정수 열16 = 열수 / 16.",
         f"    정수 wb = (tid / 32) * {128 * 자리수}.",
         "    동기화()."]
    # 넘치는 행(행수 밖 — 정보가 쓰이지 않은 칸이라 y 가 쓰레기)은 y 를 0 으로(쓰지 않는 행 — 범위 검사가 켜지지 않게). 행 조각의
    # 반쪽마다 한 번 — 아래의 GELU · 바꾸기는 갈림 없이 이어져 칸끼리 겹쳐 돈다
    for m in M:
        for h in range(2):
            L.append(f"    행{m}_{h} >= 행수이면 {{ " + " ".join(f"y{m}_{n}_{2 * h + e} = 0 으로 짧은실수." for n in N for e in range(2)) + " }")
    for m in M:
        for q in range(WC // 32):
            L += ["    {", f"        정수 블록열 = 열0 + wn * {WC} + {32 * q}."]
            for h in range(2):
                r = f"행{m}_{h}"
                L.append("        {")
                for n in range(4):
                    for e in range(2):
                        i, nn, c = 2 * n + e, 4 * q + n, 2 * h + e
                        L += [f"            짧은실수 v{i} = y{m}_{nn}_{c} + 치{nn}_{e}.",
                              f"            u = 0.7978845608 * (v{i} + 0.044715 * v{i} * v{i} * v{i}).",
                              f"            th = 1.0 - 2.0 / (근사지수(2.0 * u) + 1.0).",
                              f"            짧은실수 x{i} = 0.5 * v{i} * (1.0 + th)."]
                L.append("            짧은실수 m = " + "큰쪽(" * 7 + "큰쪽(x0, 0.0 - x0)" +
                         "".join(f", 큰쪽(x{i}, 0.0 - x{i}))" for i in range(1, 8)) + ".")
                L += ["            m = 큰쪽(m, 아래에서받기(m, 2)).", "            m = 큰쪽(m, 아래에서받기(m, 1)).",
                      "            m = 레인에서받기(m, lane - t)."]
                L += 지수식("            ")
                for i in range(8):
                    L += 넷자리식(f"x{i}", "            ", str(i))
                for n in range(4):
                    pos = f"(({2 * n} + t / 2) % 4) * 2 + {n // 2}"
                    for j in range(자리수):
                        L.append(f"            판s[(wb + {j * 128} + ({8 * h} + g) * 8 + {pos}) * 2 + t % 2] = "
                                 f"((d{2 * n}{j} & 255) | ((d{2 * n + 1}{j} & 255) << 8)) 으로 짧은정수.")
                L.append(f"            ({r} < 행수 그리고 t == 0)이면 {{ 다음정보[(블록열 / 32) * 정보폭 + {r}] = " + 마법수0() + ". }")
                L.append("        }")
            # 모은 자리수 · 512 B: 조각(16 바이트) c = k·32 + lane — 자리 c / 32, 행 (c % 32) / 2, 반쪽 c % 2
            L.append("        워프동기화().")
            for k in range(자리수):
                L += [f"        {{",
                      f"            정수 조 = {32 * k} + lane.",
                      f"            정수 행안 = (조 % 32) / 2.",
                      f"            정수 출행 = 행0 + wm * {16 * len(M)} + {16 * m} + 행안.",
                      f"            정수 판자리 = wb + (조 / 32) * 128 + 행안 * 8 + (조 % 2) * 4.",
                      f"            정수 전역 = (((조 / 32) * 행수 + 출행) * 열16 + 블록열 / 16 + 조 % 2) * 4.",
                      f"            출행 < 행수이면 {{"]
                L += [f"                짧은실수 w{u} = 판[판자리 + {u}]." for u in range(4)]
                L += [f"                다음넓[전역 + {u}] = w{u}." for u in range(4)]
                L += ["            }", "        }"]
            L += ["        워프동기화().", "    }"]
    return L


# ── 9단계 — 정수 KV 계약: 어텐션도 정수 텐서 코어로 (docs/17 §7 "9단계") ──────────────────────────────────────────────────
# KV 캐시가 자리 둘 블록 정수(활성값과 같은 문장)로 남고, 점수(Q·Kᵀ)와 가중합(P·V)은 자리 짝 넷의 정확한 정수 합을 짧은실수로 반올림
# 하나. 지수는 적힌지수(다항식 — CPU 와 비트가 같다). 참조 구현: 6단계/정수계약.py 의 어텐션 · 키캐시 · 값캐시.
#   키 캐시 [문장·머리][자리 2][위치 최대길이][64 바이트] — 바이트의 차례는 활성값 배치 그대로(블록 둘 × 낱말 8, [0 4 1 5 2 6 3 7]).
#   값 캐시 [문장·머리][키 블록 최대길이/32][자리 2][d 64][낱말 8]: 낱말 2c + h 의 바이트 i 는 키 16h + 2c + i (i < 2),
#          16h + 8 + 2c + i − 2 (i ≥ 2) 의 d 번째 자리 — mma 의 B 조각(열 d, k 네 칸 = 낱말 하나)이 바로 읽는 차례.
#   지수 [문장·머리][위치][블록 2] 바이트(E + 114 — 부호 없는 바이트; 2^(E−13) 의 비트가 바이트 << 23) — 키 · 값 따로(키지수 · 값지수).
#   q 는 활성값 자릿값 배치(자릿값q [자리 2][행][너비], 정보q [블록 너비/32][정보폭] — M_0).
# 여기의 모든 함수는 자리수 == 2 · KV == "정수" 에서만 쓰인다 — 이전 모듈의 소스는 바이트까지 그대로다.
지수 = "근사지수"           # 접기 · 조각접기 · 생성메가의 지수 함수 — 정수 KV 판은 "적힌지수"(source 가 정한다)
지수상수 = {"log2e": "1.44269502162933349609375", "C1": "0.693359375", "C2": "0.000212194441701285541058",
         "c5": "0.000198756912141107022762", "c4": "0.001398199936375021934509", "c3": "0.008333452045917510986328",
         "c2": "0.041665796190500259399414", "c1": "0.166666656732559204101562", "c0": "0.5",
         "밑": "-88.0", "끝": "-87.3000030517578125"}       # 짧은실수로 정확한 십진수(정수계약.py 와 같은 글자)
빼기둘 = 197132288                                            # 자리 둘: 2^(E−13) 의 비트 = M_0 − 빼기둘
어텐션변형 = frozenset()      # 정수어텐션의 시간 나누기용 변형(값이 달라진다 — 재는 데만): "PV없음" · "점수없음" · "근사지수" · "읽기둘" · "읽기정수" · "지수없음" · "e자리없음" · "접기없음"
타일변형 = frozenset()        # 정수타일선형의 시간 나누기용 변형(값이 달라진다 — 재는 데만): "장벽없음"(블록마다의 동기화를 뺀다) · "기다림없음"(비동기 기다림을 뺀다) · "끝없음"(끝 계산을 뺀다)
타일기본 = frozenset({"섞기", "Pd접기"})  # 11단계 새 길(타일읽기 "행렬")의 기본 변형 — 값과 상관없음(번갈아 재서 고름)
타일읽기 = "행렬"             # 11단계: 정수 KV 모듈의 타일 — "행렬"은 A 를 ldmatrix 로(B 는 π 차례로, 척도는 반실수로 미리), "짝"은 10단계까지의 8 바이트 짝 읽기(재는 데만)
                            # "엇갈림"(값은 같다): 열 조각 n + 1 의 mma 를 띄운 뒤에 열 조각 n 의 끝 계산 — 같은 워프 안에서 텐서 파이프와 끝 계산이 겹친다
                            # "Pd접기"(값은 같다): 2^(E−13) · d 를 (행 조각, 열) 마다 미리 곱해 두어(2 의 거듭제곱 곱이라 정확) 칸마다 곱 하나를 뺀다


def 적힌지수식(dst, x, ind, 접):
    """dst = 적힌지수(x) — docs/17 9단계 2: n = 가까운정수(max(x, −88) · log₂e) (정확한 곱을 마법수 1.5·2²³ 를 더하는 곱해더하기로 반올림 — 범위
    검사가 붙는 변환 없이), r = x − n·C₁ + n·C₂, y = 다항식(r)(곱해더하기 사슬), y = y·r² + r, y = y + 1, 결과 = y · 2ⁿ (지수 비트에 n 을 더한다),
    x < −87.3 이면 0. 모든 연산이 IEEE 짧은실수 — 정수계약.적힌지수와 비트가 같다."""
    k = 지수상수
    return [f"{ind}짧은실수 지x{접} = {x}.",
            f"{ind}짧은실수 지c{접} = 큰쪽(지x{접}, {k['밑']}).",
            f"{ind}짧은실수 지m{접} = 곱해더하기(지c{접}, {k['log2e']}, 12582912.0).",
            f"{ind}중간정수 지n{접} = 실수비트(지m{접}) - 1262485504.",
            f"{ind}짧은실수 지f{접} = 지m{접} - 12582912.0.",
            f"{ind}짧은실수 지r{접} = 곱해더하기(지f{접}, -{k['C1']}, 지c{접}).",
            f"{ind}지r{접} = 곱해더하기(지f{접}, {k['C2']}, 지r{접}).",
            f"{ind}짧은실수 지y{접} = 곱해더하기({k['c5']}, 지r{접}, {k['c4']}).",
            f"{ind}지y{접} = 곱해더하기(지y{접}, 지r{접}, {k['c3']}).",
            f"{ind}지y{접} = 곱해더하기(지y{접}, 지r{접}, {k['c2']}).",
            f"{ind}지y{접} = 곱해더하기(지y{접}, 지r{접}, {k['c1']}).",
            f"{ind}지y{접} = 곱해더하기(지y{접}, 지r{접}, {k['c0']}).",
            f"{ind}지y{접} = 곱해더하기(지y{접}, 지r{접} * 지r{접}, 지r{접}).",
            f"{ind}지y{접} = 지y{접} + 1.0.",
            f"{ind}{dst} = 비트실수(실수비트(지y{접}) + (지n{접} << 23)).",
            f"{ind}지x{접} < {k['끝']}이면 {{ {dst} = 0 으로 짧은실수. }}"]


def 지수줄(dst, x, ind, 접=""):
    """dst = 지수(x) 의 줄들 — 근사지수(이전 모듈 — 한 줄 그대로) 또는 적힌지수(정수 KV 판)."""
    if 지수 == "근사지수":
        return [f"{ind}{dst} = 근사지수({x})."]
    return 적힌지수식(dst, x, ind, 접)


def 정수곱읽기(dst, hh, m, ll, ind, 접):
    """자리 짝 넷의 정확한 합 2¹⁶·S₁₁ + 2⁸·(S₁₀ + S₀₁) + S₀₀ 을 짧은실수로 반올림 하나 — 짧은실수만으로: a = S₁₁, b = S_m (정확히 변환),
    hi = 곱해더하기(a, 256, b) = RN(T), z = hi − 256a (FastTwoSum — 정확), err = b − z = T − hi (정확), dst = 곱해더하기(hi, 256, 곱해더하기(err, 256, S₀₀))
    — 안쪽은 정확(< 2²¹), 바깥이 256·T + S₀₀ 의 반올림 하나. (범위 검사가 붙는 실수 → 정수 변환을 쓰지 않는다.)"""
    if "읽기둘" in 어텐션변형:
        return [f"{ind}{dst} = 곱해더하기(({hh} * 256 + {m}) 으로 짧은실수, 256.0, {ll} 으로 짧은실수)."]
    if "읽기정수" in 어텐션변형:       # 같은 값의 다른 길: S_m 을 256 으로 나눠 A = S₁₁ + ⌊S_m/256⌋ (< 2²⁰), B = (S_m mod 256)·256 + S₀₀ (< 2²¹) — 둘 다 정확한 짧은실수
        return [f"{ind}{dst} = 곱해더하기(({hh} + ({m} >> 8)) 으로 짧은실수, 65536.0, ((({m}) & 255) * 256 + {ll}) 으로 짧은실수)."]
    return [f"{ind}짧은실수 a{접} = {hh} 으로 짧은실수.",
            f"{ind}짧은실수 b{접} = {m} 으로 짧은실수.",
            f"{ind}짧은실수 hi{접} = 곱해더하기(a{접}, 256.0, b{접}).",
            f"{ind}짧은실수 z{접} = 곱해더하기(a{접}, -256.0, hi{접}).",
            f"{ind}{dst} = 곱해더하기(hi{접}, 256.0, 곱해더하기(b{접} - z{접}, 256.0, {ll} 으로 짧은실수))."]


def 낱말위치(w):
    """블록의 낱말 w(0 … 7 — 칸 4w … 4w+3)가 놓이는 자리 — [0 4 1 5 2 6 3 7] 차례 (식)."""
    return f"(({w}) % 4) * 2 + ({w}) / 4"


def 정수KV선언():
    """정수 KV 판의 커널 매개변수(공통 부분) — 캐시 넷과 길이."""
    return "중간정수 참조 키칸과 중간정수 참조 값칸과 부호없는 작은정수 참조 키지수와 부호없는 작은정수 참조 값지수와"


def KV정수로():
    """c_attn 의 출력 [행][3·너비](짧은실수 — q · k · v)를 정수 KV 계약으로: q 는 자릿값q · 정보q(활성값 배치, 깊이 너비), k 는 키 캐시 +
    키지수, v 는 값 캐시 + 값지수. 정수로와 같은 바꾸기(워프 하나가 블록 넷 — 레인 여덟이 블록 하나). 격자: ((3·너비/32 + 31)/32, 행수).
    행의 위치 = 위치시작 + 행 % 묶음안행수, 문장 = 행 / 묶음안행수."""
    L = ["(* 정수 KV 계약 — c_attn 의 q · k · v 행을 자리 둘 · 지수로: q 는 자릿값q, 키 · 값은 캐시에. 커널생성.py 의 설명 *)",
         f"[짧은실수 참조 입력에서 중간정수 참조 자릿값q에 중간정수 참조 정보q에 {정수KV선언()} 정수 행수로 정수 묶음안행수로 "
         "정수 위치시작으로 정수 최대길이로 KV정수로]는 {",
         "    정수 tid = 블록안가로().",
         "    정수 lane = tid % 32.",
         "    정수 r = 블록세로().",
         f"    정수 블록수 = {3 * 너비 // 32}.",
         "    정수 정보폭 = (행수 + 63) / 64 * 64.",
         "    정수 b0 = 블록가로() * 32 + (tid / 32) * 4 + lane / 8.",
         "    정수 b = b0.",
         "    b >= 블록수이면 { b = 블록수 - 1. }",
         f"    정수 xa = r * {3 * 너비} + b * 32 + (lane % 8) * 4.",
         "    정수 문장 = r / 묶음안행수.",
         "    정수 위치 = 위치시작 + r % 묶음안행수.",
         f"    정수 머리바탕 = 문장 * {머리수} + (b % {너비 // 32}) / 2.",
         f"    정수 bb = (b % {너비 // 32}) % 2.",
         "    작은정수 참조 값바이트 = 값칸 으로 작은정수 참조."]
    L += ["    중간정수 M0 = 0."]
    L += 블록바꾸기몸(lambda i: f"입력[xa + {i}]", lambda j: f"정수 자{j} = 0. 자{j}",
                    lambda v: f"M0 = {v}.", "    ")
    L += [f"    정수 pos = {낱말위치('lane % 8')}.",
          "    b0 < 블록수이면 {",
          f"        b < {너비 // 32}이면 {{"]
    L += [f"            자릿값q[({j} * 행수 + r) * {너비 // 4} + b * 8 + pos] = 자{j}." for j in range(2)]
    L += ["            lane % 8 == 0이면 { 정보q[b * 정보폭 + r] = M0. }",
          "        }",
          f"        아니면 b < {2 * 너비 // 32}이면 {{"]
    L += [f"            키칸[(머리바탕 * 2 + {j}) * 최대길이 * 16 + 위치 * 16 + bb * 8 + pos] = 자{j}." for j in range(2)]
    L += ["            lane % 8 == 0이면 { 키지수[(머리바탕 * 최대길이 + 위치) * 2 + bb] = (E + 114) 으로 부호없는 작은정수. }",
          "        }",
          "        아니면 {",
          "            정수 r32 = 위치 % 32.",
          "            정수 r16 = r32 % 16.",
          "            정수 낱말 = ((r16 % 8) / 2) * 2 + r32 / 16.",
          "            정수 바이트 = (r16 / 8) * 2 + r16 % 2.",
          "            정수 d0 = bb * 32 + (lane % 8) * 4.",
          "            정수 값바탕 = ((머리바탕 * (최대길이 / 32) + 위치 / 32) * 2) * 2048."]
    for j in range(2):
        for i in range(4):
            L.append(f"            값바이트[값바탕 + {j} * 2048 + (d0 + {i}) * 32 + 낱말 * 4 + 바이트] = d{i}{j} 으로 작은정수.")
    L += ["            lane % 8 == 0이면 { 값지수[(머리바탕 * 최대길이 + 위치) * 2 + bb] = (E + 114) 으로 부호없는 작은정수. }",
          "        }",
          "    }",
          "}"]
    return L


어텐션질의수 = 64      # 정수어텐션의 블록이 맡는 질의 수(워프마다 16 — 64 면 워프 넷, SM 에 블록 둘). 128(워프 여덟, SM 에 블록 하나 — L2 읽기는
                    # 반)은 번갈아 재서 5~8% 느렸다(small 1024 73 → 77 µs, XL 1024 147 → 160, small 4096 766 → 849)


def 정수어텐션(질의수=None):
    """프롬프트 처리의 어텐션 — 정수 KV 계약(docs/17 9단계): 블록 하나(128 스레드 = 워프 넷)가 (머리, 한 문장의 질의 64 개 — 워프마다 16).
    키 조각(위치 64 개)마다: 키 · 값 자리와 지수를 비동기복사로 판에(두 조각 겹쳐), 점수는 m16n8k32 정수텐서곱 넷(자리 짝 넷)의 정확한
    합을 정수곱읽기로 짧은실수에, 최댓값 · 적힌지수 · 2⁻²³ 눈금의 정수 합 l · e′ 의 자리 둘 · 가중합(정수텐서곱) · 접기. 출력 O / L 은 c_proj 의
    자리 둘 · 정보로 바로(흐름어텐션정수와 같은 자리).
    레인 ℓ = 4g + t: 점수 조각의 D[g][2t], D[g][2t+1], D[g+8][2t], D[g+8][2t+1] — 질의 행 g · g+8 (워프 안), 키 8n + 2t, 8n + 2t + 1.
    판(낱말): 조각마다 키 [자리 2][키 64][16] 0, 값 [키 블록 2][자리 2][d 64][8] 2048, 키 지수 4096(32 낱말), 값 지수 4128 — 한 조각 4160
    낱말, 둘을 번갈아. 키의 16 바이트 조각 q 는 (q ^ (키 & 2)) 자리에(뱅크가 겹치지 않게). 격자: (머리, 문장 · 질의 조각) — 흐름어텐션과 같다."""
    KS, VS, EK, EV, PK, ST = 0, 2048, 4096, 4128, 4160, 4416
    세블록 = "세블록" in 어텐션변형                      # 판 33 KB(지수는 바이트로) · SM 에 블록 셋(레지스터 168 — 실험)
    if 세블록:
        ST = 4160
    Q = 어텐션질의수 if 질의수 is None else 질의수
    T = Q * 2                                          # 스레드 수 — 워프마다 질의 16
    이름 = "정수어텐션"
    L = ["(* 정수 KV 계약의 프롬프트 어텐션 — 블록 하나가 (머리, 질의 64 개), 워프마다 16. 순서 약속은 커널생성.py 의 설명 *)",
         f"(* 실행한도 {이름} {T} {3 if 세블록 else 256 // T} *)",
         f"[중간정수 참조 자릿값q에서 중간정수 참조 정보q와 {정수KV선언()} 중간정수 참조 정보와 중간정수 참조 자릿값에 정수 행수로 "
         f"정수 묶음안행수로 정수 위치시작으로 정수 최대길이로 {이름}]는 {{",
         "    정수 tid = 블록안가로().",
         "    정수 머리 = 블록가로().",
         f"    정수 질조각수 = (묶음안행수 + {Q - 1}) / {Q}.",
         "    정수 문장 = 블록세로() / 질조각수.",
         f"    정수 r0 = (질조각수 - 1 - 블록세로() % 질조각수) * {Q}.",
         f"    정수 끝r = r0 + {Q - 1}.",
         "    끝r >= 묶음안행수이면 { 끝r = 묶음안행수 - 1. }",
         "    정수 p0 = 위치시작 + r0.",
         "    정수 끝조각 = (위치시작 + 끝r) / 64.",
         "    정수 행바탕 = 문장 * 묶음안행수.",
         "    정수 정보폭 = (행수 + 63) / 64 * 64.",
         f"    정수 머리바탕 = 문장 * {머리수} + 머리.",
         "    정수 키바탕 = 머리바탕 * 2 * 최대길이 * 16.",
         "    정수 값바탕 = 머리바탕 * (최대길이 / 32) * 1024.",
         "    정수 지수바이트 = 머리바탕 * 최대길이 * 2.",
         "    정수 lane = tid % 32.",
         "    정수 g = lane / 4.",
         "    정수 t = lane % 4.",
         "    정수 w = tid / 32.",
         f"    짧은실수 참조 판 = 공유판{33 if 세블록 else 36}().",
         "    중간정수 참조 판i = 판 으로 중간정수 참조.",
         "    부호없는 작은정수 참조 판b = 판 으로 부호없는 작은정수 참조.",
         "    짧은실수 참조 키넓 = 키칸 으로 짧은실수 참조.",
         "    짧은실수 참조 값넓 = 값칸 으로 짧은실수 참조.",
         "    짧은실수 참조 키지넓 = 키지수 으로 짧은실수 참조.",
         "    짧은실수 참조 값지넓 = 값지수 으로 짧은실수 참조.",
         "    중간정수 영i = 0.",
         "    짧은실수 영 = 0 으로 짧은실수."]
    # 질의 행 둘(g, g+8)의 자리 둘 A 조각과 2^(E−13)
    for h in range(2):
        L += [f"    정수 qr{h} = r0 + w * 16 + g + {8 * h}.",
              f"    qr{h} > 끝r이면 {{ qr{h} = 끝r. }}",
              f"    정수 pq{h} = 위치시작 + qr{h}."]
        for j in range(2):
            for b in range(2):
                L += [f"    정수 qo{j}_{b}_{h} = ({j} * 행수 + 행바탕 + qr{h}) * {너비 // 4} + (머리 * 2 + {b}) * 8 + t * 2.",
                      f"    중간정수 qa{j}_{b}_{h}_0 = 자릿값q[qo{j}_{b}_{h}].",
                      f"    중간정수 qa{j}_{b}_{h}_1 = 자릿값q[qo{j}_{b}_{h} + 1]."]
        for b in range(2):
            L.append(f"    짧은실수 pqs{b}_{h} = 비트실수(정보q[(머리 * 2 + {b}) * 정보폭 + 행바탕 + qr{h}] - {빼기둘 + 3 * 2 ** 23}).")   # 2^(E−13) · 0.125
    # 조각 올리기: 키 16 바이트 조각 512 개(자리 · 키 · 조각 넷), 값 512 개(블록 · 자리 · d · 반쪽), 지수 8 + 8 개
    for u in range(512 // T):
        c = f"(tid + {T * u})"
        L += [f"    정수 kj{u} = {c} / 256.", f"    정수 kk{u} = ({c} % 256) / 4.", f"    정수 kq{u} = {c} % 4.",
              f"    정수 k저장{u} = {KS} + kj{u} * 1024 + kk{u} * 16 + (kq{u} ^ (kk{u} & 2)) * 4.",
              f"    정수 k원본{u} = 키바탕 + kj{u} * 최대길이 * 16 + kk{u} * 16 + kq{u} * 4.",
              f"    정수 v저장{u} = {VS} + ({c} / 256) * 1024 + (({c} % 256) / 128) * 512 + (({c} % 128) / 2) * 8 + ({c} % 2) * 4.",
              f"    정수 v원본{u} = 값바탕 + ({c} / 256) * 1024 + (({c} % 256) / 128) * 512 + (({c} % 128) / 2) * 8 + ({c} % 2) * 4."]

    def 올리기(조각, 버퍼, ind):
        o = [f"{ind}정수 올바탕 = ({버퍼}) * {ST}.", f"{ind}정수 kt = ({조각}) * 64."]
        o += [f"{ind}비동기복사16(판 에, 올바탕 + k저장{u} 를, 키넓 에서, k원본{u} + kt * 16 로)." for u in range(512 // T)]
        o += [f"{ind}비동기복사16(판 에, 올바탕 + v저장{u} 를, 값넓 에서, v원본{u} + ({조각}) * 2048 로)." for u in range(512 // T)]
        if 세블록:
            o += [f"{ind}tid < 8이면 {{ 비동기복사16(판 에, 올바탕 + {EK} + tid * 4 를, 키지넓 에서, 지수바이트 / 4 + ({조각}) * 32 + tid * 4 로). }}",
                  f"{ind}(tid >= 8 그리고 tid < 16)이면 {{ 비동기복사16(판 에, 올바탕 + {EV} + (tid - 8) * 4 를, 값지넓 에서, 지수바이트 / 4 + ({조각}) * 32 + (tid - 8) * 4 로). }}"]
        return o
    # 조각의 지수 바이트(키 128 · 값 128)를 2^(E−13) 짧은실수 256 개로 판에(스레드마다 둘) — 다음 조각의 것을 이번 조각의 끝에서(비동기복사가 끝난 뒤)
    def 지수풀기(조각, 버퍼, ind):
        if 세블록:
            return []
        NP = 256 // T                                   # 스레드마다 지수 바이트 → 2^(E−13) 몇 개(256 = 키 128 + 값 128)
        o = [f"{ind}정수 풀바탕 = ({버퍼}) * {ST} + {PK} + tid * {NP}.", f"{ind}정수 지바탕 = 지수바이트 + ({조각}) * 128 + (tid % {128 // NP}) * {NP}."]
        o += [f"{ind}tid < {128 // NP}이면 {{ " + " ".join(f"판[풀바탕 + {i}] = 비트실수((키지수[지바탕 + {i}] 으로 중간정수) << 23)." for i in range(NP)) + " }",
              f"{ind}아니면 {{ " + " ".join(f"판[풀바탕 + {i}] = 비트실수((값지수[지바탕 + {i}] 으로 중간정수) << 23)." for i in range(NP)) + " }"]
        return o
    L += ["    {"] + 올리기("0", "0", "        ") + ["    }", "    비동기묶기().", "    {"] + 지수풀기("0", "0", "        ") + ["    }"]
    L += [f"    짧은실수 M{h} = 영." for h in range(2)] + [f"    짧은실수 L{h} = 영." for h in range(2)]
    L += [f"    짧은실수 O{dt}_{c} = 영." for dt in range(8) for c in range(4)]
    L += ["    정수 버퍼 = 0.",
          "    반복 (정수 조각 = 0: 조각 <= 끝조각: 조각 += 1) {",
          "        비동기기다리기(0).",
          "        동기화().",
          "        조각 < 끝조각이면 {"]
    L += 올리기("조각 + 1", "1 - 버퍼", "            ")
    L += ["        }",
          "        비동기묶기().",
          f"        정수 SB = 버퍼 * {ST}.",
          "        정수 tb = 조각 * 64."]
    I = "        "
    # ── 점수: 키 조각(8 개) n 마다 블록 b 의 자리 짝 넷 → u → s
    for n in range(8):
        L += [f"{I}정수 kr{n} = {8 * n} + g."]
        for b in range(2):
            L += [f"{I}정수 kw{n}_{b} = SB + {KS} + kr{n} * 16 + (({2 * b} + t / 2) ^ (kr{n} & 2)) * 4 + (t % 2) * 2."]
            for j in range(2):
                L += [f"{I}중간정수 kb{n}_{b}_{j}_0 = 판i[kw{n}_{b} + {j * 1024}].",
                      f"{I}중간정수 kb{n}_{b}_{j}_1 = 판i[kw{n}_{b} + {j * 1024 + 1}]."]
        # 키 8n + 2t, 8n + 2t + 1 의 블록 지수 → 2^(E−13)
        for e in range(2):
            for b in range(2):
                L.append(f"{I}짧은실수 pk{n}_{e}_{b} = 비트실수((판b[(SB + {EK}) * 4 + ({8 * n} + t * 2 + {e}) * 2 + {b}] 으로 중간정수) << 23)." if 세블록 else
                         f"{I}짧은실수 pk{n}_{e}_{b} = 판[SB + {PK} + ({8 * n} + t * 2 + {e}) * 2 + {b}].")
        L += [f"{I}짧은실수 s{n}_{c} = 영." for c in range(4)]
        for b in range(2):
            A = lambda j: f"qa{j}_{b}_0_0, qa{j}_{b}_1_0, qa{j}_{b}_0_1, qa{j}_{b}_1_1"
            B = lambda j: f"kb{n}_{b}_{j}_0, kb{n}_{b}_{j}_1"
            J = I + "    "
            L += [f"{I}{{"]
            if "점수없음" in 어텐션변형:
                L += [f"{J}짧은실수 u{c} = (kb{n}_{b}_0_0 + qa0_{b}_0_0) 으로 짧은실수." for c in range(4)]
            else:
                L += [f"{J}중간정수 hh{c} = 정수텐서곱({c}, {A(1)}, {B(1)}, 영i, 영i, 영i, 영i)." for c in range(4)]
                L += [f"{J}중간정수 sm{c} = 정수텐서곱({c}, {A(1)}, {B(0)}, 영i, 영i, 영i, 영i)." for c in range(4)]
                L += [f"{J}중간정수 smb{c} = 정수텐서곱({c}, {A(0)}, {B(1)}, sm0, sm1, sm2, sm3)." for c in range(4)]
                L += [f"{J}중간정수 ll{c} = 정수텐서곱({c}, {A(0)}, {B(0)}, 영i, 영i, 영i, 영i)." for c in range(4)]
                for c in range(4):
                    L += 정수곱읽기(f"짧은실수 u{c}", f"hh{c}", f"smb{c}", f"ll{c}", J, f"{c}")
            for c in range(4):
                h, e = c >> 1, c & 1
                if b == 0:
                    L.append(f"{J}s{n}_{c} = (u{c} * pqs0_{h}) * pk{n}_{e}_0.")
                else:
                    L.append(f"{J}s{n}_{c} = 곱해더하기(u{c} * pqs1_{h}, pk{n}_{e}_1, s{n}_{c}).")
            L += [f"{I}}}"]
    L.append(f"{I}tb + 63 > p0이면 {{")                   # 조각이 질의들의 위치에 걸칠 때만 가린다(블록의 모든 행이 p0 이상)
    for n in range(8):
        for c in range(4):
            h, e = c >> 1, c & 1
            L.append(f"{I}    tb + {8 * n} + t * 2 + {e} > pq{h}이면 {{ s{n}_{c} = -3.0e38. }}")
    L.append(f"{I}}}")
    # ── 조각의 최댓값(행마다 — 레인 넷의 셔플) · 적힌지수 · 합
    for h in range(2):
        xs = [f"s{n}_{c}" for n in range(8) for c in (2 * h, 2 * h + 1)]
        expr = xs[0]
        for x in xs[1:]:
            expr = f"큰쪽({expr}, {x})"
        L += [f"{I}짧은실수 mx{h} = {expr}.",
              f"{I}mx{h} = 큰쪽(mx{h}, 레인에서받기(mx{h}, lane ^ 1)).",
              f"{I}mx{h} = 큰쪽(mx{h}, 레인에서받기(mx{h}, lane ^ 2)).",
              f"{I}정수 ml{h} = 0."]
    for n in range(8):
        for c in range(4):
            h = c >> 1
            L += ([f"{I}짧은실수 e{n}_{c} = 근사지수(s{n}_{c} - mx{h})."] if "근사지수" in 어텐션변형 else
                  [f"{I}짧은실수 e{n}_{c} = s{n}_{c} - mx{h}."] if "지수없음" in 어텐션변형 else
                  적힌지수식(f"짧은실수 e{n}_{c}", f"s{n}_{c} - mx{h}", I, f"e{n}_{c}"))
            L.append(f"{I}ml{h} = ml{h} + ((실수비트(곱해더하기(e{n}_{c}, 8388608.0, 8388608.0)) - 1258291200) 으로 정수).")
    for h in range(2):
        L += [f"{I}ml{h} = ml{h} + 정수레인에서받기(ml{h}, lane ^ 1).",
              f"{I}ml{h} = ml{h} + 정수레인에서받기(ml{h}, lane ^ 2).",
              f"{I}짧은실수 l{h} = (ml{h} 으로 짧은실수) * 0.00000011920928955078125."]
    # ── e′ = e · 2^(E_v − 13) 를 값의 블록 b 마다, 키 32 개 블록 j 마다 자리 둘로 → A 조각 ea{b}_{j}_{자리}_{0..3}
    PV = "PV없음" not in 어텐션변형
    for n in range(8):
        for e in range(2):
            for b in range(2):
                L.append(f"{I}짧은실수 pv{n}_{e}_{b} = 비트실수((판b[(SB + {EV}) * 4 + ({8 * n} + t * 2 + {e}) * 2 + {b}] 으로 중간정수) << 23)." if 세블록 else
                         f"{I}짧은실수 pv{n}_{e}_{b} = 판[SB + {PK + 128} + ({8 * n} + t * 2 + {e}) * 2 + {b}].")
    L += [f"{I}짧은실수 Pe{b}_{j}_{h} = 영." for b in range(2) for j in range(2) for h in range(2)]
    L += [f"{I}중간정수 ea{b}_{j}_{자리}_{k} = 0." for b in range(2) for j in range(2) for 자리 in range(2) for k in range(4)]
    for b in (range(2) if PV and "e자리없음" not in 어텐션변형 else ()):
        for j in range(2):
            for c in range(4):
                h, e = c >> 1, c & 1
                for n in range(4 * j, 4 * j + 4):
                    L.append(f"{I}짧은실수 ep{b}_{n}_{c} = e{n}_{c} * pv{n}_{e}_{b}.")
            for h in range(2):
                xs = [f"ep{b}_{n}_{c}" for n in range(4 * j, 4 * j + 4) for c in (2 * h, 2 * h + 1)]
                expr = xs[0]
                for x in xs[1:]:
                    expr = f"큰쪽({expr}, {x})"
                L += [f"{I}{{",
                      f"{I}    짧은실수 m = {expr}.",
                      f"{I}    m = 큰쪽(m, 레인에서받기(m, lane ^ 1)).",
                      f"{I}    m = 큰쪽(m, 레인에서받기(m, lane ^ 2))."]
                L += 지수식(I + "    ")
                L.append(f"{I}    Pe{b}_{j}_{h} = 비트실수(((E + 114) << 23) 으로 중간정수).")
                for n in range(4 * j, 4 * j + 4):
                    for e in range(2):
                        c = 2 * h + e
                        L.append(f"{I}    중간정수 me{n}_{c} = 실수비트(곱해더하기(ep{b}_{n}_{c}, s, 8388736.0)) - 1258291200.")
                # A 조각: 레지스터 0 (k 4t … 4t+3) = 키 조각 4j, 4j+1 의 (2t, 2t+1); 레지스터 2 (16 + 4t …) = 조각 4j+2, 4j+3.
                # me = n + 128: 아래 바이트 = 아래 자리 + 128 (부호 비트만 뒤집으면 균형 자리), 위 바이트 = 윗자리
                for half in range(2):
                    n0, n1 = 4 * j + 2 * half, 4 * j + 2 * half + 1
                    L += [f"{I}    중간정수 p01_{half} = 바이트고르기(me{n0}_{2 * h}, me{n0}_{2 * h + 1}, 20800).",
                          f"{I}    중간정수 p23_{half} = 바이트고르기(me{n1}_{2 * h}, me{n1}_{2 * h + 1}, 20800).",
                          f"{I}    ea{b}_{j}_0_{2 * half + h} = 바이트고르기(p01_{half}, p23_{half}, 21520) ^ (-2139062144).",
                          f"{I}    ea{b}_{j}_1_{2 * half + h} = 바이트고르기(p01_{half}, p23_{half}, 30258)."]
                L.append(f"{I}}}")
    # ── 가중합: d 조각(8 개) dt 마다 키 블록 j 의 자리 짝 넷 → u_j → o = u₀·2^(E_e,0−13) + u₁·2^(E_e,1−13) (곱해더하기 하나) → 접기
    L += [f"{I}짧은실수 uo{j}_{c} = 영." for j in range(2) for c in range(4)]
    for dt in range(8):
        b = dt // 4
        if not PV:
            L += [f"{I}짧은실수 o{dt}_{c} = e{dt}_{c}." for c in range(4)]
            continue
        L.append(f"{I}정수 vw{dt} = SB + {VS} + ({8 * dt} + g) * 8 + t * 2.")
        for j in range(2):
            J = I + "    "
            L += [f"{I}{{"]
            for 자리 in range(2):
                L += [f"{J}중간정수 vb{자리}_0 = 판i[vw{dt} + {(j * 2 + 자리) * 512}].",
                      f"{J}중간정수 vb{자리}_1 = 판i[vw{dt} + {(j * 2 + 자리) * 512 + 1}]."]
            A = lambda 자리: f"ea{b}_{j}_{자리}_0, ea{b}_{j}_{자리}_1, ea{b}_{j}_{자리}_2, ea{b}_{j}_{자리}_3"
            B = lambda 자리: f"vb{자리}_0, vb{자리}_1"
            L += [f"{J}중간정수 phh{c} = 정수텐서곱({c}, {A(1)}, {B(1)}, 영i, 영i, 영i, 영i)." for c in range(4)]
            L += [f"{J}중간정수 psm{c} = 정수텐서곱({c}, {A(1)}, {B(0)}, 영i, 영i, 영i, 영i)." for c in range(4)]
            L += [f"{J}중간정수 psmb{c} = 정수텐서곱({c}, {A(0)}, {B(1)}, psm0, psm1, psm2, psm3)." for c in range(4)]
            L += [f"{J}중간정수 pll{c} = 정수텐서곱({c}, {A(0)}, {B(0)}, 영i, 영i, 영i, 영i)." for c in range(4)]
            for c in range(4):
                L += 정수곱읽기(f"uo{j}_{c}", f"phh{c}", f"psmb{c}", f"pll{c}", J, f"{c}")
            L += [f"{I}}}"]
        for c in range(4):
            h = c >> 1
            L.append(f"{I}짧은실수 o{dt}_{c} = 곱해더하기(uo1_{c}, Pe{b}_1_{h}, uo0_{c} * Pe{b}_0_{h}).")
    # ── 접기(이 조각에 유효한 키가 있는 행만 — pq ≥ tb)
    for h in (range(2) if "접기없음" not in 어텐션변형 else ()):
        L += [f"{I}pq{h} >= tb이면 {{",
              f"{I}    조각 == 0이면 {{",
              f"{I}        M{h} = mx{h}.", f"{I}        L{h} = l{h}."]
        L += [f"{I}        O{dt}_{c} = o{dt}_{c}." for dt in range(8) for c in (2 * h, 2 * h + 1)]
        L += [f"{I}    }}",
              f"{I}    아니면 {{",
              f"{I}        짧은실수 새큰 = 큰쪽(M{h}, mx{h})."]
        L += 적힌지수식("짧은실수 옛", f"M{h} - 새큰", I + "        ", f"f{h}a")
        L += 적힌지수식("짧은실수 새", f"mx{h} - 새큰", I + "        ", f"f{h}b")
        L += [f"{I}        L{h} = 곱해더하기(l{h}, 새, L{h} * 옛)."]
        L += [f"{I}        O{dt}_{c} = 곱해더하기(o{dt}_{c}, 새, O{dt}_{c} * 옛)." for dt in range(8) for c in (2 * h, 2 * h + 1)]
        L += [f"{I}        M{h} = 새큰.", f"{I}    }}", f"{I}}}"]
    L += ["        조각 < 끝조각이면 {"] + 지수풀기("조각 + 1", "1 - 버퍼", "            ") + ["        }"]
    L += ["        버퍼 = 1 - 버퍼.", "    }"]
    # ── 출력 O / L → c_proj 의 자리 둘(블록 32 칸 = d 조각 넷) · 정보(M_0): 레인 t 가 d 8dt + 2t, 2t + 1 — 이웃 레인의 두 바이트를 받아 낱말로
    for h in range(2):
        L += [f"    정수 행{h} = 행바탕 + r0 + w * 16 + g + {8 * h}.",
              f"    정수 쓰{h} = 0.", f"    r0 + w * 16 + g + {8 * h} <= 끝r이면 {{ 쓰{h} = 1. }}"]
        for b in range(2):
            L += ["    {"]
            for dt in range(4 * b, 4 * b + 4):
                for e in range(2):
                    L.append(f"        짧은실수 x{dt}_{e} = O{dt}_{2 * h + e} / L{h}.")
            xs = [f"x{dt}_{e}" for dt in range(4 * b, 4 * b + 4) for e in range(2)]
            expr = "큰쪽(" * (len(xs) - 1) + f"큰쪽({xs[0]}, 0.0 - {xs[0]})" + "".join(f", 큰쪽({x}, 0.0 - {x}))" for x in xs[1:])
            L += [f"        짧은실수 m = {expr}.",
                  "        m = 큰쪽(m, 레인에서받기(m, lane ^ 1)).",
                  "        m = 큰쪽(m, 레인에서받기(m, lane ^ 2))."]
            L += 지수식("        ")
            for dt in range(4 * b, 4 * b + 4):
                for e in range(2):
                    L += 넷자리식(f"x{dt}_{e}", "        ", f"{dt}_{e}")
            for dt in range(4 * b, 4 * b + 4):
                for j in range(2):
                    L += [f"        정수 반{dt}_{j} = ((d{dt}_0{j} & 255) | ((d{dt}_1{j} & 255) << 8)) 으로 정수.",
                          f"        정수 옆{dt}_{j} = 정수레인에서받기(반{dt}_{j}, lane + 1).",
                          f"        (쓰{h} == 1 그리고 t % 2 == 0)이면 {{ 자릿값[({j} * 행수 + 행{h}) * {너비 // 4} + (머리 * 2 + {b}) * 8 + "
                          f"{낱말위치(f'{2 * (dt - 4 * b)} + t / 2')}] = (반{dt}_{j} | (옆{dt}_{j} << 16)) 으로 중간정수. }}"]
            L += [f"        (쓰{h} == 1 그리고 t == 0)이면 {{ 정보[(머리 * 2 + {b}) * 정보폭 + 행{h}] = {마법수0()}. }}",
                  "    }"]
    L.append("}")
    return L


def 정수어텐션둘():
    """정수어텐션과 같은 값(같은 계약 · 같은 식 · 같은 차례)을 내는 다른 모양 — 10단계: 블록 하나(256 스레드 = 워프 여덟)가 (머리, 질의 64).
    질의 16 묶음(qt = 워프/2)마다 워프 둘(kh = 워프 % 2)이 키 조각의 반쪽(키 32·kh …)씩 점수를 내고(mma 32), 조각의 최댓값은 판으로 합치고,
    e′ 의 자리는 값의 블록 b 둘 다 만들어 b ≠ kh 인 것을 판에 두고 b = kh 인 것을 상대에게서 받아, 워프 kh 가 d 블록 kh(d 조각 넷)의 가중합
    (mma 32)과 접기 · 출력을 맡는다. 레지스터가 반(합 · 지수 · 자리 · 누적이 반)이라 SM 에 워프 열여섯 — 정수어텐션(워프 여덟)의 지연 사슬을
    둘로 나눈다. 판(낱말): 조각 [키 2048 | 값 2048 | 2^(E−13) 256] 4352 × 2, 최댓값 [질의 묶음 4][반쪽 2][16] 8704, 합 8832, 상대의 2^(E_e−13)
    8960, 자리 [4][2][자리 2][레지스터 4][레인 32] 9088 — 44 KB. 조각마다 동기화 셋(조각 올리기 · 최댓값 · 자리)."""
    KS, VS, PK, ST = 0, 2048, 4096, 4352
    MX, LS, PE, DG = 8704, 8832, 8960, 9088
    이름 = "정수어텐션둘"
    L = ["(* 정수 KV 계약의 프롬프트 어텐션 — 워프 여덟: 질의 16 묶음마다 키 반쪽 워프 둘, 값은 정수어텐션과 같다. 커널생성.py 의 설명 *)",
         f"(* 실행한도 {이름} 256 2 *)",
         f"[중간정수 참조 자릿값q에서 중간정수 참조 정보q와 {정수KV선언()} 중간정수 참조 정보와 중간정수 참조 자릿값에 정수 행수로 "
         f"정수 묶음안행수로 정수 위치시작으로 정수 최대길이로 {이름}]는 {{",
         "    정수 tid = 블록안가로().",
         "    정수 머리 = 블록가로().",
         "    정수 질조각수 = (묶음안행수 + 63) / 64.",
         "    정수 문장 = 블록세로() / 질조각수.",
         "    정수 r0 = (질조각수 - 1 - 블록세로() % 질조각수) * 64.",
         "    정수 끝r = r0 + 63.",
         "    끝r >= 묶음안행수이면 { 끝r = 묶음안행수 - 1. }",
         "    정수 p0 = 위치시작 + r0.",
         "    정수 끝조각 = (위치시작 + 끝r) / 64.",
         "    정수 행바탕 = 문장 * 묶음안행수.",
         "    정수 정보폭 = (행수 + 63) / 64 * 64.",
         f"    정수 머리바탕 = 문장 * {머리수} + 머리.",
         "    정수 키바탕 = 머리바탕 * 2 * 최대길이 * 16.",
         "    정수 값바탕 = 머리바탕 * (최대길이 / 32) * 1024.",
         "    정수 지수바이트 = 머리바탕 * 최대길이 * 2.",
         "    정수 lane = tid % 32.",
         "    정수 g = lane / 4.",
         "    정수 t = lane % 4.",
         "    정수 w = tid / 32.",
         "    정수 qt = w / 2.",
         "    정수 kh = w % 2.",
         "    정수 키0 = kh * 32.",
         "    정수 d0 = kh * 32.",
         f"    정수 내칸 = (qt * 2 + kh) * 16 + g.",
         f"    정수 상대칸 = (qt * 2 + 1 - kh) * 16 + g.",
         "    짧은실수 참조 판 = 공유판44().",
         "    중간정수 참조 판i = 판 으로 중간정수 참조.",
         "    짧은실수 참조 키넓 = 키칸 으로 짧은실수 참조.",
         "    짧은실수 참조 값넓 = 값칸 으로 짧은실수 참조.",
         "    중간정수 영i = 0.",
         "    짧은실수 영 = 0 으로 짧은실수."]
    for h in range(2):
        L += [f"    정수 qr{h} = r0 + qt * 16 + g + {8 * h}.",
              f"    qr{h} > 끝r이면 {{ qr{h} = 끝r. }}",
              f"    정수 pq{h} = 위치시작 + qr{h}."]
        for j in range(2):
            for b in range(2):
                L += [f"    정수 qo{j}_{b}_{h} = ({j} * 행수 + 행바탕 + qr{h}) * {너비 // 4} + (머리 * 2 + {b}) * 8 + t * 2.",
                      f"    중간정수 qa{j}_{b}_{h}_0 = 자릿값q[qo{j}_{b}_{h}].",
                      f"    중간정수 qa{j}_{b}_{h}_1 = 자릿값q[qo{j}_{b}_{h} + 1]."]
        for b in range(2):
            L.append(f"    짧은실수 pqs{b}_{h} = 비트실수(정보q[(머리 * 2 + {b}) * 정보폭 + 행바탕 + qr{h}] - {빼기둘 + 3 * 2 ** 23}).")
    for u in range(2):
        c = f"(tid + {256 * u})"
        L += [f"    정수 kj{u} = {c} / 256.", f"    정수 kk{u} = ({c} % 256) / 4.", f"    정수 kq{u} = {c} % 4.",
              f"    정수 k저장{u} = {KS} + kj{u} * 1024 + kk{u} * 16 + (kq{u} ^ (kk{u} & 2)) * 4.",
              f"    정수 k원본{u} = 키바탕 + kj{u} * 최대길이 * 16 + kk{u} * 16 + kq{u} * 4.",
              f"    정수 v저장{u} = {VS} + ({c} / 256) * 1024 + (({c} % 256) / 128) * 512 + (({c} % 128) / 2) * 8 + ({c} % 2) * 4.",
              f"    정수 v원본{u} = 값바탕 + ({c} / 256) * 1024 + (({c} % 256) / 128) * 512 + (({c} % 128) / 2) * 8 + ({c} % 2) * 4."]

    def 올리기(조각, 버퍼, ind):
        o = [f"{ind}정수 올바탕 = ({버퍼}) * {ST}.", f"{ind}정수 kt = ({조각}) * 64."]
        o += [f"{ind}비동기복사16(판 에, 올바탕 + k저장{u} 를, 키넓 에서, k원본{u} + kt * 16 로)." for u in range(2)]
        o += [f"{ind}비동기복사16(판 에, 올바탕 + v저장{u} 를, 값넓 에서, v원본{u} + ({조각}) * 2048 로)." for u in range(2)]
        return o

    def 지수풀기(조각, 버퍼, ind):
        return [f"{ind}정수 풀바탕 = ({버퍼}) * {ST} + {PK} + tid.", f"{ind}정수 지바탕 = 지수바이트 + ({조각}) * 128 + tid % 128.",
                f"{ind}tid < 128이면 {{ 판[풀바탕] = 비트실수((키지수[지바탕] 으로 중간정수) << 23). }}",
                f"{ind}아니면 {{ 판[풀바탕] = 비트실수((값지수[지바탕] 으로 중간정수) << 23). }}"]
    L += ["    {"] + 올리기("0", "0", "        ") + ["    }", "    비동기묶기().", "    {"] + 지수풀기("0", "0", "        ") + ["    }"]
    L += [f"    짧은실수 M{h} = 영." for h in range(2)] + [f"    짧은실수 L{h} = 영." for h in range(2)]
    L += [f"    짧은실수 O{i}_{c} = 영." for i in range(4) for c in range(4)]
    L += ["    정수 버퍼 = 0.",
          "    반복 (정수 조각 = 0: 조각 <= 끝조각: 조각 += 1) {",
          "        비동기기다리기(0).",
          "        동기화().",
          "        조각 < 끝조각이면 {"]
    L += 올리기("조각 + 1", "1 - 버퍼", "            ")
    L += ["        }",
          "        비동기묶기().",
          f"        정수 SB = 버퍼 * {ST}.",
          "        정수 tb = 조각 * 64."]
    I = "        "
    # ── 점수: 내 키 반쪽의 조각 넷(i) × 블록 둘(b)
    for i in range(4):
        L += [f"{I}정수 kr{i} = 키0 + {8 * i} + g."]
        for b in range(2):
            L += [f"{I}정수 kw{i}_{b} = SB + {KS} + kr{i} * 16 + (({2 * b} + t / 2) ^ (kr{i} & 2)) * 4 + (t % 2) * 2."]
            for j in range(2):
                L += [f"{I}중간정수 kb{i}_{b}_{j}_0 = 판i[kw{i}_{b} + {j * 1024}].",
                      f"{I}중간정수 kb{i}_{b}_{j}_1 = 판i[kw{i}_{b} + {j * 1024 + 1}]."]
        for e in range(2):
            for b in range(2):
                L.append(f"{I}짧은실수 pk{i}_{e}_{b} = 판[SB + {PK} + (키0 + {8 * i} + t * 2 + {e}) * 2 + {b}].")
        L += [f"{I}짧은실수 s{i}_{c} = 영." for c in range(4)]
        for b in range(2):
            A = lambda j: f"qa{j}_{b}_0_0, qa{j}_{b}_1_0, qa{j}_{b}_0_1, qa{j}_{b}_1_1"
            B = lambda j: f"kb{i}_{b}_{j}_0, kb{i}_{b}_{j}_1"
            J = I + "    "
            L += [f"{I}{{"]
            L += [f"{J}중간정수 hh{c} = 정수텐서곱({c}, {A(1)}, {B(1)}, 영i, 영i, 영i, 영i)." for c in range(4)]
            L += [f"{J}중간정수 sm{c} = 정수텐서곱({c}, {A(1)}, {B(0)}, 영i, 영i, 영i, 영i)." for c in range(4)]
            L += [f"{J}중간정수 smb{c} = 정수텐서곱({c}, {A(0)}, {B(1)}, sm0, sm1, sm2, sm3)." for c in range(4)]
            L += [f"{J}중간정수 ll{c} = 정수텐서곱({c}, {A(0)}, {B(0)}, 영i, 영i, 영i, 영i)." for c in range(4)]
            for c in range(4):
                h, e = c >> 1, c & 1
                L += 정수곱읽기(f"짧은실수 u{c}", f"hh{c}", f"smb{c}", f"ll{c}", J, f"{c}")
                if b == 0:
                    L.append(f"{J}s{i}_{c} = (u{c} * pqs0_{h}) * pk{i}_{e}_0.")
                else:
                    L.append(f"{J}s{i}_{c} = 곱해더하기(u{c} * pqs1_{h}, pk{i}_{e}_1, s{i}_{c}).")
            L += [f"{I}}}"]
    L.append(f"{I}tb + 63 > p0이면 {{")
    for i in range(4):
        for c in range(4):
            h, e = c >> 1, c & 1
            L.append(f"{I}    tb + 키0 + {8 * i} + t * 2 + {e} > pq{h}이면 {{ s{i}_{c} = -3.0e38. }}")
    L.append(f"{I}}}")
    # ── 조각의 최댓값: 내 반쪽(레인 넷의 셔플) → 판 → 상대 반쪽과 합침
    for h in range(2):
        xs = [f"s{i}_{c}" for i in range(4) for c in (2 * h, 2 * h + 1)]
        expr = xs[0]
        for x in xs[1:]:
            expr = f"큰쪽({expr}, {x})"
        L += [f"{I}짧은실수 mx{h} = {expr}.",
              f"{I}mx{h} = 큰쪽(mx{h}, 레인에서받기(mx{h}, lane ^ 1)).",
              f"{I}mx{h} = 큰쪽(mx{h}, 레인에서받기(mx{h}, lane ^ 2)).",
              f"{I}t == 0이면 {{ 판[{MX} + 내칸 + {8 * h}] = mx{h}. }}"]
    L += [f"{I}동기화()."]
    L += [f"{I}mx{h} = 큰쪽(mx{h}, 판[{MX} + 상대칸 + {8 * h}])." for h in range(2)]
    L += [f"{I}정수 ml{h} = 0." for h in range(2)]
    for i in range(4):
        for c in range(4):
            h = c >> 1
            L += 적힌지수식(f"짧은실수 e{i}_{c}", f"s{i}_{c} - mx{h}", I, f"e{i}_{c}")
            L.append(f"{I}ml{h} = ml{h} + ((실수비트(곱해더하기(e{i}_{c}, 8388608.0, 8388608.0)) - 1258291200) 으로 정수).")
    for h in range(2):
        L += [f"{I}ml{h} = ml{h} + 정수레인에서받기(ml{h}, lane ^ 1).",
              f"{I}ml{h} = ml{h} + 정수레인에서받기(ml{h}, lane ^ 2).",
              f"{I}t == 0이면 {{ 판i[{LS} + 내칸 + {8 * h}] = ml{h} 으로 중간정수. }}"]
    # ── e′ 의 자리 둘: 값의 블록 b 둘 다(내 키 블록 j = kh) — b ≠ kh 는 상대에게 판으로
    for i in range(4):
        for e in range(2):
            for b in range(2):
                L.append(f"{I}짧은실수 pv{i}_{e}_{b} = 판[SB + {PK + 128} + (키0 + {8 * i} + t * 2 + {e}) * 2 + {b}].")
    L += [f"{I}짧은실수 Pe{b}_{h} = 영." for b in range(2) for h in range(2)]
    L += [f"{I}중간정수 ea{b}_{자리}_{k} = 0." for b in range(2) for 자리 in range(2) for k in range(4)]
    for b in range(2):
        for c in range(4):
            h, e = c >> 1, c & 1
            for i in range(4):
                L.append(f"{I}짧은실수 ep{b}_{i}_{c} = e{i}_{c} * pv{i}_{e}_{b}.")
        for h in range(2):
            xs = [f"ep{b}_{i}_{c}" for i in range(4) for c in (2 * h, 2 * h + 1)]
            expr = xs[0]
            for x in xs[1:]:
                expr = f"큰쪽({expr}, {x})"
            L += [f"{I}{{",
                  f"{I}    짧은실수 m = {expr}.",
                  f"{I}    m = 큰쪽(m, 레인에서받기(m, lane ^ 1)).",
                  f"{I}    m = 큰쪽(m, 레인에서받기(m, lane ^ 2))."]
            L += 지수식(I + "    ")
            L.append(f"{I}    Pe{b}_{h} = 비트실수(((E + 114) << 23) 으로 중간정수).")
            for i in range(4):
                for e in range(2):
                    c = 2 * h + e
                    L.append(f"{I}    중간정수 me{i}_{c} = 실수비트(곱해더하기(ep{b}_{i}_{c}, s, 8388736.0)) - 1258291200.")
            for half in range(2):
                i0, i1 = 2 * half, 2 * half + 1
                L += [f"{I}    중간정수 p01_{half} = 바이트고르기(me{i0}_{2 * h}, me{i0}_{2 * h + 1}, 20800).",
                      f"{I}    중간정수 p23_{half} = 바이트고르기(me{i1}_{2 * h}, me{i1}_{2 * h + 1}, 20800).",
                      f"{I}    ea{b}_0_{2 * half + h} = 바이트고르기(p01_{half}, p23_{half}, 21520) ^ (-2139062144).",
                      f"{I}    ea{b}_1_{2 * half + h} = 바이트고르기(p01_{half}, p23_{half}, 30258)."]
            L.append(f"{I}}}")
    # 상대(같은 질의 묶음의 다른 반쪽)에게: b = 1 − kh 의 자리 · 지수. 자리 [묶음][반쪽][자리][레지스터][레인]
    L += [f"{I}정수 교바탕 = {DG} + ((qt * 2 + kh) * 2) * 128 + lane.",
          f"{I}kh == 0이면 {{"]
    L += [f"{I}    판i[교바탕 + {자리 * 128 + k * 32}] = ea1_{자리}_{k}." for 자리 in range(2) for k in range(4)]
    L += [f"{I}    t == 0이면 {{ 판[{PE} + 내칸 + {8 * h}] = Pe1_{h}. }}" for h in range(2)]
    L += [f"{I}}}", f"{I}아니면 {{"]
    L += [f"{I}    판i[교바탕 + {자리 * 128 + k * 32}] = ea0_{자리}_{k}." for 자리 in range(2) for k in range(4)]
    L += [f"{I}    t == 0이면 {{ 판[{PE} + 내칸 + {8 * h}] = Pe0_{h}. }}" for h in range(2)]
    L += [f"{I}}}", f"{I}동기화()."]
    # 받기: 내 d 블록(b = kh)의 자리 — 키 블록 j = 1 − kh 는 상대가 만든 것, j = kh 는 내 것(ea{kh})
    L += [f"{I}정수 받바탕 = {DG} + ((qt * 2 + 1 - kh) * 2) * 128 + lane."]
    L += [f"{I}중간정수 ra_{자리}_{k} = 판i[받바탕 + {자리 * 128 + k * 32}]." for 자리 in range(2) for k in range(4)]
    L += [f"{I}짧은실수 Per{h} = 판[{PE} + 상대칸 + {8 * h}]." for h in range(2)]
    L += [f"{I}ml{h} = ml{h} + (판i[{LS} + 상대칸 + {8 * h}] 으로 정수)." for h in range(2)]
    L += [f"{I}짧은실수 l{h} = (ml{h} 으로 짧은실수) * 0.00000011920928955078125." for h in range(2)]
    L += [f"{I}중간정수 aj{j}_{자리}_{k} = 0." for j in range(2) for 자리 in range(2) for k in range(4)]
    L += [f"{I}짧은실수 Pj{j}_{h} = 영." for j in range(2) for h in range(2)]
    L += [f"{I}kh == 0이면 {{"]
    L += [f"{I}    aj0_{자리}_{k} = ea0_{자리}_{k}. aj1_{자리}_{k} = ra_{자리}_{k}." for 자리 in range(2) for k in range(4)]
    L += [f"{I}    Pj0_{h} = Pe0_{h}. Pj1_{h} = Per{h}." for h in range(2)]
    L += [f"{I}}}", f"{I}아니면 {{"]
    L += [f"{I}    aj0_{자리}_{k} = ra_{자리}_{k}. aj1_{자리}_{k} = ea1_{자리}_{k}." for 자리 in range(2) for k in range(4)]
    L += [f"{I}    Pj0_{h} = Per{h}. Pj1_{h} = Pe1_{h}." for h in range(2)]
    L += [f"{I}}}"]
    # ── 가중합: 내 d 블록의 d 조각 넷(i) × 키 블록 둘(j)
    L += [f"{I}짧은실수 uo{j}_{c} = 영." for j in range(2) for c in range(4)]
    for i in range(4):
        L.append(f"{I}정수 vw{i} = SB + {VS} + (d0 + {8 * i} + g) * 8 + t * 2.")
        for j in range(2):
            J = I + "    "
            L += [f"{I}{{"]
            for 자리 in range(2):
                L += [f"{J}중간정수 vb{자리}_0 = 판i[vw{i} + {(j * 2 + 자리) * 512}].",
                      f"{J}중간정수 vb{자리}_1 = 판i[vw{i} + {(j * 2 + 자리) * 512 + 1}]."]
            A = lambda 자리: f"aj{j}_{자리}_0, aj{j}_{자리}_1, aj{j}_{자리}_2, aj{j}_{자리}_3"
            B = lambda 자리: f"vb{자리}_0, vb{자리}_1"
            L += [f"{J}중간정수 phh{c} = 정수텐서곱({c}, {A(1)}, {B(1)}, 영i, 영i, 영i, 영i)." for c in range(4)]
            L += [f"{J}중간정수 psm{c} = 정수텐서곱({c}, {A(1)}, {B(0)}, 영i, 영i, 영i, 영i)." for c in range(4)]
            L += [f"{J}중간정수 psmb{c} = 정수텐서곱({c}, {A(0)}, {B(1)}, psm0, psm1, psm2, psm3)." for c in range(4)]
            L += [f"{J}중간정수 pll{c} = 정수텐서곱({c}, {A(0)}, {B(0)}, 영i, 영i, 영i, 영i)." for c in range(4)]
            for c in range(4):
                L += 정수곱읽기(f"uo{j}_{c}", f"phh{c}", f"psmb{c}", f"pll{c}", J, f"{c}")
            L += [f"{I}}}"]
        for c in range(4):
            h = c >> 1
            L.append(f"{I}짧은실수 o{i}_{c} = 곱해더하기(uo1_{c}, Pj1_{h}, uo0_{c} * Pj0_{h}).")
    # ── 접기
    for h in range(2):
        L += [f"{I}pq{h} >= tb이면 {{",
              f"{I}    조각 == 0이면 {{",
              f"{I}        M{h} = mx{h}.", f"{I}        L{h} = l{h}."]
        L += [f"{I}        O{i}_{c} = o{i}_{c}." for i in range(4) for c in (2 * h, 2 * h + 1)]
        L += [f"{I}    }}",
              f"{I}    아니면 {{",
              f"{I}        짧은실수 새큰 = 큰쪽(M{h}, mx{h})."]
        L += 적힌지수식("짧은실수 옛", f"M{h} - 새큰", I + "        ", f"f{h}a")
        L += 적힌지수식("짧은실수 새", f"mx{h} - 새큰", I + "        ", f"f{h}b")
        L += [f"{I}        L{h} = 곱해더하기(l{h}, 새, L{h} * 옛)."]
        L += [f"{I}        O{i}_{c} = 곱해더하기(o{i}_{c}, 새, O{i}_{c} * 옛)." for i in range(4) for c in (2 * h, 2 * h + 1)]
        L += [f"{I}        M{h} = 새큰.", f"{I}    }}", f"{I}}}"]
    L += ["        조각 < 끝조각이면 {"] + 지수풀기("조각 + 1", "1 - 버퍼", "            ") + ["        }"]
    L += ["        버퍼 = 1 - 버퍼.", "    }"]
    # ── 출력: 내 d 블록(kh) 의 O / L → c_proj 의 자리 둘 · 정보
    for h in range(2):
        L += [f"    정수 행{h} = 행바탕 + r0 + qt * 16 + g + {8 * h}.",
              f"    정수 쓰{h} = 0.", f"    r0 + qt * 16 + g + {8 * h} <= 끝r이면 {{ 쓰{h} = 1. }}",
              "    {"]
        for i in range(4):
            for e in range(2):
                L.append(f"        짧은실수 x{i}_{e} = O{i}_{2 * h + e} / L{h}.")
        xs = [f"x{i}_{e}" for i in range(4) for e in range(2)]
        expr = "큰쪽(" * (len(xs) - 1) + f"큰쪽({xs[0]}, 0.0 - {xs[0]})" + "".join(f", 큰쪽({x}, 0.0 - {x}))" for x in xs[1:])
        L += [f"        짧은실수 m = {expr}.",
              "        m = 큰쪽(m, 레인에서받기(m, lane ^ 1)).",
              "        m = 큰쪽(m, 레인에서받기(m, lane ^ 2))."]
        L += 지수식("        ")
        for i in range(4):
            for e in range(2):
                L += 넷자리식(f"x{i}_{e}", "        ", f"{i}_{e}")
        for i in range(4):
            for j in range(2):
                L += [f"        정수 반{i}_{j} = ((d{i}_0{j} & 255) | ((d{i}_1{j} & 255) << 8)) 으로 정수.",
                      f"        정수 옆{i}_{j} = 정수레인에서받기(반{i}_{j}, lane + 1).",
                      f"        (쓰{h} == 1 그리고 t % 2 == 0)이면 {{ 자릿값[({j} * 행수 + 행{h}) * {너비 // 4} + (머리 * 2 + kh) * 8 + "
                      f"{낱말위치(f'{2 * i} + t / 2')}] = (반{i}_{j} | (옆{i}_{j} << 16)) 으로 중간정수. }}"]
        L += [f"        (쓰{h} == 1 그리고 t == 0)이면 {{ 정보[(머리 * 2 + kh) * 정보폭 + 행{h}] = {마법수0()}. }}",
              "    }"]
    L.append("}")
    return L


def 정수조각계산워프(ind, QB, WB, 위치, 조각, 바탕식, 조각칸):
    """정수 KV 계약의 생성 어텐션 — 워프 하나(rl = tid % 32, rw = tid / 32)가 키 조각(위치 64 개) 하나. 값은 정수어텐션(프롬프트)과 비트까지
    같다(정수 합은 순서와 상관없고, 짧은실수 연산은 같은 식 · 같은 차례).
      점수 — 레인 r 이 키 t₀ + 2r, t₀ + 2r + 1: 자리 짝 넷을 바이트넷곱더하기(dp4a)로 블록(d 32 칸)마다 정확히 더해 정수곱읽기.
      최댓값 — 워프 셔플. 적힌지수. 합 l — 2⁻²³ 눈금의 정수를 셔플로 더해 레인 0 이.
      e′ — 값의 블록 b 마다 e · 2^(E_v − 13), 키 32 개 블록(레인 16 개)마다 지수 · 자리 둘 → 판에 값 캐시와 같은 낱말 차례로.
      가중합 — 레인 r 이 d = 2r, 2r + 1: 키 블록 j 마다 dp4a 로 정확히 → 정수곱읽기 → o = u₁·2^(E_e,1−13) + u₀·2^(E_e,0−13).
    판(낱말): q 자리 [자리 2][16] QB, 2^(E_q−13) [2] QB + 32; 워프마다 WB + rw·72: e′ 낱말 [값 블록 2][키 블록 2][자리 2][8] 64, Pe [2][2] 4.
    바깥에 있어야 하는 것: tid · rl · rw, 판 · 판i(중간정수) · 판s(짧은정수), 키바탕 · 값바탕(낱말) · 지수바탕(바이트), 키칸 · 값칸 · 키지수 · 값지수, 최대길이."""
    o = [f"{ind}정수 t0 = {조각} * 64.",
         f"{ind}정수 ta = t0 + 2 * rl.",
         f"{ind}정수 wb = {WB} + rw * 72.",
         f"{ind}짧은실수 sa = -3.0e38.",
         f"{ind}짧은실수 sb = -3.0e38."]
    o += [f"{ind}중간정수 qw{j}_{w} = 판i[{QB} + {j * 16 + w}]." for j in range(2) for w in range(16)]
    o += [f"{ind}짧은실수 pq{b} = 판[{QB} + 32 + {b}]." for b in range(2)]

    def 적재(키, 접, ind2):
        """키 하나의 자리 낱말 32 개(자리 j 는 최대길이 · 16 낱말 뒤)와 지수 — 계산보다 먼저 모두 띄운다(조각의 키는 최대길이 안이라 늘 읽을 수 있다)."""
        out = [f"{ind2}정수 kw{접} = 키바탕 + ({키}) * 16."]
        out += [f"{ind2}중간정수 k{접}_{j}_{w} = 키칸[kw{접} + {w}]." if j == 0 else
                f"{ind2}중간정수 k{접}_{j}_{w} = 키칸[kw{접} + 최대길이 * 16 + {w}]." for j in range(2) for w in range(16)]
        out += [f"{ind2}짧은실수 pk{접}_{b} = 비트실수((키지수[지수바탕 + ({키}) * 2 + {b}] 으로 중간정수) << 23)." for b in range(2)]
        return out

    def 점수(접, dst, ind2):
        out = []
        for b in range(2):
            ws = range(8 * b, 8 * b + 8)
            for nm, (ja, jb) in (("hh", (1, 1)), ("sm", (1, 0)), ("ll", (0, 0))):
                out.append(f"{ind2}중간정수 {nm}{접}_{b} = 0.")
                out += [f"{ind2}{nm}{접}_{b} = 바이트넷곱더하기(qw{ja}_{w}, k{접}_{jb}_{w}, {nm}{접}_{b})." for w in ws]
            out += [f"{ind2}sm{접}_{b} = 바이트넷곱더하기(qw0_{w}, k{접}_1_{w}, sm{접}_{b})." for w in ws]
            out += 정수곱읽기(f"짧은실수 u{접}_{b}", f"hh{접}_{b}", f"sm{접}_{b}", f"ll{접}_{b}", ind2, f"{접}_{b}")
        out += [f"{ind2}{dst} = ((u{접}_0 * pq0) * pk{접}_0).",
                f"{ind2}{dst} = 곱해더하기(u{접}_1 * pq1, pk{접}_1, {dst}) * 0.125."]
        return out
    o += 적재("ta", "a", ind) + 적재("ta + 1", "c", ind)
    o += [f"{ind}ta <= {위치}이면 {{"] + 점수("a", "sa", ind + "    ") + [f"{ind}}}"]
    o += [f"{ind}ta + 1 <= {위치}이면 {{"] + 점수("c", "sb", ind + "    ") + [f"{ind}}}"]
    o += [f"{ind}짧은실수 mx = 큰쪽(sa, sb)."]
    o += [f"{ind}mx = 큰쪽(mx, 아래에서받기(mx, {sft}))." for sft in (16, 8, 4, 2, 1)]
    o += [f"{ind}짧은실수 m = 레인에서받기(mx, 0)."]
    o += 적힌지수식("짧은실수 ea", "sa - m", ind, "ea") + 적힌지수식("짧은실수 ec", "sb - m", ind, "ec")
    o += [f"{ind}정수 ml = ((실수비트(곱해더하기(ea, 8388608.0, 8388608.0)) - 1258291200) 으로 정수) + "
          f"((실수비트(곱해더하기(ec, 8388608.0, 8388608.0)) - 1258291200) 으로 정수)."]
    o += [f"{ind}ml = ml + 정수아래에서받기(ml, {sft})." for sft in (16, 8, 4, 2, 1)]
    o += [f"{ind}짧은실수 l = (ml 으로 짧은실수) * 0.00000011920928955078125.",
          f"{ind}정수 rq = rl % 16.",
          f"{ind}정수 jj = rl / 16.",
          f"{ind}정수 e낱말 = ((rq % 8) % 4) * 2 + rq / 8.",
          f"{ind}정수 e반 = (rq % 8) / 4."]
    # e′ 의 자리 둘 — 값의 블록 b 마다, 레인 16 개(키 블록 jj)의 최댓값으로 지수
    for b in range(2):
        o += [f"{ind}{{",
              f"{ind}    짧은실수 pva = 비트실수((값지수[지수바탕 + ta * 2 + {b}] 으로 중간정수) << 23).",
              f"{ind}    짧은실수 pvc = 비트실수((값지수[지수바탕 + (ta + 1) * 2 + {b}] 으로 중간정수) << 23).",
              f"{ind}    짧은실수 epa = ea * pva.",
              f"{ind}    짧은실수 epc = ec * pvc.",
              f"{ind}    짧은실수 m = 큰쪽(epa, epc)."]
        o += [f"{ind}    m = 큰쪽(m, 레인에서받기(m, rl ^ {sft}))." for sft in (1, 2, 4, 8)]
        o += 지수식(ind + "    ")
        o += [f"{ind}    중간정수 ma = 실수비트(곱해더하기(epa, s, 8388736.0)) - 1258291200.",
              f"{ind}    중간정수 mc = 실수비트(곱해더하기(epc, s, 8388736.0)) - 1258291200.",
              f"{ind}    판s[(wb + {32 * b} + jj * 16 + e낱말) * 2 + e반] = (바이트고르기(ma, mc, 64) ^ 32896) 으로 짧은정수.",
              f"{ind}    판s[(wb + {32 * b} + jj * 16 + 8 + e낱말) * 2 + e반] = 바이트고르기(ma, mc, 81) 으로 짧은정수.",
              f"{ind}    rq == 0이면 {{ 판[wb + 64 + {2 * b} + jj] = 비트실수(((E + 114) << 23) 으로 중간정수). }}",
              f"{ind}}}"]
    o += [f"{ind}워프동기화().",
          f"{ind}정수 bq = rl / 16.",
          f"{ind}정수 eb = wb + bq * 32.",
          f"{ind}정수 vb = 값바탕 + ({조각} * 2) * 1024 + rl * 16."]
    o += [f"{ind}중간정수 ew{j}_{자리}_{w} = 판i[eb + {j * 16 + 자리 * 8 + w}]." for j in range(2) for 자리 in range(2) for w in range(8)]
    o += [f"{ind}짧은실수 Pe{j} = 판[wb + 64 + bq * 2 + {j}]." for j in range(2)]
    o += [f"{ind}중간정수 v{dd}_{j}_{자리}_{w} = 값칸[vb + {(j * 2 + 자리) * 512 + dd * 8 + w}]." for dd in range(2) for j in range(2) for 자리 in range(2) for w in range(8)]
    for dd in range(2):
        o += [f"{ind}{{"]
        for j in range(2):
            for nm, (ja, jb) in (("hh", (1, 1)), ("sm", (1, 0)), ("ll", (0, 0))):
                o.append(f"{ind}    중간정수 {nm}{j} = 0.")
                o += [f"{ind}    {nm}{j} = 바이트넷곱더하기(ew{j}_{ja}_{w}, v{dd}_{j}_{jb}_{w}, {nm}{j})." for w in range(8)]
            o += [f"{ind}    sm{j} = 바이트넷곱더하기(ew{j}_0_{w}, v{dd}_{j}_1_{w}, sm{j})." for w in range(8)]
            o += 정수곱읽기(f"짧은실수 uo{j}", f"hh{j}", f"sm{j}", f"ll{j}", ind + "    ", f"{j}")
        o += [f"{ind}    정수 바탕 = {바탕식}.",
              f"{ind}    {조각칸}[바탕 + 4 + 2 * rl + {dd}] = 곱해더하기(uo1, Pe1, uo0 * Pe0).",
              f"{ind}}}"]
    o += [f"{ind}rl == 0이면 {{",
          f"{ind}    정수 바탕 = {바탕식}.",
          f"{ind}    {조각칸}[바탕] = m.",
          f"{ind}    {조각칸}[바탕 + 1] = l.",
          f"{ind}}}",
          f"{ind}워프동기화()."]                    # 다음 조각이 e′ 자리를 덮어쓰기 전에
    return o


def 정수조각어텐션():
    """생성(문장마다 행 하나)의 어텐션 (가) — 정수 KV 계약: 블록 하나(256 스레드 = 워프 여덟)가 (행, 머리)의 키 조각 여덟 — 워프 rw 가
    조각 블록·8 + rw(정수조각계산워프). q 자리는 자릿값q · 정보q 에서(KV정수로 가 둔 것). 조각마다 (m, l, o[64]) 를 조각칸 [행][머리][조각
    (최대길이/64)][68] 에. 격자: (조각 묶음, 행 · 머리)."""
    L = ["(* 정수 KV 계약의 생성 어텐션 (가) — 블록 하나가 (행, 머리)의 키 조각 여덟(워프마다 하나). 순서 약속은 커널생성.py 의 설명 *)",
         "(* 실행한도 정수조각어텐션 256 2 *)",
         f"[중간정수 참조 자릿값q에서 중간정수 참조 정보q와 {정수KV선언()} 짧은실수 참조 조각칸에 정수 행수로 정수 묶음안행수로 "
         "정수 위치시작으로 정수 최대길이로 정수조각어텐션]는 {",
         "    정수 tid = 블록안가로().",
         "    정수 rl = tid % 32.",
         "    정수 rw = tid / 32.",
         f"    정수 행 = 블록세로() / {머리수}.",
         f"    정수 머리 = 블록세로() % {머리수}.",
         "    정수 조각 = 블록가로() * 8 + rw.",
         "    정수 위치 = 위치시작 + 행 % 묶음안행수.",
         f"    정수 머리바탕 = (행 / 묶음안행수) * {머리수} + 머리.",
         "    정수 키바탕 = 머리바탕 * 2 * 최대길이 * 16.",
         "    정수 값바탕 = 머리바탕 * (최대길이 / 32) * 1024.",
         "    정수 지수바탕 = 머리바탕 * 최대길이 * 2.",
         "    정수 정보폭 = (행수 + 63) / 64 * 64.",
         "    짧은실수 참조 판 = 공유판8().",
         "    중간정수 참조 판i = 판 으로 중간정수 참조.",
         "    짧은정수 참조 판s = 판 으로 짧은정수 참조.",
         "    짧은실수 영 = 0 으로 짧은실수.",
         f"    tid < 32이면 {{ 판i[tid] = 자릿값q[((tid / 16) * 행수 + 행) * {너비 // 4} + (머리 * 2 + (tid % 16) / 8) * 8 + tid % 8]. }}",
         f"    tid < 2이면 {{ 판[32 + tid] = 비트실수(정보q[(머리 * 2 + tid) * 정보폭 + 행] - {빼기둘}). }}",
         "    동기화().",
         "    조각 <= 위치 / 64이면 {"]
    L += 정수조각계산워프("        ", 0, 40, "위치", "조각", f"((행 * {머리수} + 머리) * (최대길이 / 64) + 조각) * 68", "조각칸")
    L += ["    }", "}"]
    return L


def 정수접기(ind, 조각칸, 바탕, 조각끝, 목적, FB):
    """빠른접기와 같은 값(같은 순서 약속)이되 지수는 적힌지수, 조각은 256 개씩 묶어 몇 묶음이든(긴 문맥 — 위치 131072 까지):
    묶음마다 누적 최댓값은 앞 묶음의 끝 값에서 잇고, L 사슬(스레드 64)과 O 사슬(스레드 d)은 레지스터로 잇는다 — 차례로 접는 것과 비트가 같다.
    판: m [256] FB, P [256] FB+256, 가 [256] FB+512, 나 [256] FB+768, L FB+1024, 앞P FB+1025, l [256] FB+1028, 워프 최댓값 [8] FB+1284."""
    FM, FP, FA, FN, FL, FPP, FLV, FW = FB, FB + 256, FB + 512, FB + 768, FB + 1024, FB + 1025, FB + 1028, FB + 1284
    out = [f"{ind}정수 조각수끝 = {조각끝} + 1.",
           f"{ind}짧은실수 L = 0 으로 짧은실수.",
           f"{ind}짧은실수 O = 0 으로 짧은실수.",
           f"{ind}정수 레인 = tid % 32.",
           f"{ind}tid == 0이면 {{ 판[{FPP}] = -3.0e38. }}",
           f"{ind}반복 (정수 c0 = 0: c0 < 조각수끝: c0 += 256) {{",
           f"{ind}    정수 c끝 = 조각수끝 - c0.",
           f"{ind}    c끝 > 256이면 {{ c끝 = 256. }}",
           f"{ind}    동기화().",
           f"{ind}    tid < c끝이면 {{",
           f"{ind}        판[{FM} + tid] = {조각칸}[{바탕} + (c0 + tid) * 68].",
           f"{ind}        판[{FLV} + tid] = {조각칸}[{바탕} + (c0 + tid) * 68 + 1].",
           f"{ind}    }}",
           f"{ind}    동기화().",
           f"{ind}    {{",
           f"{ind}        짧은실수 pv = -3.0e38.",
           f"{ind}        tid < c끝이면 {{ pv = 판[{FM} + tid]. }}"]
    for sft in (1, 2, 4, 8, 16):
        out += [f"{ind}        정수 kk{sft} = 레인 - {sft}.",
                f"{ind}        kk{sft} < 0이면 {{ kk{sft} = 레인. }}",
                f"{ind}        pv = 큰쪽(pv, 레인에서받기(pv, kk{sft}))."]
    out += [f"{ind}        레인 == 31이면 {{ 판[{FW} + tid / 32] = pv. }}",
            f"{ind}        동기화().",
            f"{ind}        반복 (정수 w = 0: w < tid / 32: w += 1) {{ pv = 큰쪽(pv, 판[{FW} + w]). }}",
            f"{ind}        pv = 큰쪽(pv, 판[{FPP}]).",
            f"{ind}        tid < c끝이면 {{ 판[{FP} + tid] = pv. }}",
            f"{ind}    }}",
            f"{ind}    동기화().",
            f"{ind}    tid < c끝이면 {{",
            f"{ind}        짧은실수 앞P = 판[{FPP}].",
            f"{ind}        tid > 0이면 {{ 앞P = 판[{FP} + tid - 1]. }}"]
    out += 적힌지수식(f"판[{FA} + tid]", f"앞P - 판[{FP} + tid]", ind + "        ", "가")
    out += 적힌지수식(f"판[{FN} + tid]", f"판[{FM} + tid] - 판[{FP} + tid]", ind + "        ", "나")
    out += [f"{ind}    }}",
            f"{ind}    동기화().",
            f"{ind}    tid == 64이면 {{",
            f"{ind}        정수 cl = 0.",
            f"{ind}        c0 == 0이면 {{ L = 판[{FLV}]. cl = 1. }}",
            f"{ind}        반복 (: cl + 7 < c끝: cl += 8) {{"]
    out += [f"{ind}            짧은실수 la{k} = 판[{FLV} + cl + {k}]." for k in range(8)]
    out += [f"{ind}            짧은실수 lb{k} = 판[{FN} + cl + {k}]." for k in range(8)]
    out += [f"{ind}            짧은실수 lc{k} = 판[{FA} + cl + {k}]." for k in range(8)]
    out += [f"{ind}            L = 곱해더하기(la{k}, lb{k}, L * lc{k})." for k in range(8)]
    out += [f"{ind}        }}",
            f"{ind}        반복 (: cl < c끝: cl += 1) {{ L = 곱해더하기(판[{FLV} + cl], 판[{FN} + cl], L * 판[{FA} + cl]). }}",
            f"{ind}    }}",
            f"{ind}    tid < 64이면 {{",
            f"{ind}        정수 c = 0.",
            f"{ind}        c0 == 0이면 {{ O = {조각칸}[{바탕} + 4 + tid]. c = 1. }}",
            f"{ind}        반복 (: c + 31 < c끝: c += 32) {{"]
    out += [f"{ind}            짧은실수 op{k} = {조각칸}[{바탕} + (c0 + c + {k}) * 68 + 4 + tid]." for k in range(32)]
    out += [f"{ind}            O = 곱해더하기(op{k}, 판[{FN} + c + {k}], O * 판[{FA} + c + {k}])." for k in range(32)]
    out += [f"{ind}        }}",
            f"{ind}        반복 (: c + 7 < c끝: c += 8) {{"]
    out += [f"{ind}            짧은실수 oo{k} = {조각칸}[{바탕} + (c0 + c + {k}) * 68 + 4 + tid]." for k in range(8)]
    out += [f"{ind}            O = 곱해더하기(oo{k}, 판[{FN} + c + {k}], O * 판[{FA} + c + {k}])." for k in range(8)]
    out += [f"{ind}        }}",
            f"{ind}        반복 (: c < c끝: c += 1) {{ O = 곱해더하기({조각칸}[{바탕} + (c0 + c) * 68 + 4 + tid], 판[{FN} + c], O * 판[{FA} + c]). }}",
            f"{ind}    }}",
            f"{ind}    동기화().",
            f"{ind}    tid == 0이면 {{ 판[{FPP}] = 판[{FP} + c끝 - 1]. }}",
            f"{ind}}}",
            f"{ind}tid == 64이면 {{ 판[{FL}] = L. }}",
            f"{ind}동기화().",
            f"{ind}tid < 64이면 {{ {목적} = O / 판[{FL}]. }}"]
    return out


def 정수조각접기():
    """생성의 어텐션 (나) — 정수 KV 계약: 블록 하나(256 스레드)가 (행, 머리) 하나, 조각들의 (m, l, o) 를 위치 순서대로 접는다(정수접기 —
    적힌지수, 조각 몇 묶음이든)."""
    L = ["(* 정수 KV 계약의 생성 어텐션 (나) — 조각들을 위치 순서대로 접는다(적힌지수). 순서 약속은 커널생성.py 의 설명 *)",
         "[짧은실수 참조 조각칸에서 짧은실수 참조 출력에 정수 행수로 정수 묶음안행수로 정수 위치시작으로 정수 최대길이로 정수조각접기]는 {",
         "    정수 tid = 블록안가로().",
         "    정수 쌍 = 블록가로().",
         f"    정수 행 = 쌍 / {머리수}.",
         f"    정수 머리 = 쌍 % {머리수}.",
         "    정수 조각끝 = (위치시작 + 행 % 묶음안행수) / 64.",
         "    정수 바탕 = 쌍 * (최대길이 / 64) * 68.",
         "    짧은실수 참조 판 = 공유판8()."]
    L += 정수접기("    ", "조각칸", "바탕", "조각끝", f"출력[행 * {너비} + 머리 * 64 + tid]", 0)
    L += ["}"]
    return L


def KV정수끝(M, N, WC):
    """_KV정수: c_attn 타일의 끝손질 — 값 y + 치우침을 32 열 블록(= 워프의 열 조각 넷)마다 자리 둘 · 지수로 바꿔, q 는 자릿값q · 정보q(활성값
    배치, 깊이 너비), 키는 키 캐시 + 키지수, 값은 값 캐시 + 값지수에(정수 KV 계약 — KV정수로 · 겔루정수끝과 같은 바꾸기). 블록의 열은 q · 키 ·
    값 중 하나(종 — 너비가 32 의 배수라 블록이 경계를 넘지 않는다).
    q · 키: 겔루정수끝처럼 워프의 판에 [자리 2][행 16][32 바이트] 로 모아 16 바이트씩 전역에(키는 위치의 행 [16 낱말] — 활성값 배치 그대로).
    값: 행 조각 16 개가 위치 16 개로 나란히 놓이면(정렬 — 위치시작 · 묶음안행수가 16 의 배수) 레인 g 짝수가 이웃 레인(g + 1)의 두 바이트를 받아
    키 넷의 낱말을 한 번에 쓰고, 아니면 바이트 하나씩 쓴다(값은 같다). 지수는 t = 0 레인이 행마다. 열수 밖의 블록(XL: 4800 열이 256 의 배수가
    아니다)은 건너뛴다."""
    L = ["    짧은정수 참조 판s = 판 으로 짧은정수 참조.",
         "    짧은실수 참조 자릿값q넓 = 자릿값q 으로 짧은실수 참조.",
         "    짧은실수 참조 키넓 = 키칸 으로 짧은실수 참조.",
         "    부호없는 작은정수 참조 값바이트 = 값칸 으로 부호없는 작은정수 참조.",
         "    정수 wb = (tid / 32) * 256.",
         "    정수 정렬 = 0.",
         "    (위치시작 % 16 == 0 그리고 (묶음안행수 % 16 == 0 또는 묶음안행수 >= 행수))이면 { 정렬 = 1. }",
         "    동기화()."]
    for m in M:
        for h in range(2):
            L.append(f"    행{m}_{h} >= 행수이면 {{ " + " ".join(f"y{m}_{n}_{2 * h + e} = 0 으로 짧은실수." for n in N for e in range(2)) + " }")
            # 행의 문장 · 위치
            L += [f"    정수 문장{m}_{h} = 0.", f"    정수 위치{m}_{h} = 위치시작 + 행{m}_{h}.",
                  f"    묶음안행수 < 행수이면 {{ 문장{m}_{h} = 행{m}_{h} / 묶음안행수. 위치{m}_{h} = 위치시작 + 행{m}_{h} % 묶음안행수. }}"]
    for m in M:
        for q in range(WC // 32):
            L += ["    {",
                  f"        정수 블록열 = 열0 + wn * {WC} + {32 * q}.",
                  f"        정수 종 = 블록열 / {너비}.",
                  f"        정수 열안 = 블록열 % {너비}.",
                  "        정수 머리 = 열안 / 64.",
                  "        정수 bb = (열안 / 32) % 2.",
                  "        블록열 < 열수이면 {"]                   # 열수 밖의 블록(3·너비가 블록 열수의 배수가 아닐 때)은 값이 쓰레기 — 아무것도 안 한다
            L += [f"        중간정수 자{h}_{i}_{j} = 0." for h in range(2) for i in range(8) for j in range(2)]
            L += [f"        정수 꽉 = 0.", f"        (정렬 == 1 그리고 행{m}_0 - g + 15 < 행수)이면 {{ 꽉 = 1. }}"]
            for h in range(2):
                r = f"행{m}_{h}"
                L.append("        {")
                for n in range(4):
                    for e in range(2):
                        i, nn, c = 2 * n + e, 4 * q + n, 2 * h + e
                        L.append(f"            짧은실수 x{i} = y{m}_{nn}_{c} + 치{nn}_{e}.")
                L.append("            짧은실수 m = " + "큰쪽(" * 7 + "큰쪽(x0, 0.0 - x0)" +
                         "".join(f", 큰쪽(x{i}, 0.0 - x{i}))" for i in range(1, 8)) + ".")
                L += ["            m = 큰쪽(m, 아래에서받기(m, 2)).", "            m = 큰쪽(m, 아래에서받기(m, 1)).",
                      "            m = 레인에서받기(m, lane - t)."]
                L += 지수식("            ")
                for i in range(8):
                    L += 넷자리식(f"x{i}", "            ", str(i))
                L += [f"            자{h}_{i}_{j} = d{i}{j}." for i in range(8) for j in range(2)]
                for n in range(4):
                    pos = f"(({2 * n} + t / 2) % 4) * 2 + {n // 2}"
                    for j in range(2):
                        L.append(f"            판s[(wb + {j * 128} + ({8 * h} + g) * 8 + {pos}) * 2 + t % 2] = "
                                 f"((d{2 * n}{j} & 255) | ((d{2 * n + 1}{j} & 255) << 8)) 으로 짧은정수.")
                # 지수(정보 · 키지수 · 값지수) 는 t = 0 레인이
                L += [f"            ({r} < 행수 그리고 t == 0)이면 {{",
                      f"                종 == 0이면 {{ 정보q[(블록열 / 32) * 정보폭 + {r}] = {마법수0()}. }}",
                      f"                아니면 종 == 1이면 {{ 키지수[((문장{m}_{h} * {머리수} + 머리) * 최대길이 + 위치{m}_{h}) * 2 + bb] = (E + 114) 으로 부호없는 작은정수. }}",
                      f"                아니면 {{ 값지수[((문장{m}_{h} * {머리수} + 머리) * 최대길이 + 위치{m}_{h}) * 2 + bb] = (E + 114) 으로 부호없는 작은정수. }}",
                      "            }"]
                # 값의 자리(바이트 쓰기 — 정렬이 아닐 때): 레인의 여덟 칸 × 자리 둘
                L += ["            (종 == 2 그리고 꽉 == 0 그리고 " + f"{r} < 행수)이면 {{",
                      f"                정수 r32 = 위치{m}_{h} % 32.",
                      "                정수 r16 = r32 % 16.",
                      "                정수 낱말 = ((r16 % 8) / 2) * 2 + r32 / 16.",
                      "                정수 바이트 = (r16 / 8) * 2 + r16 % 2.",
                      f"                정수 값바탕 = (((문장{m}_{h} * {머리수} + 머리) * (최대길이 / 32) + 위치{m}_{h} / 32) * 2) * 2048 + (bb * 32 + t * 2) * 32 + 낱말 * 4 + 바이트."]
                for n in range(4):
                    for e in range(2):
                        i = 2 * n + e
                        for j in range(2):
                            L.append(f"                값바이트[값바탕 + {j} * 2048 + {(8 * n + e) * 32}] = d{i}{j} 으로 부호없는 작은정수.")
                L.append("            }")
                L.append("        }")
            L.append("        워프동기화().")
            # q · 키: 모은 자리 두 자리 · 512 B — 조각(16 바이트) c = k·32 + lane: 자리 c/32, 행 (c%32)/2, 반쪽 c%2
            L += ["        종 < 2이면 {"]
            for k in range(2):
                L += [f"            {{",
                      f"                정수 조 = {32 * k} + lane.",
                      f"                정수 행안 = (조 % 32) / 2.",
                      f"                정수 출행 = 행0 + wm * {16 * len(M)} + {16 * m} + 행안.",
                      f"                정수 판자리 = wb + (조 / 32) * 128 + 행안 * 8 + (조 % 2) * 4.",
                      f"                출행 < 행수이면 {{",
                      f"                    정수 출문장 = 0.", f"                    정수 출위치 = 위치시작 + 출행.",
                      f"                    묶음안행수 < 행수이면 {{ 출문장 = 출행 / 묶음안행수. 출위치 = 위치시작 + 출행 % 묶음안행수. }}",
                      f"                    정수 전역 = (((조 / 32) * 행수 + 출행) * {너비 // 16} + 블록열 / 16 + 조 % 2) * 4.",
                      f"                    종 == 1이면 {{ 전역 = ((출문장 * {머리수} + 머리) * 2 + 조 / 32) * 최대길이 * 16 + 출위치 * 16 + bb * 8 + (조 % 2) * 4. }}"]
                L += [f"                    짧은실수 w{u} = 판[판자리 + {u}]." for u in range(4)]
                L += [f"                    종 == 0이면 {{ " + " ".join(f"자릿값q넓[전역 + {u}] = w{u}." for u in range(4)) + " }",
                      f"                    아니면 {{ " + " ".join(f"키넓[전역 + {u}] = w{u}." for u in range(4)) + " }",
                      "                }", "            }"]
            L += ["        }"]
            # 값 — 꽉 찬 정렬 조각이면 레인 g 짝수가 이웃(g + 1)의 바이트를 받아 키 넷의 낱말로(행 조각 16 = 위치 16 — 키 블록 안의 반쪽 h16)
            L += ["        (종 == 2 그리고 꽉 == 1)이면 {",
                  f"            정수 자리위 = 위치{m}_0 - g.",            # 행 조각의 첫 위치(16 의 배수)
                  "            정수 h16 = (자리위 % 32) / 16.",
                  f"            정수 값바탕 = ((문장{m}_0 * {머리수} + 머리) * (최대길이 / 32) + 자리위 / 32) * 1024 + (bb * 32 + t * 2) * 8 + (g / 2) * 2 + h16."]
            for n in range(4):
                for e in range(2):
                    i = 2 * n + e
                    for j in range(2):
                        L += [f"            정수 내{i}_{j} = ((자0_{i}_{j} & 255) | ((자1_{i}_{j} & 255) << 16)) 으로 정수.",
                              f"            정수 옆{i}_{j} = 정수레인에서받기(내{i}_{j}, lane + 4).",
                              f"            g % 2 == 0이면 {{ 값칸[값바탕 + {j * 512 + (8 * n + e) * 8}] = 바이트고르기(내{i}_{j} 으로 중간정수, 옆{i}_{j} 으로 중간정수, 25152). }}"]
            L.append("        }")
            L.append("        }")
            L.append("    }")
    return L


def 정수메가어텐션(J, G12, AT, G):
    """생성 메가커널의 어텐션 단계 — 정수 KV 계약(docs/17 9단계). 머리 h 는 블록 G12·h … G12·h + G12 − 1 이. (1) 블록마다 제 머리의 q 를
    자리 둘로 판에(워프 0, 레인 16 개 — 블록 둘), 마지막 조각을 맡을 블록은 새 위치의 키 · 값을 바꿔 캐시에(워프 1: 레인 0~15 키,
    16~31 값 — 값은 프롬프트의 끝손질이 쓴 것과 같다; 장벽을 더하지 않는다). (2) 워프마다 조각 하나(정수조각계산워프). (3) 조각이 넷
    이하면 블록 하나가 판 안에서 바로 접고(적힌지수), 아니면 머리마다 마지막에 도착한 블록이 정수접기로. 판(AT 부터): q 자리 34,
    워프 자리 8 × 72 (AT + 40 부터), 짧은 길의 조각칸 4 × 68 (AT + 620 부터); 정수접기는 AT 부터 1292 — 모두 AT 의 1348 안.
    긴 길에서 다음 조각의 키 · 값을 넓게미리올리기로 L2 에 미리 올리는 것은 해 봤으나 느렸다(문맥 102336 생성 9.43 → 9.54 ms/토큰, 레지스터
    넘침 8 B) — 두지 않는다."""
    K = J + "    "
    QB, WB, SC = AT, AT + 40, AT + 620
    L = [f"{J}블록 < {G12 * 머리수}이면 {{" if G12 * 머리수 < G else f"{J}{{",
         f"{K}정수 머리 = 블록 / {G12}.",
         f"{K}정수 b10 = 블록 % {G12}.",
         f"{K}정수 rl = tid % 32.",
         f"{K}정수 rw = tid / 32.",
         f"{K}정수 lane = rl.",
         f"{K}정수 조각끝 = 위치 / 64.",
         f"{K}정수 키바탕 = l * 캐시정수 + 머리 * 2 * 최대길이 * 16.",
         f"{K}정수 값바탕 = l * 캐시정수 + 머리 * (최대길이 / 32) * 1024.",
         f"{K}정수 지수바탕 = (l * 캐시문장수 * {머리수} + 머리) * 최대길이 * 2.",
         f"{K}정수 맡음 = 0.",
         f"{K}조각끝 < 4이면 {{ b10 == 0이면 {{ 맡음 = 1. }} }}",
         f"{K}아니면 {{ b10 == 조각끝 % {G12}이면 {{ 맡음 = 1. }} }}",
         # 워프 0: q 의 블록 둘(레인 0~15; 16~31 은 같은 것을 다시 — 쓰지 않는다)
         f"{K}rw == 0이면 {{",
         f"{K}    정수 xa = 머리 * 64 + ((lane / 8) % 2) * 32 + (lane % 8) * 4.",
         f"{K}    중간정수 M0 = 0."]
    L += 블록바꾸기몸(lambda i: f"질의칸[xa + {i}]", lambda j: f"정수 자{j} = 0. 자{j}", lambda v: f"M0 = {v}.", K + "    ")
    L += [f"{K}    lane < 16이면 {{"]
    L += [f"{K}        판i[{QB} + {j * 16} + (lane / 8) * 8 + {낱말위치('lane % 8')}] = 자{j}." for j in range(2)]
    L += [f"{K}        lane % 8 == 0이면 {{ 판[{QB} + 32 + lane / 8] = 비트실수(M0 - {빼기둘}). }}",
          f"{K}    }}",
          f"{K}}}",
          # 워프 1: 새 위치의 키(레인 0~15) · 값(레인 16~31)
          f"{K}(rw == 1 그리고 맡음 == 1)이면 {{",
          f"{K}    정수 bb = (lane / 8) % 2.",
          f"{K}    정수 xa = {너비} + 머리 * 64 + bb * 32 + (lane % 8) * 4.",
          f"{K}    lane >= 16이면 {{ xa = xa + {너비}. }}",
          f"{K}    중간정수 M0 = 0."]
    L += 블록바꾸기몸(lambda i: f"질의칸[xa + {i}]", lambda j: f"정수 자{j} = 0. 자{j}", lambda v: f"M0 = {v}.", K + "    ")
    L += [f"{K}    lane < 16이면 {{"]
    L += [f"{K}        키칸[키바탕 + {j} * 최대길이 * 16 + 위치 * 16 + bb * 8 + {낱말위치('lane % 8')}] = 자{j}." for j in range(2)]
    L += [f"{K}        lane % 8 == 0이면 {{ 키지수[지수바탕 + 위치 * 2 + bb] = (E + 114) 으로 부호없는 작은정수. }}",
          f"{K}    }}",
          f"{K}    아니면 {{",
          f"{K}        정수 r32 = 위치 % 32.",
          f"{K}        정수 r16 = r32 % 16.",
          f"{K}        정수 낱말 = ((r16 % 8) / 2) * 2 + r32 / 16.",
          f"{K}        정수 바이트 = (r16 / 8) * 2 + r16 % 2.",
          f"{K}        정수 d0 = bb * 32 + (lane % 8) * 4.",
          f"{K}        정수 값자리 = (값바탕 + (위치 / 32) * 1024) * 4."]
    for j in range(2):
        for i in range(4):
            L.append(f"{K}        값바이트[값자리 + {j * 2048} + (d0 + {i}) * 32 + 낱말 * 4 + 바이트] = d{i}{j} 으로 부호없는 작은정수.")
    L += [f"{K}        lane % 8 == 0이면 {{ 값지수[지수바탕 + 위치 * 2 + bb] = (E + 114) 으로 부호없는 작은정수. }}",
          f"{K}    }}",
          f"{K}}}",
          f"{K}동기화().",
          # 조각이 넷 이하: 머리의 첫 블록이 워프마다 조각 하나 — 판 안에서 바로 접는다
          f"{K}조각끝 < 4이면 {{",
          f"{K}    b10 == 0이면 {{",
          f"{K}        rw <= 조각끝이면 {{"]
    L += 정수조각계산워프(K + "            ", QB, WB, "위치", "rw", f"{SC} + rw * 68", "판")
    L += [f"{K}        }}",
          f"{K}        동기화().",
          f"{K}        tid < 64이면 {{",
          f"{K}            짧은실수 M = 판[{SC}].",
          f"{K}            짧은실수 L = 판[{SC + 1}].",
          f"{K}            짧은실수 O = 판[{SC + 4} + tid].",
          f"{K}            반복 (정수 c = 1: c <= 조각끝: c += 1) {{",
          f"{K}                정수 cb = {SC} + c * 68.",
          f"{K}                짧은실수 mc = 판[cb].",
          f"{K}                짧은실수 M2 = 큰쪽(M, mc)."]
    L += 적힌지수식("짧은실수 옛비", "M - M2", K + "                ", "가")
    L += 적힌지수식("짧은실수 새비", "mc - M2", K + "                ", "나")
    L += [f"{K}                L = 곱해더하기(판[cb + 1], 새비, L * 옛비).",
          f"{K}                O = 곱해더하기(판[cb + 4 + tid], 새비, O * 옛비).",
          f"{K}                M = M2.",
          f"{K}            }}",
          f"{K}            주의출력[머리 * 64 + tid] = O / L.",
          f"{K}        }}",
          f"{K}    }}",
          f"{K}}}",
          f"{K}아니면 {{",
          f"{K}    반복 (정수 조각0 = 0: 조각0 <= 조각끝: 조각0 += {8 * G12}) {{",
          f"{K}        정수 조각 = 조각0 + b10 + {G12} * rw.",
          f"{K}        조각 <= 조각끝이면 {{"]
    L += 정수조각계산워프(K + "            ", QB, WB, "위치", "조각", "(머리 * (최대길이 / 64) + 조각) * 68", "조각칸")
    L += [f"{K}        }}",
          f"{K}    }}",
          f"{K}    동기화().",
          f"{K}    tid == 0이면 {{",
          f"{K}        울타리().",
          f"{K}        번판[100] = 원자더하기(주의셈 에, 머리 를, 1 로).",
          f"{K}        울타리().",
          f"{K}    }}",
          f"{K}    동기화().",
          f"{K}    (번판[100] + 1) % {G12} == 0이면 {{",
          f"{K}        정수 접바탕 = 머리 * (최대길이 / 64) * 68."]
    L += 정수접기(K + "        ", "조각칸", "접바탕", "조각끝", "주의출력[머리 * 64 + tid]", AT)
    L += [f"{K}    }}",
          f"{K}}}",
          f"{J}}}"]
    return L


def 머리줄():
    head = ["(* 커널생성.py 가 만든 파일 — 고치지 말 것. 순서의 약속은 커널생성.py 의 설명 그대로. *)", "",
            "외부 [블록안가로]는 -> 정수.", "외부 [블록가로]는 -> 정수.", "외부 [블록세로]는 -> 정수.",
            ] + [f"외부 [공유판{kb}]는 -> 짧은실수 참조." for kb in ((4, 8, 12, 24, 36, 40, 48) if 작은가() else range(4, 49, 4))] + \
           ["외부 [동기화]는.",
            "외부 [짧은실수 x를 짧은실수 y를 큰쪽]는 -> 짧은실수.",
            "외부 [짧은실수 참조 판에 정수 자리를 짧은실수 참조 원본에서 정수 색인으로 비동기복사]는.",
            "외부 [짧은실수 참조 판에 정수 자리를 짧은실수 참조 원본에서 정수 색인으로 비동기복사16]는.", "외부 [비동기묶기]는.",
            "외부 [짧은실수 참조 판에 정수 자리를 짧은실수 참조 원본에서 정수 색인으로 넓게미리올리기]는.",
            "외부 [정수 n을 비동기기다리기]는.", "외부 [짧은실수 참조 원본에서 정수 색인으로 미리읽기]는.",
            "외부 [실행번호]는 -> 정수.", "외부 [실행개수]는 -> 정수.",
            "외부 [공유메모리2]는 -> 정수 참조.", "외부 [울타리]는.",
            "외부 [정수 참조 칸에 정수 i를 정수 v로 원자더하기]는 -> 정수.", "외부 [정수 참조 칸에서 정수 i로 획득읽기]는 -> 정수.",
            "외부 [짧은실수 x를 제곱근]는 -> 짧은실수.", "외부 [시각]는 -> 정수.",
            "외부 [짧은실수 v를 정수 s를 아래에서받기]는 -> 짧은실수.", "외부 [짧은실수 v를 정수 k를 레인에서받기]는 -> 짧은실수.",
            "외부 [정수 v를 정수 s를 정수아래에서받기]는 -> 정수.",
            "외부 [정수 v를 정수 k를 정수레인에서받기]는 -> 정수.", "외부 [워프동기화]는.",
            "외부 [짧은실수 x를 짧은실수 y를 짧은실수 z를 곱해더하기]는 -> 짧은실수.",
            "외부 [짧은실수 x를 근사지수]는 -> 짧은실수.", ""]
    return head


def gpt2소스():
    """gpt2.gl(GPT-2 small — 손으로 쓴 파일)과 같은 커널 넷을 지금의 크기로(7단계 — gpt2XL.gl): 임베딩, 줄층정규화(블록 하나가 한
    행), 층정규화(워프 하나가 한 행 — 줄층정규화몸), 가장큰번호. 순서 약속은 gpt2.gl 과 같다(가상 스레드 256 개, 반씩 접기)."""
    D = 너비
    L = ["(* GPT-2 의 GPU 커널 — 커널생성.py 가 gpt2.gl 과 같은 계산을 이 크기로 만든 파일. 고치지 말 것. *)", ""]
    L += [f"외부 [{n}]는 -> 정수." for n in ("실행번호", "블록안가로", "블록안세로", "블록가로", "블록세로")]
    L += ["외부 [공유메모리0]는 -> 짧은실수 참조.", "외부 [공유메모리1]는 -> 짧은실수 참조.", "외부 [공유메모리2]는 -> 정수 참조.",
          "외부 [동기화]는.", "외부 [짧은실수 v를 정수 s를 아래에서받기]는 -> 짧은실수.", "외부 [짧은실수 v를 정수 k를 레인에서받기]는 -> 짧은실수.",
          "외부 [짧은실수 x를 짧은실수 y를 짧은실수 z를 곱해더하기]는 -> 짧은실수.", "외부 [짧은실수 x를 근사지수]는 -> 짧은실수.",
          "외부 [짧은실수 x를 제곱근]는 -> 짧은실수.", "외부 [짧은실수 x를 짧은실수 y를 큰쪽]는 -> 짧은실수.", ""]
    L += ["(* 출력[r, c] = 낱말표[토큰[r], c] + 위치표[위치, c] *)",
          "[정수 참조 토큰에서 짧은실수 참조 낱말표와 짧은실수 참조 위치표와 짧은실수 참조 출력에 정수 행수로 정수 묶음안행수로 정수 위치시작으로 임베딩]는 {",
          "    정수 i = 실행번호().",
          f"    i < 행수 * {D}이면 {{",
          f"        정수 r = i / {D}.",
          f"        정수 c = i % {D}.",
          f"        출력[i] = 낱말표[토큰[r] * {D} + c] + 위치표[(위치시작 + r % 묶음안행수) * {D} + c].",
          "    }", "}", "",
          "(* 블록 하나가 한 행(256 스레드) — 아래 워프 판과 같은 순서의 약속이라 비트가 같다 (eps 1e-5) *)",
          "[짧은실수 참조 입력에서 짧은실수 참조 감마와 짧은실수 참조 베타와 짧은실수 참조 출력에 줄층정규화]는 {",
          "    정수 행 = 블록가로().",
          "    정수 tid = 블록안가로().",
          "    짧은실수 참조 칸 = 공유메모리0().",
          f"    정수 바탕 = 행 * {D}.",
          "    짧은실수 부분 = 0 으로 짧은실수.",
          f"    반복 (정수 c = tid: c < {D}: c += 256) {{ 부분 += 입력[바탕 + c]. }}",
          "    칸[tid] = 부분.",
          "    동기화().",
          "    반복 (정수 접기 = 128: 접기 > 0: 접기 /= 2) {",
          "        tid < 접기이면 { 칸[tid] = 칸[tid] + 칸[tid + 접기]. }",
          "        동기화().",
          "    }",
          f"    짧은실수 평균 = 칸[0] / {D}.0.",
          "    동기화().",
          "    짧은실수 제곱부분 = 0 으로 짧은실수.",
          f"    반복 (정수 c = tid: c < {D}: c += 256) {{",
          "        짧은실수 d = 입력[바탕 + c] - 평균.",
          "        제곱부분 += d * d.",
          "    }",
          "    칸[tid] = 제곱부분.",
          "    동기화().",
          "    반복 (정수 접기2 = 128: 접기2 > 0: 접기2 /= 2) {",
          "        tid < 접기2이면 { 칸[tid] = 칸[tid] + 칸[tid + 접기2]. }",
          "        동기화().",
          "    }",
          f"    짧은실수 역표준 = 1.0 / 제곱근(칸[0] / {D}.0 + 0.00001).",
          f"    반복 (정수 c = tid: c < {D}: c += 256) {{",
          "        출력[바탕 + c] = (입력[바탕 + c] - 평균) * 역표준 * 감마[c] + 베타[c].",
          "    }",
          "}", "",
          "(* 워프 하나가 한 행(블록 256 스레드 = 8 행) — 가상 스레드 v = l + 32k 의 부분합과 반씩 접기(줄층정규화와 같은 짝 · 순서) *)",
          "[짧은실수 참조 입력에서 짧은실수 참조 감마와 짧은실수 참조 베타와 짧은실수 참조 출력에 정수 행수로 층정규화]는 {",
          "    정수 tid = 블록안가로().",
          "    정수 행 = 블록가로() * 8 + tid / 32.",
          "    행 < 행수이면 {"]
    L += 줄층정규화몸("        ", "입력", "감마", "0", "출력", "행")
    L += ["    }", "}", "",
          "(* 문장마다 마지막 행의 로짓에서 가장 큰 칸의 번호 — 값이 같으면 작은 번호. 블록 하나가 문장 하나, 256 스레드, 열수 ≥ 256 *)",
          "[짧은실수 참조 로짓에서 정수 참조 토큰출력에 정수 묶음안행수로 정수 열수로 가장큰번호]는 {",
          "    정수 문장 = 블록가로().",
          "    정수 tid = 블록안가로().",
          "    짧은실수 참조 값들 = 공유메모리0().",
          "    정수 참조 번호들 = 공유메모리2().",
          "    정수 바탕 = (문장 * 묶음안행수 + 묶음안행수 - 1) * 열수.",
          "    짧은실수 최고 = 로짓[바탕 + tid].",
          "    정수 최고번호 = tid.",
          "    반복 (정수 j = tid + 256: j < 열수: j += 256) {",
          "        짧은실수 v = 로짓[바탕 + j].",
          "        v > 최고이면 {",
          "            최고 = v.",
          "            최고번호 = j.",
          "        }",
          "    }",
          "    값들[tid] = 최고.",
          "    번호들[tid] = 최고번호.",
          "    동기화().",
          "    tid == 0이면 {",
          "        짧은실수 큰 = 값들[0].",
          "        정수 큰번호 = 번호들[0].",
          "        반복 (정수 k는 1부터 256 전까지) {",
          "            (값들[k] > 큰 또는 (값들[k] == 큰 그리고 번호들[k] < 큰번호))이면 {",
          "                큰 = 값들[k].",
          "                큰번호 = 번호들[k].",
          "            }",
          "        }",
          "        토큰출력[문장] = 큰번호.",
          "    }",
          "}", ""]
    return "\n".join(L)


def 프롬소스():
    """프롬프트 메가커널만 담은 소스(커널프롬.gl) — 3l 의 시도. 기본 모듈(커널.gl)이 커지지 않게 따로 둔다."""
    return "\n".join(머리줄() + 프롬메가() + [""])


# 생성메가의 양자 판이 한 벌에 읽는 칸 수(두 벌을 번갈아) — 레지스터가 칸마다 Q4_0 둘 · Q8_0 셋 · F16 여덟. 블록 수 24 · 96 이
# 2·UB 로 나뉘어야 한다. 재서 정했다(5단계/README).
메가UB = {"Q4_0": 4, "Q8_0": 4, "F16": 6}
# 양자 판의 줄 판이 먼저 읽는 칸 수 — (줄선형1, 깊은줄선형1, 줄선형4). 레지스터가 칸마다 Q4_0 둘 · Q8_0 셋 · F16 여덟.
양자UB = {"Q4_0": (8, 24, 4), "Q8_0": (6, 12, 3), "F16": (4, 8, 2)}
# 만드는 모듈: 파일 → (KV 형식, 층형식, 낱말형식). Q4_0 GGUF 의 낱말표는 Q8_0 이다(llama.cpp 의 양자화가 그렇게 둔다).
모듈들 = {"커널.gl": ("짧은실수", "짧은실수", "짧은실수"), "커널반.gl": ("반실수", "짧은실수", "짧은실수"),
         "커널반F16.gl": ("반실수", "F16", "F16"), "커널반Q8.gl": ("반실수", "Q8_0", "Q8_0"), "커널반Q4.gl": ("반실수", "Q4_0", "Q8_0"),
         "커널반Q8정수.gl": ("반실수", "Q8_0", "Q8_0", "정수"), "커널반Q4정수.gl": ("반실수", "Q4_0", "Q8_0", "정수"),
         # 7단계 — GPT-2 XL (크기만 다르고 순서 약속은 같다): 짧은실수(짧은실수 KV — PyTorch 와 견줄 판) · F16 · Q8_0 · Q4_0(반실수 KV)
         "커널XL.gl": ("짧은실수", "짧은실수", "짧은실수", "가닥", "XL"), "커널XL반F16.gl": ("반실수", "F16", "F16", "가닥", "XL"),
         "커널XL반Q8정수.gl": ("반실수", "Q8_0", "Q8_0", "정수", "XL"), "커널XL반Q4정수.gl": ("반실수", "Q4_0", "Q8_0", "정수", "XL"),
         # 8단계 — 자리 둘 계약(활성값 14 비트): 같은 가중치 · 같은 커널 모양, 자리만 둘
         "커널반Q8둘자리.gl": ("반실수", "Q8_0", "Q8_0", "정수", "small", 2), "커널반Q4둘자리.gl": ("반실수", "Q4_0", "Q8_0", "정수", "small", 2),
         "커널XL반Q8둘자리.gl": ("반실수", "Q8_0", "Q8_0", "정수", "XL", 2), "커널XL반Q4둘자리.gl": ("반실수", "Q4_0", "Q8_0", "정수", "XL", 2),
         # 9단계 — 정수 KV 계약(자리 둘 + 정수 KV 캐시 + 정수 텐서 코어 어텐션 + 적힌지수)
         "커널Q8정수KV.gl": ("정수", "Q8_0", "Q8_0", "정수", "small", 2), "커널Q4정수KV.gl": ("정수", "Q4_0", "Q8_0", "정수", "small", 2),
         "커널XLQ8정수KV.gl": ("정수", "Q8_0", "Q8_0", "정수", "XL", 2), "커널XLQ4정수KV.gl": ("정수", "Q4_0", "Q8_0", "정수", "XL", 2)}


def source(kv="짧은실수", 층="짧은실수", 낱말="짧은실수", 약속="가닥", 크기="small", 자리=4):
    """크기: "small"(GPT-2 small — 이전 단계의 소스 그대로) 또는 "XL"(7단계). 자리: 정수 계약의 활성값 자리 수(4 · 2 — 8단계).
    아래 _source 의 설명."""
    global 너비, 머리수, 층수, 확장폭, 낱말수, 자리수
    너비, 머리수, 층수, 확장폭, 낱말수 = 크기들[크기]
    자리수 = 자리
    try:
        return _source(kv, 층, 낱말, 약속)
    finally:
        너비, 머리수, 층수, 확장폭, 낱말수 = 크기들["small"]
        자리수 = 4


def gpt2_source(크기="small"):
    """gpt2소스 를 크기로(XL — gpt2XL.gl). small 은 손으로 쓴 gpt2.gl 을 쓴다."""
    global 너비, 머리수, 층수, 확장폭, 낱말수
    너비, 머리수, 층수, 확장폭, 낱말수 = 크기들[크기]
    try:
        return gpt2소스()
    finally:
        너비, 머리수, 층수, 확장폭, 낱말수 = 크기들["small"]


def _source(kv="짧은실수", 층="짧은실수", 낱말="짧은실수", 약속="가닥"):
    """kv: KV 캐시의 원소 타입 — "짧은실수"(커널.gl) 또는 "반실수"(커널반.gl). 층 · 낱말: 가중치의 형식(5단계 — 커널반F16.gl ·
    커널반Q8.gl · 커널반Q4.gl). 양자 판의 모듈: 선형 판 다섯(타일선형 · 작은타일선형 · 줄선형1 · 줄선형4 · 깊은줄선형1 — 끝손질
    넷, 층형식)과 로짓용 넷(낱말형식, 끝손질 없이 — 이름 앞에 '로짓'), 임베딩, 어텐션 셋, 생성메가."""
    global KV, 층형식, 낱말형식, 계약
    KV, 층형식, 낱말형식, 계약 = kv, 층, 낱말, 약속
    head = 머리줄()
    body = []
    global 지수
    지수 = "적힌지수" if kv == "정수" else "근사지수"
    if 약속 == "정수" and kv == "정수":                 # 9단계 정수 KV 계약: 어텐션 셋이 다르고, c_attn 의 끝손질은 _KV정수(타일만 — 줄 판은 KV정수로 를 거친다)
        assert 자리수 == 2
        head += 정수머리줄()
        body += 정수로() + [""] + 층정규화정수() + [""]
        판표 = 정수판표()
        for epi in ("", "_잔차", "_겔루"):
            for 판 in 판표:
                body += 정수타일선형(epi, f"{판}{epi}", 층, 판) + [""]
            body += 정수줄선형(epi, f"정수줄선형{epi}", 층) + [""]
        for 판 in 판표:
            if 판표[판][3] >= 4:                       # _겔루정수 · _KV정수: 워프의 열이 블록(32 열)으로 나뉘는 판만
                body += 정수타일선형("_겔루정수", f"{판}_겔루정수", 층, 판) + [""]
                body += 정수타일선형("_KV정수", f"{판}_KV정수", 층, 판) + [""]
        for 판 in 판표:
            body += 정수타일선형("", f"로짓{판}", 낱말, 판) + [""]
        body += 정수줄선형("", "로짓정수줄선형", 낱말) + [""]
        body += 양자임베딩() + [""]
        body += KV정수로() + [""] + 정수어텐션() + [""] + 정수어텐션둘() + [""] + 정수조각어텐션() + [""] + 정수조각접기() + [""]
        body += 생성메가() + [""]
        KV, 층형식, 낱말형식, 계약, 지수 = "짧은실수", "짧은실수", "짧은실수", "가닥", "근사지수"
        return "\n".join(head + body)
    if 약속 == "정수":                                  # 6단계 정수 블록 계약: 활성값 바꾸기, 정수 텐서 코어 타일(모든 행 수), 로짓, 임베딩
        head += 정수머리줄()
        body += 정수로() + [""] + 층정규화정수() + [""] + 흐름어텐션(정수=True, 빠른=True) + [""]
        판표 = 정수판표()
        for epi in 끝손질들:
            for 판 in 판표:
                body += 정수타일선형(epi, f"{판}{epi}", 층, 판) + [""]
            body += 정수줄선형(epi, f"정수줄선형{epi}", 층) + [""]
        for 판 in 판표:
            if 판표[판][3] >= 4:                       # _겔루정수: 워프의 열이 블록(32 열)으로 나뉘는 판만
                body += 정수타일선형("_겔루정수", f"{판}_겔루정수", 층, 판) + [""]
        for 판 in 판표:
            body += 정수타일선형("", f"로짓{판}", 낱말, 판) + [""]
        body += 정수줄선형("", "로짓정수줄선형", 낱말) + [""]
        body += 양자임베딩() + [""]
    elif 층 == "짧은실수":
        for epi in 끝손질들:
            body += 타일선형(epi) + [""] + 타일선형(epi, 넷=True, 레지=True) + [""] + 작은타일선형(epi) + [""]
            for R in (1, 4):
                body += 줄선형(R, epi) + [""]
            body += 줄선형(1, epi, 48, 32, f"깊은줄선형1{epi}") + [""]
    else:
        u1, u48, u4 = 양자UB[층]
        for epi in 끝손질들:
            body += 양자타일선형(epi, f"타일선형{epi}") + [""] + 양자작은타일선형(epi, f"작은타일선형{epi}") + [""]
            body += 양자줄선형(1, epi, u1, f"줄선형1{epi}") + [""] + 양자줄선형(4, epi, u4, f"줄선형4{epi}") + [""]
            body += 양자줄선형(1, epi, u48, f"깊은줄선형1{epi}") + [""]
        u1, _, u4 = 양자UB[낱말]
        body += 양자타일선형("", "로짓타일선형", 낱말) + [""] + 양자작은타일선형("", "로짓작은타일선형", 낱말) + [""]
        body += 양자줄선형(1, "", u1, "로짓줄선형1", 낱말) + [""] + 양자줄선형(4, "", u4, "로짓줄선형4", 낱말) + [""]
        body += 양자임베딩() + [""]
    body += 흐름어텐션(빠른=(약속 == "정수")) + [""] + 조각어텐션() + [""] + 조각접기() + [""]
    body += 생성메가() + [""]
    KV, 층형식, 낱말형식, 계약 = "짧은실수", "짧은실수", "짧은실수", "가닥"
    return "\n".join(head + body)


def main(argv):
    if argv[:1] == ["-o"]:                               # 짧은실수 KV 판 하나만 — 대조용
        open(argv[1], "w", encoding="utf-8", newline="\n").write(source())
        print(argv[1])
        return
    for 이름, 뜻 in 모듈들.items():
        open(os.path.join(HERE, 이름), "w", encoding="utf-8", newline="\n").write(source(*뜻))
        print(os.path.join(HERE, 이름))
    open(os.path.join(HERE, "커널프롬.gl"), "w", encoding="utf-8", newline="\n").write(프롬소스())
    open(os.path.join(HERE, "gpt2XL.gl"), "w", encoding="utf-8", newline="\n").write(gpt2_source("XL"))
    print(os.path.join(HERE, "gpt2XL.gl"))


if __name__ == "__main__":
    main(sys.argv[1:])
